// Metadaten (Klassen, Schaden, Flächen) ergänzt mit Hilfe von dnd5eapi.co.
export const SPELLS = [
  {"id":"mending","name":"Ausbessern","en":"Mending","level":0,"school":"transmutation","classes":["kleriker","barde","druide","zauberer","magier","magieschmied"],"time":"1 Minute","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Dieser Zauber repariert eine Bruchstelle oder einen Riss in einem Gegenstand, den du berührst, beispielsweise ein zerbrochenes Kettenglied, einen in zwei Hälften zerbrochenen Schlüssel, einen zerrissenen Umhang oder einen leckenden Weinschlauch. Solange der Riss oder die Bruchstelle in keiner Abmessung größer als 30 Zentimeter ist, ist nicht mehr zu erkennen, dass der Gegenstand beschädigt war.","Dieser Zauber kann die physische Form eines magischen Gegenstands oder Konstrukts reparieren, jedoch nicht dessen Magie wiederherstellen."]},
  {"id":"message","name":"Botschaft","en":"Message","level":0,"school":"transmutation","classes":["barde","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"1 Runde","conc":false,"ritual":false,"desc":["Du deutest mit deinem Finger auf eine Kreatur in Reichweite und flüsterst eine Botschaft. Das Ziel (und nur dieses) hört die Botschaft und kann mit einem Flüstern antworten, das nur du hörst.","Du kannst diesen Zauber durch solide Gegenstände wirken, wenn du mit dem Ziel vertraut bist und weißt, dass es sich hinter der Barriere befindet. Magische Stille, 30 Zentimeter dicker Stein, 2,5 Zentimeter dickes gewöhnliches Metall, ein dünnes Bleiblech oder 90 Zentimeter dickes Holz blockieren den Zauber. Der Zauber muss keiner geraden Linie folgen und kann sich frei um Ecken oder durch Öffnungen bewegen."]},
  {"id":"druidcraft","name":"Druidenkunst","en":"Druidcraft","level":0,"school":"transmutation","classes":["druide"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du flüsterst den Geistern der Natur zu und erzeugst einen der folgenden magischen Effekte in Reichweite:"]},
  {"id":"minor-illusion","name":"Einfache Illusion","en":"Minor Illusion","level":0,"school":"abjuration","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"G, M","duration":"1 Minute","conc":false,"ritual":false,"area":{"shape":"cube","size":1.5},"desc":["Du erschaffst ein Geräusch oder das Abbild eines Gegenstands in Reichweite, das während der Wirkungsdauer bestehen bleibt. Der Zauber endet vorzeitig, wenn du ihn erneut wirkst oder ihn als Aktion aufhebst.","Die Lautstärke des Geräuschs kann so leise wie ein Flüstern oder so laut wie ein Schrei sein. Dies kann deine Stimme oder die einer anderen Person sein, aber auch Löwengebrüll, Trommeln oder ein anderes beliebiges Geräusch. Du kannst einen durchgehenden Laut erzeugen oder während der Wirkungsdauer unterschiedliche kurze Laute.","Das erschaffene Bild eines Gegenstands - etwa ein Stuhl, schlammige Fußabdrücke oder eine Truhe - darf nicht größer als ein Würfel mit 1,5 Metern Kantenlänge sein. Dieses Abbild kann weder Geräusche, Gerüche, Licht noch andere sensorische Effekte erzeugen. Physische Interaktionen mit dem Abbild enttarnen es als Illusion, da Dinge es einfach durchdringen können.","Eine Kreatur, die ihre Aktion verwendet, um das Geräusch oder Abbild zu untersuchen, kann einen Wurf auf Intelligenz (Nachforschungen) gegen deinen Zauberrettungswurf-SG ausführen. Erkennt eine Kreatur die Illusion als solche, wird das Abbild oder das Geräusch weniger deutlich wahrnehmbar."]},
  {"id":"fire-bolt","name":"Feuerpfeil","en":"Fire Bolt","level":0,"school":"evocation","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"attack":"ranged","damage":{"type":"fire","slots":{"0":"1d10"}},"desc":["Du schleuderst einen Funkenwirbel auf eine Kreatur oder einen Gegenstand in Reichweite. Führe einen Fernkampf-Zauberangriff gegen das Ziel aus. Bei einem Treffer erleidet das Ziel 1W10 Feuerschaden.","Der Zauber entzündet bei einem Treffer brennbare Gegenstände, die nicht getragen werden.","Der Schaden dieses Zaubers wird jeweils um 1W10 erhöht, wenn du die 5. Stufe (2W10), die 11. Stufe (3W10) und die 17. Stufe (4W10) erreichst."]},
  {"id":"produce-flame","name":"Flammen erzeugen","en":"Produce Flame","level":0,"school":"conjuration","classes":["druide"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"10 Minuten","conc":false,"ritual":false,"attack":"ranged","damage":{"type":"fire","slots":{"0":"1d8"}},"desc":["Eine flackernde Flamme erscheint in deiner Hand. Sie bleibt für die Wirkungsdauer bestehen und schadet weder dir noch deiner Ausrüstung. Die Flamme spendet in einem Radius von drei Metern helles Licht und in einem Radius von weiteren drei Metern dämmriges Licht. Der Zauber endet, wenn du ihn als Aktion beendest oder ihn erneut wirkst.","Du kannst auch mit der Flamme angreifen. Dies beendet jedoch den Zauber. Wenn du diesen Zauber wirkst oder ihn als Aktion in einem späteren Zug wirkst, kannst du die Flamme auf eine Kreatur im Abstand von bis zu neun Metern von dir schleudern. Führe einen Fernkampf-Zauberangriff aus. Bei einem Treffer erleidet das Ziel 1W8 Feuerschaden.","Der Schaden dieses Zaubers erhöht sich um je 1W8, wenn du die 5. Stufe (2W8), die 11. Stufe (3W8) und die 17. Stufe (4W8) erreichst"]},
  {"id":"vicious-mockery","name":"Gehässiger Spott","en":"Vicious Mockery","level":0,"school":"enchantment","classes":["barde"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"save":"wis","damage":{"type":"psychic","char":{"1":"1d4","5":"2d4","11":"3d4","17":"4d4"}},"desc":["Du entfesselst eine Reihe von Beleidigungen, die mit subtilen Verzauberungen durchsetzt und an eine Kreatur in Reichweite gerichtet sind, die du sehen kannst. Falls dich das Ziel hören kann - obwohl es dich nicht verstehen muss -, muss es einen Weisheitsrettungswurf bestehen, oder es erleidet 1W4 psychischen Schaden und ist beim nächsten Angriffswurf vor dem Ende seines nächsten Zugs im Nachteil.","Der Schaden dieses Zaubers steigt um je 1W4, wenn du die 5. Stufe (2W4), die 11. Stufe (3W4) und die 17. Stufe (4W4) erreichst."]},
  {"id":"poison-spray","name":"Gift versprühen","en":"Poison Spray","level":0,"school":"conjuration","classes":["zauberer","hexenmeister","magier","druide","magieschmied"],"time":"1 Aktion","action":"action","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"poison","slots":{"0":"1d12"}},"desc":["Du streckst deine Hand in Richtung einer Kreatur in Reichweite aus, die du sehen kannst, und erzeugst eine Wolke giftigen Gases aus deiner Handfläche. Die Kreatur muss einen Konstitutionsrettungswurf bestehen, oder sie erleidet 1W12 Giftschaden.","Der Schaden dieses Zaubers steigt um je 1W12, wenn du die 5. Stufe (2W12), die 11. Stufe (3W12) und die 17. Stufe (4W12) erreichst"]},
  {"id":"guidance","name":"Göttliche Führung","en":"Guidance","level":0,"school":"divination","classes":["kleriker","druide","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Du berührst eine bereitwillige Kreatur. Einmal vor dem Ende des Zaubers kann das Ziel mit einem W4 würfeln und das Ergebnis zu einem Attributswurf seiner Wahl addieren. Es kann mit dem W4 vor oder nach dem Attributswurf würfeln. Dann endet der Zauber."]},
  {"id":"sacred-flame","name":"Heilige Flamme","en":"Sacred Flame","level":0,"school":"evocation","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"radiant","slots":{"0":"1d8"}},"desc":["Ein Strahl aus gleißenden Flammen schießt auf eine Kreatur in Reichweite herab, die du sehen kannst. Das Ziel muss einen Geschicklichkeitsrettungswurf bestehen, oder es erleidet 1W8 gleißenden Schaden. Deckung bietet dem Ziel bei diesem Rettungswurf keine Vorteile.","Der Schaden des Zaubers steigt um je 1W8, wenn du die 5. Stufe (2W8), die 11. Stufe (3W8) und die 17. Stufe (4W8) erreichst."]},
  {"id":"chill-touch","name":"Kalte Hand","en":"Chill Touch","level":0,"school":"necromancy","classes":["zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"1 Runde","conc":false,"ritual":false,"attack":"ranged","damage":{"type":"necrotic","char":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}},"desc":["Du erschaffst eine geisterhafte Skeletthand im Bereich einer Kreatur in Reichweite. Führe einen Fernkampf-Zauberangriff gegen die Kreatur aus, um sie die Kälte des Grabes spüren zu lassen. Bei einem Treffer erleidet das Ziel 1W8 nekrotischen Schaden und kann bis zum Beginn deines nächsten Zugs keine Trefferpunkte zurückerhalten. Bis dahin klammert sich die Hand an das Ziel.","Triffst du ein untotes Ziel, so ist es außerdem bis zum Ende deines nächsten Zugs bei Angriffswürfen gegen dich im Nachteil.","Der Schaden dieses Zaubers erhöht sich um je 1W8, wenn du die 5. Stufe (2W8), die 11. Stufe (3W8) und die 17. Stufe (4W8) erreichst"]},
  {"id":"ray-of-frost","name":"Kältestrahl","en":"Ray of Frost","level":0,"school":"evocation","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"attack":"ranged","damage":{"type":"cold","slots":{"0":"1d8"}},"desc":["Ein eisiger Strahl blau-weißen Lichts schießt auf eine Kreatur in Reichweite. Führe einen Fernkampf-Zauberangriff gegen das Ziel aus. Bei einem Treffer erleidet es 1W8 Kälteschaden und seine Bewegungsrate ist bis zum Beginn deines nächsten Zugs um drei Meter verringert","Der Schaden des Zaubers steigt um je 1W8, wenn du die 5. Stufe (2W8), die 11. Stufe (3W8) und die 17. Stufe (4W8) erreichst."]},
  {"id":"light","name":"Licht","en":"Light","level":0,"school":"evocation","classes":["barde","kleriker","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, M","duration":"1 Stunde","conc":false,"ritual":false,"save":"dex","desc":["Du berührst einen Gegenstand, der in keiner Abmessung größer als drei Meter ist. Während der Wirkungsdauer strahlt dieser Gegenstand helles Licht in einem Radius von sechs Metern und dämmriges Licht im Radius von weiteren sechs Metern aus. Du kannst die Farbe des Lichts frei wählen. Wenn der Gegenstand mit etwas Blickdichtem abgedeckt wird, wird das Licht blockiert. Der Zauber endet vorzeitig, wenn du ihn erneut wirkst oder ihn als Aktion aufhebst.","Wählst du ein Ziel, das von einer feindlichen Kreatur gehalten oder getragen wird, muss diese einen Geschicklichkeitsrettungswurf ausführen, um den Zauber zu verhindern."]},
  {"id":"mage-hand","name":"Magierhand","en":"Mage Hand","level":0,"school":"conjuration","classes":["barde","zauberer","hexenmeister","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"1 Minute","conc":false,"ritual":false,"desc":["Eine spektrale, schwebende Hand erscheint in Reichweite an einem Punkt deiner Wahl. Die Hand bleibtwährend der Wirkungsdauer bestehen, oder bis du sie als Aktion beendest. Die Hand verschwindet, wenn sie mehr als neun Meter von dir entfernt ist oder falls du den Zauber erneut wirkst.","Du kannst eine Aktion verwenden, um die Hand zu kontrollieren. Damit kannst du mit Gegenständen interagieren, unverschlossene Türen oder Behälter öffnen, Gegenstände in einem Behälter verstauen oder daraus hervorholen oder den Inhalt einer","Phiole ausgießen. Wann immer du sie kontrollierst, kannst du sie um bis zu neun Meter bewegen.","Die Hand kann nicht angreifen, keine magischen Gegenstände aktivieren und nicht mehr als 5 Kilogramm Gewicht tragen."]},
  {"id":"acid-splash","name":"Säurespritzer","en":"Acid Splash","level":0,"school":"conjuration","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"acid","slots":{"0":"1d6"}},"desc":["Du wirfst eine Säureblase. Wähle eine oder zwei Kreaturen in Reichweite, sofern sie nicht weiter als 1,5 Meter voneinander entfernt sind. Ziele müssen einen Geschicklichkeitsrettungswurf bestehen, oder sie erleiden 1W6 Säureschaden.","Der Schaden des Zaubers steigt um je 1W6, wenn du die 5. Stufe (2W6), die 11. Stufe (3W6) und die 17. Stufe (4W6) erreichst."]},
  {"id":"shocking-grasp","name":"Schockgriff","en":"Shocking Grasp","level":0,"school":"evocation","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"attack":"melee","damage":{"type":"lightning","slots":{"0":"1d8"}},"desc":["Ein Blitz springt von deiner Hand auf eine Kreatur über, die du zu berühren versuchst, und versetzt ihr einen elektrischen Schlag. Führe einen Nahkampf-Zauberangriff gegen das Ziel aus. Du bist beim Angriffswurf im Vorteil, wenn das Ziel eine Rüstung aus Metall trägt. Bei einem Treffer erleidet das Ziel 1W8 Blitzschaden und kann erst zu Beginn seines nächsten Zugs Reaktionen ausführen.","Der Schaden des Zaubers steigt um je 1W8, wenn du die 5. Stufe (2W8), die 11. Stufe (3W8) und die 17. Stufe (4W8) erreichst."]},
  {"id":"shillelagh","name":"Shillelagh","en":"Shillelagh","level":0,"school":"transmutation","classes":["druide"],"time":"1 Bonusaktion","action":"bonus","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Minute","conc":false,"ritual":false,"desc":["Das Holz eines Knüppels oder Kampfstabs, den du in der Hand hältst, wird von der Macht der Natur erfüllt. Für die Wirkungsdauer kannst du für Angriffs- und Schadenswürfe von","Nahkampfangriffen mit dieser Waffe dein Attribut zum Zauberwirken anstatt Stärke verwenden.","Der Schadenswürfel der Waffe wird zu einem W8. Sie wird zudem magisch, falls sie es nicht bereits ist. Der Zauber endet, wenn du ihn erneut wirkst oder die Waffe loslässt."]},
  {"id":"dancing-lights","name":"Tanzende Lichter","en":"Dancing Lights","level":0,"school":"evocation","classes":["barde","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Du kannst bis zu vier Lichter in Fackelgröße in Reichweite erstellen und sie als Fackeln, Laternen oder Leuchtkugeln erscheinen lassen, die während der Wirkungsdauer in der Luft schweben. Du kannst die vier Lichter auch zu einer humanoiden Gestalt mittlerer Größe kombinieren. Jedes Licht strahlt unabhängig von der Form dämmriges Licht im Radius von drei Metern aus.","Als Bonusaktion kannst du die Lichter bis zu 18 Meter an einen neuen Ort in Reichweite bewegen. Die Lichter müssen sich im Abstand von bis zu sechs Metern zueinander befinden. Wenn sie die Reichweite des Zaubers verlassen, erlöschen sie."]},
  {"id":"prestidigitation","name":"Taschenspielerei","en":"Prestidigitation","level":0,"school":"transmutation","classes":["barde","zauberer","hexenmeister","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G","duration":"Bis zu 1 Stunde","conc":false,"ritual":false,"desc":["Dies ist ein einfacher Zaubertrick, den Zauberlehrlinge zum Üben verwenden. Du erzeugst einen der folgenden magischen Effekte in Reichweite:","Wirkst du diesen Zauber mehrmals, können bis zu drei der langfristigen Effekte gleichzeitig aktiv sein. Du kannst einen solchen Effekt als Aktion beenden."]},
  {"id":"thaumaturgy","name":"Thaumaturgie","en":"Thaumaturgy","level":0,"school":"transmutation","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V","duration":"Bis zu 1 Minute","conc":false,"ritual":false,"desc":["Du manifestierst ein kleines Wunder, ein Zeichen übernatürlicher Kraft in Reichweite. Du erzeugst einen der folgenden magischen Effekte in Reichweite:","Wenn du diesen Zauber mehrmals wirkst, können bis zu drei seiner einminütigen Effekte gleichzeitig wirken, und du kannst als Aktion einen der Effekte beenden."]},
  {"id":"eldritch-blast","name":"Unheimlicher Strahl","en":"Eldritch Blast","level":0,"school":"evocation","classes":["hexenmeister"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"attack":"ranged","damage":{"type":"force","slots":{"0":"1d10"}},"desc":["Ein Strahl aus knisternder Energie schießt auf eine Kreatur in Reichweite zu. Führe einen Fernkampf-Zauberangriff gegen das Ziel aus. Bei einem Treffer erleidet das Ziel 1W10 Energieschaden.","Auf höheren Stufen erschafft der Zauber mehr als einen Strahl: zwei Strahlen auf der 5. Stufe, drei Strahlen auf der 11. Stufe und vier Strahlen auf der 17. Stufe. Du kannst die Strahlen auf dasselbe oder auf unterschiedliche Ziele lenken. Führe für jeden Strahl einen eigenen Angriffswurf aus."]},
  {"id":"spare-the-dying","name":"Verschonung der Sterbenden","en":"Spare the Dying","level":0,"school":"necromancy","classes":["kleriker","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst eine lebende Kreatur, die 0 Trefferpunkte hat Die Kreatur wird stabil. Dieser Zauber wirkt nicht auf Untote oder Konstrukte."]},
  {"id":"resistance","name":"Widerstand (Resistenz*)","en":"Resistance","level":0,"school":"abjuration","classes":["kleriker","druide","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Du berührst eine bereitwillige Kreatur. Einmal vor dem Ende des Zaubers kann das Ziel mit einem W4 würfeln und das Ergebnis zu einem Rettungswurf seiner Wahl addieren. Der Würfel kann vor oder nach dem Rettungswurf geworfen werden. Dann endet der Zauber.","* im Spielerhandbuch ist der Zauber mit 'Resistenz' übersetzt worden"]},
  {"id":"true-strike","name":"Zielsicherer Schlag","en":"True Strike","level":0,"school":"divination","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"G","duration":"Konzentration, bis zu 1 Runde","conc":true,"ritual":false,"desc":["Du streckst deine Hand aus und deutest mit dem Finger auf ein Ziel in Reichweite. Deine Magie gewährt dir einen kurzen Einblick in die Verteidigung des Ziels. In deinem nächsten Zug bist du bei deinem ersten Angriffswurf gegen das Ziel im Vorteil, sofern dieser Zauber noch aktiv ist."]},
  {"id":"alarm","name":"Alarm","en":"Alarm","level":1,"school":"abjuration","classes":["waldlaeufer","magier","magieschmied"],"time":"1 Minute","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":true,"area":{"shape":"cube","size":6},"desc":["Du erschaffst einen Alarm gegen unerwünschtes Eindringen. Wähle eine Tür, ein Fenster oder einen Bereich in Reichweite, der nicht größer als ein Würfel von sechs Metern Kantenlänge sein darf. Bis der Zauber endet, warnt dich ein Alarm, wenn eine mindestens winzige Kreatur den geschützten Bereich berührt oder in ihn eindringt. Wenn du den Zauber wirkst, kannst du Kreaturen bestimmen, die den Alarm nicht auslösen. Du legst zudem fest, ob der Alarm mental oder hörbar ist.","Ein mentaler Alarm macht sich als Klingeln in deinem Kopf bemerkbar, wenn du dich im Abstand von bis zu 1,6 Kilometern vom geschützten Bereich befindest. Er weckt dich auch aus dem Schlaf.","Ein hörbarer Alarm erzeugt im Abstand von bis zu 18 Metern zehn Sekunden lang das Geräusch einer Handglocke."]},
  {"id":"command","name":"Befehl","en":"Command","level":1,"school":"enchantment","classes":["kleriker","paladin"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V","duration":"1 Runde","conc":false,"ritual":false,"save":"wis","desc":["Du gibst einer Kreatur in Reichweite, die du sehen kannst, einen ein Wort langen Befehl. Das Ziel muss einen Weisheitsrettungswurf bestehen oder den Befehl im nächsten Zug ausführen. Der Zauber hat keine Wirkung, wenn das Ziel untot ist, deine Sprache nicht versteht oder dein Befehl ihm direkt Schaden zufügen würde.","Im Folgenden sind einige typische Befehle und deren Effekte aufgelistet. Du kannst auch andere als die hier aufgelisteten Befehle aussprechen. In dem Fall bestimmt der SL, wie sich das Ziel verhält. Kann das Ziel deinen Befehl nicht ausführen, endet der Zauber.","Flieh: Das Ziel nutzt seinen Zug, um sich so schnell wie möglich von dir wegzubewegen.","Hinlegen: Das Ziel legt sich hin und beendet seinen Zug.","Komm: Das Ziel bewegt sich auf dem kürzesten Weg in deine Richtung und beendet seinen Zug, sobald es sich auf 1,5 Meter genähert hat.","Loslassen: Das Ziel lässt fallen, was es gerade hält, und beendet seinen Zug.","Stopp: Das Ziel bewegt sich nicht und führt keinerlei Aktionen aus. Eine fliegende Kreatur bleibt in der Luft, sofern sie dies kann. Falls sie sich bewegen muss, um in der Luft zu bleiben, fliegt sie die dazu minimal notwendige Strecke."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, kann für jeden Grad über dem 1. eine zusätzliche Kreatur betroffen sein. Die Kreaturen müssen sich im Abstand von bis zu neun Metern voneinander befinden, wenn du sie als Ziel wählst."]},
  {"id":"burning-hands","name":"Brennende Hände","en":"Burning Hands","level":1,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Kegel von 4,5 m)","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"fire","slots":{"1":"3d6"}},"area":{"shape":"cone","size":4.5},"desc":["Du streckst deine Hände mit sich berührenden Daumen und gespreizten Fingern aus und eine dünne Flammenwand schießt aus deinen Fingerspitzen hervor. Kreaturen innerhalb eines Kegels von 4,5 Metern müssen einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleiden sie 3W6 Feuerschaden, anderenfalls die Hälfte.","Das Feuer entzündet brennbare Gegenstände in der Umgebung, die nicht getragen werden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 1. um 1W6."]},
  {"id":"thunderwave","name":"Donnerwoge","en":"Thunderwave","level":1,"school":"evocation","classes":["barde","druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Würfel von 4,5 m)","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"thunder","slots":{"1":"2d8"}},"area":{"shape":"cube","size":4.5},"desc":["Eine Woge donnernder Energie bricht aus dir heraus. Alle Kreaturen in einem Würfel mit einer Kantenlänge von 4,5 Metern, der von dir ausgeht, müssen einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet eine Kreatur 2W8 Schallschaden und wird drei Meter von dir weggestoßen. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur halb so viel Schaden und wird nicht weggestoßen.","Außerdem werden ungesicherte Objekte, die sich vollständig im Wirkungsbereich befinden, durch den Effekt des Zaubers automatisch drei Meter von dir weggestoßen. Der Zauber bewirkt einen donnernden Knall, der 90 Meter weit zu hören ist."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, erhöht sich der Schaden für jeden Grad über dem 1. um 1W8."]},
  {"id":"false-life","name":"Falsches Leben","en":"False Life","level":1,"school":"necromancy","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"heal":{"slots":{"1":"1d4 + 4","2":"1d4 + 9","3":"1d4 + 14","4":"1d4 + 19","5":"1d4 + 24","6":"1d4 + 29","7":"1d4 + 34","8":"1d4 + 39","9":"1d4 + 44"}},"desc":["Du stärkst dich selbst mit einer nekromantischen Nachahmung des Lebens und erhältst für die Wirkungsdauer 1W4+4 temporäre Trefferpunkte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, erhältst du für jeden Grad über dem 1. zusätzliche 5 temporäre Trefferpunkte."]},
  {"id":"feather-fall","name":"Federfall","en":"Feather Fall","level":1,"school":"transmutation","classes":["barde","zauberer","magier","magieschmied"],"time":"1 Reaktion, die du ausführst, wenn eine Kreatur im Umkreis von 18 Meter um dich fällt","action":"reaction","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, M","duration":"1 Minute","conc":false,"ritual":false,"desc":["Wähle bis zu fünf fallende Kreaturen in Reichweite. Ihre Fallgeschwindigkeit verlangsamt sich für die Wirkungsdauer auf 18 Meter pro Runde. Landet eine Kreatur, bevor der Zauber endet, kann sie auf ihren Füßen landen und erleidet keinen Sturzschaden. Dann endet der Zauber für diese Kreatur."]},
  {"id":"faerie-fire","name":"Feenfeuer","en":"Faerie Fire","level":1,"school":"evocation","classes":["druide","magieschmied"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"dex","area":{"shape":"cube","size":6},"desc":["Jeder Gegenstand innerhalb eines würfelförmigen Bereichs mit sechs Metern Kantenlänge in Reichweite wird von blauem, grünen oder violetten Licht umrahmt - deine Wahl. Auch Kreaturen im Wirkungsbereich des Zaubers werden von diesem Licht umspielt, es sei denn, sie bestehen einen Geschicklichkeitsrettungswurf. Während der Wirkungsdauer verströmen betroffene Gegenstände und Kreaturen ein dämmriges Licht in einem Radius von drei Metern.","Angreifer sind bei Angriffswürfen gegen betroffene Kreaturen oder Gegenstände im Vorteil, wenn sie ihr Ziel sehen können. Die Ziele profitieren nicht von Unsichtbarkeit."]},
  {"id":"hideous-laughter","name":"Fürchterlicher Lachanfall","en":"Hideous Laughter","level":1,"school":"enchantment","classes":["barde","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Eine Kreatur deiner Wahl in Reichweite, die du sehen kannst, findet alles unglaublich lustig und bricht in einen Lachanfall aus, wenn dieser Zauber einen Effekt auf sie hat. Das Ziel muss einen Weisheitsrettungswurfbestehen oder es fällt für die Wirkungsdauer hin, wird kampfunfähig und kann nicht mehr aufstehen. Kreaturen mit einem Intelligenzwert von 4 oder niedriger sind nicht betroffen.","Am Ende jedes seiner Züge und jedes Mal, wenn es Schaden erleidet, kann das Ziel einen weiteren Weisheitsrettungswurf ausführen. Wird er durch Schaden ausgelöst, ist das Ziel beim Rettungswurf im Vorteil. Bei einem Erfolg endet der Zauber."]},
  {"id":"detect-poison-and-disease","name":"Gift und Krankheit entdecken","en":"Detect Poison and Disease","level":1,"school":"divination","classes":["kleriker","druide","paladin","waldlaeufer"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten Während der Wirkungsdauer nimmst du die Gegenwart und die Position von Giften, giftigen Kreaturen und Krankheiten im Abstand von bis zu neun Metern von dir wahr. Du kannst auch die Art des Gifts, der giftigen Kreatur oder der Krankheit bestimmen.","conc":true,"ritual":true,"area":{"shape":"sphere","size":9},"desc":["Dieser Zauber durchdringt die meisten Barrieren, wird aber von 30 Zentimetern Stein, 2,5 Zentimetern gewöhnlichem Metall, dünnem Bleiblech sowie von einem Meter Holz oder Erde blockiert."]},
  {"id":"divine-favor","name":"Göttliche Gunst","en":"Divine Favor","level":1,"school":"evocation","classes":["paladin"],"time":"1 Bonusaktion","action":"bonus","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"damage":{"type":"radiant","slots":{"1":"1d4"}},"desc":["Dein Gebet erfüllt dich mit göttlicher Macht Bis der Zauber endet, verursachst du mit deinen Waffenangriffen bei jedem Treffer zusätzlich 1W4 gleißenden Schaden."]},
  {"id":"goodberry","name":"Gute Beeren","en":"Goodberry","level":1,"school":"transmutation","classes":["druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Bis zu zehn Beeren erscheinen in deiner Hand und werden für die Wirkungsdauer mit Magie erfüllt. Kreaturen können als Aktion eine Beere essen. Dadurch wird 1 Trefferpunkt wiederhergestellt und die Beere versorgt die Kreatur einen Tag lang mit Nahrung.","Die Beeren verlieren ihre Wirksamkeit, wenn sie nicht innerhalb von 24 Stunden nach dem Wirken des Zaubers verzehrt werden."]},
  {"id":"detect-evil-and-good","name":"Gutes und Böses entdecken","en":"Detect Evil and Good","level":1,"school":"divination","classes":["kleriker","paladin"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"area":{"shape":"sphere","size":9},"desc":["Für die Wirkungsdauer weißt du, ob sich eine Aberration, ein celestisches Wesen, ein Elementar, ein Feenwesen, ein Unhold oder ein Untoter im Abstand von bis zu neun Metern von dir befindet, sowie wo sich die Kreatur aufhält. Gleichermaßen weißt du, ob sich im Abstand von bis zu neun Metern von dir ein Ort oder Gegenstand befindet, der magisch geweiht oder entweiht wurde.","Dieser Zauber durchdringt die meisten Barrieren, wird aber von 30 Zentimetern Stein, 2,5 Zentimetern gewöhnlichem Metall, dünnem Bleiblech sowie von einem Meter Holz oder Erde blockiert."]},
  {"id":"healing-word","name":"Heilendes Wort","en":"Healing Word","level":1,"school":"evocation","classes":["barde","kleriker","druide"],"time":"1 Bonusaktion","action":"bonus","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"heal":{"slots":{"1":"1d4 + MOD","2":"2d4 + MOD","3":"3d4 + MOD","4":"4d4 + MOD","5":"5d4 + MOD","6":"6d4 + MOD","7":"7d4 + MOD","8":"8d4 + MOD","9":"9d4 + MOD"}},"desc":["Eine Kreatur deiner Wahl in Reichweite, die du sehen kannst, gewinnt Trefferpunkte in Höhe von 1W4 + deinem Zauberwirken-Attributsmodifikator zurück. Dieser Zauber wirkt nicht auf Untote oder Konstrukte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, steigt die Heilung für jeden Grad über dem 1. um 1W4."]},
  {"id":"sanctuary","name":"Heiligtum","en":"Sanctuary","level":1,"school":"abjuration","classes":["kleriker","magieschmied"],"time":"1 Bonusaktion","action":"bonus","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"1 Minute","conc":false,"ritual":false,"desc":["Du schützt eine Kreatur in Reichweite vor Angriffen. Während der Wirkungsdauer muss jede Kreatur, die bei einem Angriff oder schädlichen Zauber die geschützte Kreatur als Ziel hat, zuerst einen Weisheitsrettungswurf bestehen. Scheitert der Wurf, muss die Kreatur ein neues Ziel wählen, oder sie verliert den Angriff oder Zauber. Dieser Zauber schützt die entsprechende Kreatur nicht vor Flächeneffekten wie der Explosion eines Feuerballs.","Greift die geschützte Kreatur an oder wirkt sie einen Zauber auf eine feindliche Kreatur, endet Heiligtum."]},
  {"id":"heroism","name":"Heldenmut","en":"Heroism","level":1,"school":"enchantment","classes":["barde","paladin"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Du berührst eine bereitwillige Kreatur und erfüllst sie mit Tapferkeit. Bis der Zauber endet, kann die Kreatur nicht verängstigt werden, und sie erhält zu Beginn jedes ihrer Züge temporäre Trefferpunkte in Höhe deines Zauberwirken-Attributsmodifikators. Wenn der Zauber endet, verliert das Ziel alle verbleibenden temporären Trefferpunkte dieses Zaubers."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, kannst du für jeden Grad über dem 1. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"hellish-rebuke","name":"Höllischer Tadel","en":"Hellish Rebuke","level":1,"school":"evocation","classes":["hexenmeister"],"time":"1 Reaktion, die du ausführst, wenn dir eine Kreatur im Umkreis von 18 Metern um dich herum Schaden zufügt, die du sehen kannst","action":"reaction","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"fire","slots":{"1":"2d10"}},"desc":["Du deutest mit deinem Finger und die Kreatur, die dich verletzt hat, wird für einen kurzen Moment von höllischen Flammen eingehüllt. Sie muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 2W10 Feuerschaden, anderenfalls die Hälfte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 1. um 1W10."]},
  {"id":"identify","name":"Identifizie ren","en":"Identify","level":1,"school":"divination","classes":["barde","magier","magieschmied"],"time":"1 Minute","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":true,"desc":["Du wählst einen Gegenstand, den du während der gesamten Wirkungsdauer des Zaubers berühren musst. Falls es ein magischer Gegenstand oder ein anderweitig magisch durchdrungenes Objekt ist, erkennst du seine Eigenschaften und ihre Anwendung, ob die Nutzung eine Einstimmung erfordert und wie viele Ladungen es besitzt, falls zutreffend. Du erfährst, ob Zauber auf das Objekt wirken, und wenn ja, welche Zauber. Falls das Objekt durch einen Zauber erzeugt wurde, erfährst du, durch welchen Zauber.","Wenn du stattdessen eine Kreatur beim Wirken des Zaubers durchgehend berührst, erfährst du, von welchen Zaubern sie derzeit betroffen ist, falls vorhanden."]},
  {"id":"illusory-script","name":"Illusionsschrift","en":"Illusory Script","level":1,"school":"illusion","classes":["barde","hexenmeister","magier"],"time":"1 Minute","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"G, M","duration":"10 Tage","conc":false,"ritual":true,"desc":["Du schreibst auf Pergament, Papier oder ein anderes passendes Material und erfüllst die Schrift mit einer mächtigen Illusion, die für die Wirkungsdauer anhält.","Für dich und alle Kreaturen, die du beim Wirken des Zaubers bestimmst, erscheint die Schrift ganz normal in deiner Handschrift und gibt den Inhalt wieder, den du niedergeschrieben hast. Für alle anderen erscheint eine unbekannte oder magische Schrift, die unverständlich ist. Alternativ kannst du die Schrift als vollständig andere Nachricht erscheinen lassen, die in einer anderen Handschrift und Sprache verfasst ist. Die Sprache muss dir jedoch bekannt sein.","Sollte der Zauber gebannt werden, verschwinden sowohl die echte Schrift als auch die Illusion.","Eine Kreatur mit wahrem Blick kann die versteckte Nachricht lesen."]},
  {"id":"longstrider","name":"Lange Schritte","en":"Longstrider","level":1,"school":"transmutation","classes":["barde","druide","waldlaeufer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Du berührst eine Kreatur. Während der Wirkungsdauer steigt die Bewegungsrate des Ziels um drei Meter."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, kannst du für jeden Grad über dem 1. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"silent-image","name":"Lautloses Trugbild","en":"Silent Image","level":1,"school":"illusion","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"area":{"shape":"cube","size":4.5},"desc":["Du erschaffst ein Abbild eines Gegenstands, einer Kreatur oder eines anderen sichtbaren Phänomens, das nicht größer als ein Würfel mit 4,5 Metern Kantenlänge sein darf. Das Abbild erscheint an einem Punkt in Reichweite und bleibt während der Wirkungsdauer bestehen. Das Abbild ist ein rein visueller Eindruck ohne Geräusche, Gerüche oder andere Sinneseffekte.","Als Aktion kannst du das Abbild an einen Ort deiner Wahl in Reichweite bewegen. Dabei kannst du das Bild so verändern, dass seine Bewegung natürlich erscheint. Beispiel: Wenn du das Abbild einer Kreatur erstellst und bewegst, kannst du es so verändern, dass es zu laufen scheint.","Physische Interaktionen mit dem Abbild enttarnen es als Illusion, da Dinge es einfach durchdringen können. Eine Kreatur, die ihre Aktion verwendet, um das Abbild zu untersuchen, kann einen Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG ausführen. Erkennt eine Kreatur die Illusion als solche, wird das Abbild für sie durchscheinend."]},
  {"id":"guiding-bolt","name":"Lenkendes Geschoss","en":"Guiding Bolt","level":1,"school":"evocation","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"1 Runde","conc":false,"ritual":false,"attack":"ranged","damage":{"type":"radiant","slots":{"1":"4d6"}},"desc":["Ein Lichtblitz schießt auf eine Kreatur deiner Wahl in Reichweite zu. Führe einen Fernkampf-Zauberangriff gegen das Ziel aus. Bei einem Erfolg erleidet das Ziel 4W6 gleißenden Schaden. Dank des mystischen dämmrigen Lichts, das auf dem Ziel glitzert, ist der nächste Angriffswurf gegen das Ziel vor Ende deines nächsten Zugs im Vorteil."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 1. um 1W6."]},
  {"id":"detect-magic","name":"Magie entdecken","en":"Detect Magic","level":1,"school":"divination","classes":["barde","kleriker","druide","paladin","waldlaeufer","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":true,"area":{"shape":"sphere","size":9},"desc":["Während der Wirkungsdauer nimmst du die Gegenwart von Magie im Abstand von bis zu neun Metern von dir wahr. Wenn du auf diese Weise Magie wahrnimmst, kannst du deine Aktion verwenden, um schwache Auren um sichtbare magische Kreaturen oder Objekte sowie ihre magische Schule zu erkennen, falls vorhanden.","Dieser Zauber durchdringt die meisten Barrieren, wird aber von 30 Zentimetern Stein, 2,5 Zentimetern gewöhnlichem Metall, dünnem Bleiblech sowie von einem Meter Holz oder Erde blockiert."]},
  {"id":"mage-armor","name":"Magierrüstung","en":"Mage Armor","level":1,"school":"abjuration","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":false,"desc":["Du berührst eine willige Kreatur, die keine Rüstung trägt. Sie wird von einer schützenden magischen Energie umgeben, bis der Zauber endet. Die Basis-Rüstungs klasse des Ziels beträgt 13 + sein Geschicklichkeitsmodifikator. Der Zauber endet vorzeitig, wenn das Ziel eine Rüstung anlegt oder du den Zauber als Aktion beendest"]},
  {"id":"magic-missile","name":"Magisches Geschoss","en":"Magic Missile","level":1,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du erschaffst drei leuchtende Wurfpfeile aus magischer Energie. Jeder Pfeil trifft eine Kreatur deiner Wahl in Reichweite, die du sehen kannst Ein Pfeil fügt seinem Ziel 1W4+1 Energieschaden zu. Die Wurfpfeile treffen alle gleichzeitig und du kannst bestimmen, ob sie dieselbe oder verschiedene Kreaturen treffen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, wird pro Grad über dem 1. ein weiterer Pfeil erschaffen."]},
  {"id":"speak-with-animals","name":"Mit Tieren sprechen","en":"Speak with Animals","level":1,"school":"divination","classes":["barde","druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"10 Minuten","conc":false,"ritual":true,"desc":["Für die Wirkungsdauer kannst du Tiere verstehen und verbal mit ihnen kommunizieren. Das Wissen und die Wahrnehmung vieler Tiere wird durch ihre Intelligenz eingeschränkt. Sie sind jedoch zumindest in der Lage, Informationen über nahe Orte und Monster mitzuteilen - sowie über Ereignisse, die sie wahrnehmen können oder innerhalb des letzten Tages erlebt haben. Nach Ermessen des SL kannst du ein Tier überreden, dir einen kleinen Gefallen zu erweisen."]},
  {"id":"purify-food-and-drink","name":"Nahrung und Wasser reinigen","en":"Purify Food and Drink","level":1,"school":"transmutation","classes":["kleriker","druide","paladin","magieschmied"],"time":"1 Aktion","action":"action","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":true,"desc":["Alle nichtmagischen Nahrungsmittel und Getränke in einer Sphäre mit einem Radius von 1,5 Metern, die auf einen Punkt deiner Wahl in Reichweite zentriert ist, werden von Giften und Krankheiten gereinigt."]},
  {"id":"fog-cloud","name":"Nebelwolke","en":"Fog Cloud","level":1,"school":"conjuration","classes":["druide","waldlaeufer","zauberer","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"area":{"shape":"sphere","size":6},"desc":["Du erschaffst eine Sphäre aus Nebel mit einem Radius von sechs Metern an einem Ort in Reichweite.","Die Sphäre breitet sich um Ecken aus und ihr Bereich ist komplett verschleiert Sie bleibt für die Wirkungsdauer bestehen oder bis ein mäßiger oder stärkerer Wind (mindestens 16 Kilometer pro Stunde) den Nebel auflöst Auf höheren Graden: Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, steigt der Radius des Nebels für jeden Grad über dem 1. um sechs Meter."]},
  {"id":"charm-person","name":"Person bezaubern","en":"Charm Person","level":1,"school":"enchantment","classes":["barde","druide","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"1 Stunde","conc":false,"ritual":false,"save":"wis","desc":["Du versuchst, einen Humanoiden in Reichweite zu bezaubern, den du sehen kannst. Er muss einen Rettungswurf auf Weisheit ausführen. Dabei ist er im Vorteil, wenn du oder deine Begleiter gegen ihn kämpft. Scheitert der Wurf, ist der Humanoide von dir bezaubert, bis der Zauber endet oder du und deine Begleiter dem Humanoiden Schaden zufügt. Die bezauberte Kreatur betrachtet dich als freundlichen Bekannten. Nach Ende des Zaubers weiß die Kreatur, dass sie von dir bezaubert wurde."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, kannst du für jeden Grad über dem 1. eine zusätzliche Kreatur als Ziel wählen. Die Kreaturen müssen sich im Abstand von bis zu neun Metern voneinander befinden, wenn du sie als Ziel wählst."]},
  {"id":"expeditious-retreat","name":"Rascher Rückzug","en":"Expeditious Retreat","level":1,"school":"transmutation","classes":["zauberer","hexenmeister","magier","magieschmied"],"time":"1 Bonusaktion","action":"bonus","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Mit diesem Zauber kannst du dich mit unglaublicher Geschwindigkeit bewegen. Wenn du diesen Zauber wirkst, sowie als Bonusaktion in jedem deiner Züge während der Wirkungsdauer, kannst du die Spurt-Aktion verwenden."]},
  {"id":"shield","name":"Schild","en":"Shield","level":1,"school":"abjuration","classes":["zauberer","magier"],"time":"1 Reaktion, die du ausführst, wenn du von einem Angriff getroffen oder als Ziel für den Zauber ","action":"reaction","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"1 Runde","conc":false,"ritual":false,"desc":["Eine unsichtbare Barriere aus magischer Energie erscheint und schützt dich. Bis zum Beginn deines nächsten Zuges hast du einen Bonus von +5 auf RK, auch gegen den auslösenden Angriff, und du erleidest keinen Schaden durch Magisches Geschoss."]},
  {"id":"shield-of-faith","name":"Schild des Glaubens","en":"Shield of Faith","level":1,"school":"abjuration","classes":["kleriker","paladin"],"time":"1 Bonusaktion","action":"bonus","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Ein schimmerndes Feld erscheint, umgibt eine Kreatur deiner Wahl in Reichweite und gewährt ihr für die Wirkungsdauer einen Bonus von +2 auf ihre RK."]},
  {"id":"sleep","name":"Schlaf","en":"Sleep","level":1,"school":"enchantment","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G, M","duration":"1 Minute","conc":false,"ritual":false,"area":{"shape":"sphere","size":6},"desc":["Dieser Zauber versetzt Kreaturen in einen magischen Schlaf. Würfle mit fünf W8. Die Summe gibt an, auf wie viele Trefferpunkte an Kreaturen dieser Zauber wirken kann. Kreaturen im Abstand von bis zu sechs Metern um einen Punkt deiner Wahl in Reichweite sind in aufsteigender Reihenfolge ihrer aktuellen Trefferpunkte betroffen (bewusstlose Kreaturen werden ignoriert).","Beginnend mit der Kreatur mit den niedrigsten aktuellen Trefferpunkten verliert jede Kreatur, auf die der Zauber wirkt, das Bewusstsein. Dieser Zustand hält an, bis die Wirkungsdauer endet, der Schlafende Schaden erleidet oder jemand den Schlafenden mit einer Aktion aufweckt. Subtrahiere die Trefferpunkte jeder Kreatur von der Summe, bevor du zur Kreatur mit den nächstniedrigsten Trefferpunkten übergehst. Die Trefferpunkte einer Kreatur müssen kleiner oder gleich der verbleibenden Summe sein, damit der Zauber auf die Kreatur wirkt.","Der Zauber wirkt nicht auf Untote und Kreaturen, die nicht bezaubert werden können."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, würfle für jeden Grad über dem 1. zusätzlich mit zwei W8."]},
  {"id":"grease","name":"Schmieren","en":"Grease","level":1,"school":"conjuration","classes":["magier","magieschmied"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"1 Minute","conc":false,"ritual":false,"save":"dex","area":{"shape":"cube","size":3},"desc":["Schmieriges Fett bedeckt den Boden in einem würfelförmigen Bereich mit drei Metern Kantenlänge, der um einen Punkt in Reichweite zentriert ist, und macht ihn für die Wirkungsdauer zu schwierigem Gelände.","Wenn das Schmierfett erscheint, muss jede Kreatur, die in diesem Bereich steht, einen Geschicklichkeitsrettungswurf bestehen, um nicht hinzufallen. Kreaturen, die den Bereich betreten oder ihren Zug darin beginnen, müssen ebenfalls einen Geschicklichkeitsrettungswurf bestehen, oder sie rutschen aus und sind liegend."]},
  {"id":"protection-from-evil-and-good","name":"Schutz vor Gut und Böse","en":"Protection from Evil and Good","level":1,"school":"abjuration","classes":["kleriker","paladin","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten Bis der Zauber endet, ist eine willige Kreatur, die du berührst, vor bestimmten Kreaturentypen geschützt: vor Aberrationen, celestischen Wesen, Feenwesen, Unholden und Untoten.","conc":true,"ritual":false,"desc":["Der Schutz gewährt mehrere Vorteile. Angriffswürfe von Kreaturen dieses Typs sind bei Angriffen auf das Ziel im Nachteil. Das Ziel kann auch nicht von ihnen besessen, bezaubert oder verängstigt sein. Ist das Ziel bereits von einer solchen Kreatur besessen, bezaubert oder verängstigt, ist das Ziel bei jedem neuen Rettungswurf gegen den entsprechenden Effekt im Vorteil."]},
  {"id":"floating-disk","name":"Schwebende Scheibe","en":"Floating Disk","level":1,"school":"conjuration","classes":["magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":true,"desc":["Dieser Zauber erschafft eine kreisförmige, waagrechte Fläche aus Energie mit 90 Zentimetern Durchmesser und 2,5 Zentimetern Dicke. Sie schwebt an einer freien Stelle deiner Wahl in Reichweite, die du sehen kannst, 90 Zentimeter über dem Boden. Die Scheibe bleibt für die Wirkungsdauer bestehen und kann bis zu 250 Kilogramm tragen. Lastet mehr Gewicht auf ihr, endet der Zauber, und alles auf der Scheibe fällt zu Boden.","Die Scheibe ist unbeweglich, wenn du dich im Abstand von bis zu sechs Metern von ihr befindest. Entfernst du dich mehr als sechs Meter von ihr, folgt dir die Scheibe, so dass sie im Abstand von bis zu sechs Metern von dir bleibt. Sie kann sich über unebenes Gelände, Treppen, Abhänge und dergleichen bewegen, kann jedoch keinen Höhenunterschied von drei Metern oder mehr überwinden. Beispielsweise kann die Scheibe nicht über eine drei Meter tiefe Grube hinwegschweben oder eine derartige Grube verlassen, falls sie in ihr erschaffen wurde.","Entfernst du dich mehr als 30 Meter von der Scheibe (meist, weil sie sich nicht um ein Hindernis bewegen kann, um dir zu folgen), endet der Zauber."]},
  {"id":"bless","name":"Segnen","en":"Bless","level":1,"school":"enchantment","classes":["kleriker","paladin"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Du segnest bis zu drei Kreaturen deiner Wahl in Reichweite. Wenn ein Ziel während der Wirkungsdauer einen Angriffs- oder Rettungswurf ausführt, darf es mit einem W4 würfeln und das Würfelergebnis zu seinem Angriffs- oder Rettungswurf addieren."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, kannst du für jeden Grad über dem 1. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"disguise-self","name":"Selbstverkleidung","en":"Disguise Self","level":1,"school":"illusion","classes":["barde","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Verändere dein Aussehen einschließlich Kleidung, Rüstung, Waffen und anderer Habseligkeiten, bis der Zauber endet oder du deine Aktion verwendest, um ihn zu beenden. Du kannst 30 Zentimeter größer oder kleiner sowie dick, dünn oder normal erscheinen. Deinen Körpertyp kannst du nicht verändern, musst also eine Form mit der gleichen Grundanordnung von Gliedmaßen annehmen. Abgesehen davon sind Form und Ausmaß der Illusion dir überlassen.","Einer genauen körperlichen Untersuchung halten die Veränderungen dieser Illusion nicht stand. Nutzt du diesen Zauber beispielsweise, um dir einen Hut aufzusetzen, durchdringen Gegenstände diesen einfach. Will jemand den Hut berühren, fühlt er dort nichts außer deinen Haaren und deinem Kopf. Lässt du dich durch den Zauber dünner erscheinen, würde eine nach dir greifende Hand schon mit dir kollidieren, wenn sie noch in der Luft zu sein scheint","Eine Kreatur kann deine Verkleidung als solche erkennen, wenn sie mit ihrer Aktion dein Aussehen untersucht und einen Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG besteht."]},
  {"id":"comprehend-languages","name":"Sprachen verstehen","en":"Comprehend Languages","level":1,"school":"divination","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":true,"desc":["Für die Wirkungsdauer verstehst du die wörtliche Bedeutung jeder gesprochenen Sprache, die du hörst Außerdem verstehst du jede Schriftsprache, die du liest, sofern du die Oberfläche berührst, auf der die Worte geschrieben stehen. Eine Seite Text zu lesen dauert etwa eine Minute.","Dieser Zauber entschlüsselt weder Geheimbotschaften in Texten noch Glyphen wie arkane Siegel, die nicht Teil der geschriebenen Sprache sind."]},
  {"id":"jump","name":"Springen","en":"Jump","level":1,"school":"transmutation","classes":["druide","waldlaeufer","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Minute","conc":false,"ritual":false,"desc":["Du berührst eine Kreatur. Die Sprungdistanz der Kreatur wird bis zum Ende des Zaubers verdreifacht."]},
  {"id":"color-spray","name":"Sprühende Farben","en":"Color Spray","level":1,"school":"illusion","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Kegel von 4,5 m)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"1 Runde","conc":false,"ritual":false,"area":{"shape":"cone","size":4.5},"desc":["Schillernde, bunte Lichter entspringen deiner Hand. Würfle 6W10. Die Summe gibt an, auf wie viele Trefferpunkte an Kreaturen dieser Zauber wirken kann. Kreaturen in einem von dir ausgehenden Kegel von 4,5 Metern sind in aufsteigender Reihenfolge ihrer aktuellen Trefferpunkte betroffen (bewusstlose Kreaturen und Kreaturen, die nicht sehen können, werden ignoriert).","Beginnend mit der Kreatur mit den niedrigsten aktuellen Trefferpunkten wird jede Kreatur, auf die der Zauber wirkt, bis zum Ende der Wirkungsdauer blind. Subtrahiere die Trefferpunkte jeder Kreatur von der Summe, bevor du zur Kreatur mit den nächstniedrigsten Trefferpunkten übergehst. Die Trefferpunkte einer Kreatur müssen kleiner oder gleich der verbleibenden Summe sein, damit der Zauber auf die Kreatur wirkt."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, würfle für jeden Grad über dem 1. zusätzlich mit 2W10."]},
  {"id":"animal-friendship","name":"Tierfreundschaft","en":"Animal Friendship","level":1,"school":"enchantment","classes":["barde","druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":false,"save":"wis","desc":["Mit diesem Zauber kannst du ein Tier davon überzeugen, dass du ihm nichts Böses willst. Wähle ein Tier in Reichweite, das du sehen kannst. Es muss dich sehen und hören können. Wenn die Intelligenz des Tiers mindestens 4 beträgt, schlägt der Zauber fehl. Anderenfalls muss das Tier einen Weisheitsrettungswurf ausführen oder es wird für die Wirkungsdauer des Zaubers von dir bezaubert. Wenn du oder einer deiner Begleiter das Ziel verletzt, endet der Zauber."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, kann für jeden Grad über dem 1. ein zusätzliches Tier betroffen sein."]},
  {"id":"unseen-servant","name":"Unsichtbarer Diener","en":"Unseen Servant","level":1,"school":"conjuration","classes":["barde","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":true,"desc":["Dieser Zauber erschafft eine unsichtbare, geist-und formlose Kraft, die auf deinen Befehl einfache Aufgaben erfüllt, bis der Zauber endet. Der Diener erscheint in einem freien Bereich in Reichweite auf dem Boden. Er besitzt eine RK von 10, einen Stärkewert von 2,1 Trefferpunkt und kann nicht angreifen. Wenn seine Trefferpunkte auf 0 sinken, endet der Zauber.","Als Bonusaktion kannst du in jedem deiner Züge dem Diener mental befehlen, sich bis zu 4,5 Meter zu bewegen und mit einem Gegenstand zu interagieren. Der Diener kann einfache Aufgaben übernehmen, die auch ein menschlicher Diener ausführen könnte: Er kann Dinge holen, reinigen und reparieren, Kleidung Zusammenlegen, Feuer entfachen, Essen servieren und Wein einschenken. Sobald du einen Befehl erteilst, erfüllt der Diener diesen nach Kräften, bis die Aufgabe erledigt ist Dann wartet er auf deinen nächsten Befehl.","Befiehlst du dem Diener, sich für eine Aufgabe mehr als 18 Meter von dir zu entfernen, endet der Zauber."]},
  {"id":"bane","name":"Verderben","en":"Bane","level":1,"school":"enchantment","classes":["barde","kleriker"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"cha","desc":["Bis zu drei Kreaturen deiner Wahl in Reichweite, die du sehen kannst, müssen Charismarettungswürfe ausführen. Wenn ein Ziel, das diesen Rettungswurf nicht besteht, während der Wirkungsdauer einen Angriffs- oder Rettungswurf ausführt, muss es einen W4 würfeln und das Würfelergebnis von seinem Angriffs- oder Rettungswurf abziehen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, kannst du für jeden Grad über dem 1. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"entangle","name":"Verstricken","en":"Entangle","level":1,"school":"conjuration","classes":["druide"],"time":"1 Aktion","action":"action","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"str","area":{"shape":"cube","size":6},"desc":["Unkraut und Ranken wachsen in einem viereckigen Bereich mit sechs Metern Kantenlänge in Reichweite aus dem Boden. Während der Wirkungsdauer verwandeln diese Pflanzen den Boden im Bereich in schwieriges Gelände.","Jede Kreatur, die sich in dem Bereich aufhält, wenn du den Zauber wirkst, muss einen Stärkerettungswurf bestehen, anderenfalls wird sie von den umschlingenden Pflanzen festgesetzt, bis der Zauber endet. Eine von den Pflanzen festgesetzte Kreatur kann als Aktion einen Stärkewurf gegen deinen Zauberrettungswurf-SG ausführen. Bei einem Erfolg befreit sie sich.","Wenn der Zauber endet, verwelken die beschworenen Pflanzen."]},
  {"id":"find-familiar","name":"Vertrauten finden","en":"Find Familiar","level":1,"school":"conjuration","classes":["magier"],"time":"1 Stunde","action":"long","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":true,"desc":["Du erhältst die Dienste eines Vertrauten. Dabei handelt es sich um einen Geist, der die Gestalt eines Tiers deiner Wahl annimmt: Eidechse, Eule, Falke, Fisch (Quipper) Fledermaus, Frosch (Kröte), Giftschlange, Katze, Krabbe, Oktopus, Rabe, Ratte, Seepferdchen, Spinne oder Wiesel. Der Vertraute erscheint an einer freien Stelle in Reichweite.","Er besitzt die Spielwerte der gewählten Gestalt, ist jedoch ein celestisches Wesen, ein Feenwesen oder ein Unhold (deine Wahl) und kein Tier.","Dein Vertrauter agiert unabhängig von dir, befolgt aber immer deine Befehle. Im Kampf würfelt er seine eigene Initiative aus und hat seinen eigenen Zug. Ein Vertrauter kann nicht angreifen, kann jedoch andere Aktionen wie gewohnt ausführen.","Sinken die Trefferpunkte des Vertrauten auf 0, verschwindet er und hinterlässt keine physische Form. Er erscheint wieder, wenn du den Zauber erneut wirkst.","Während sich dein Vertrauter im Abstand von bis zu 30 Metern von dir aufhält, kannst du telepathisch mit ihm kommunizieren. Zudem kannst du als Aktion bis zum Beginn deines nächsten Zugs durch die Augen deines Vertrauten sehen und hören, was er hört. Dabei erhältst du etwaige Spezialsinne des Vertrauten. Währenddessen bist du blind und taub, was deine eigenen Sinne betrifft.","Als Aktion kannst du deinen Vertrauten kurzzeitig fortschicken. Er verschwindet in eine Taschendimension, wo er auf deinen Ruf wartet. Alternativ kannst du ihn für immer fortschicken. Solange dein Vertrauter kurzzeitig fortgeschickt ist, kannst du ihn als Aktion an einer freien Stelle im Abstand von bis zu neun Metern von dir erscheinen lassen.","Du kannst maximal einen Vertrauten gleichzeitig haben. Wirkst du diesen Zauber, während du bereits einen Vertrauten hast, lässt du ihn stattdessen eine neue Gestalt annehmen. Wähle eine aus der Liste weiter oben aus. Dein Vertrauter verwandelt sich in die gewählte Kreatur.","Wirkst du zudem einen Zauber mit Berührungsreichweite, kann dein Vertrauter den Zauber ausführen, als hättest du ihn gewirkt. Dein Vertrauter muss sich im Abstand von bis zu 30 Metern von dir befinden und muss seine Reaktion verwenden, um den Zauber auszuführen, wenn du ihn wirkst. Erfordert der Zauber einen Angriffswurf, verwende deinen Angriffsmodifikator."]},
  {"id":"create-or-destroy-water","name":"Wasser erschaffen oder zerstören","en":"Create or Destroy Water","level":1,"school":"transmutation","classes":["kleriker","druide"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"area":{"shape":"cube","size":9},"desc":["Du erschaffst oder zerstörst Wasser.","Wasser erschaffen: Du erschaffst bis zu 40 Liter sauberes Wasser in einem offenen Behälter in Reichweite. Alternativ fällt das Wasser als Regen in einem Würfel mit neun Metern Kantenlänge in Reichweite und löscht offene Flammen in dem Bereich.","Wasser zerstören: Du zerstörst bis zu 40 Liter Wasser in einem offenen Behälter in Reichweite. Alternativ zerstörst du Nebel in einem Würfel mit neun Metern Kantenlänge in Reichweite."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, kannst du für jeden Grad über dem 1. zusätzliche 40 Liter Wasser erschaffen oder zerstören, oder die Kantenlänge des Würfels um 1,5 Meter vergrößern."]},
  {"id":"cure-wounds","name":"Wunden heilen","en":"Cure Wounds","level":1,"school":"evocation","classes":["barde","kleriker","druide","paladin","waldlaeufer","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"heal":{"slots":{"1":"1d8 + MOD","2":"2d8 + MOD","3":"3d8 + MOD","4":"4d8 + MOD","5":"5d8 + MOD","6":"6d8 + MOD","7":"7d8 + MOD","8":"8d8 + MOD","9":"9d8 + MOD"}},"desc":["Eine Kreatur, die du berührst, gewinnt Trefferpunkte in Höhe von 1W8 + deinem Attributsmodifikator im Zauberwirken zurück. Dieser Zauber wirkt nicht auf Untote oder Konstrukte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, steigt die Heilung für jeden Grad über dem 1. um 1W8."]},
  {"id":"inflict-wounds","name":"Wunden verursachen","en":"Inflict Wounds","level":1,"school":"necromancy","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"attack":"melee","damage":{"type":"necrotic","slots":{"1":"3d10","2":"4d10","3":"5d10","4":"6d10","5":"7d10","6":"8d10","7":"9d10","8":"10d10","9":"11d10"}},"desc":["Führe einen Nahkampf-Zauberangriff gegen eine Kreatur innerhalb deiner Reichweite aus. Bei einem Treffer erleidet das Ziel 3W10 nekrotischen Schaden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 2. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 1. um 1W10."]},
  {"id":"hunters-mark","name":"Zeichen des Jägers","en":"Hunter's Mark","level":1,"school":"divination","classes":["waldlaeufer"],"time":"1 Bonusaktion","action":"bonus","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du wählst eine Kreatur in Reichweite, die du sehen kannst, und markierst sie auf mystische Weise als deine Beute. Bis der Zauber endet, fügst du dem Ziel bei jedem Treffer mit einem Waffenangriff zusätzliche 1W6 Schaden zu. Zudem bist du bei Weisheitswürfen (Wahrnehmung) oder Weisheitswürfen (Überlebenskunst), um das Ziel ausfindig zu machen, im Vorteil. Sinken die Trefferpunkte des Ziels auf 0, bevor der Zauber endet, kannst du in darauffolgenden Zügen eine Bonusaktion verwenden, um eine neue Kreatur zu markieren."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. oder 4. Grades nutzt, kannst du die Konzentration auf diesen Zauber bis zu acht Stunden aufrechterhalten. Bei einem Zauberplatz des 5. Grades oder höher kannst du die Konzentration auf diesen Zauber bis zu 24 Stunden aufrechterhalten."]},
  {"id":"arcane-lock","name":"Arkanes Schloss","en":"Arcane Lock","level":2,"school":"abjuration","classes":["magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":false,"desc":["Wenn du eine Tür, ein Fenster oder Tor, eine Truhe oder einen anderen Eingang berührst, der geschlossen ist, wird er für die Wirkungsdauer verschlossen. Du und alle Kreaturen, die du beim Wirken des Zaubers bestimmst, könnt das Objekt normal öffnen. Du kannst auch ein Kennwort festlegen, das diesen Zauber eine Minute lang innerhalb eines Radius von 1,5 Metern unterdrückt. Der Durchgang ist nicht passierbar, bis der Zauber gebannt oder unterdrückt wird. Wird Klopfen auf das Objekt gewirkt, so wird Arkanes Schloss zehn Minuten lang unterdrückt.","Unter diesem Zauber ist das Objekt schwieriger aufzubrechen oder aufzuzwingen. Der SG ist entsprechend um 10 erhöht."]},
  {"id":"enhance-ability","name":"Attribut verbessern","en":"Enhance Ability","level":2,"school":"transmutation","classes":["barde","kleriker","druide","zauberer","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"heal":{"dice":"2d6","mod":false},"desc":["Du berührst eine Kreatur und verleihst ihr eine magische Verbesserung. Wähle einen der folgenden Effekte aus. Das Ziel erhält diesen Effekt, bis der Zauber endet.","Anmut der Katze: Das Ziel ist bei Geschicklichkeitswürfen im Vorteil. Es erleidet zudem keinen Schaden bei Stürzen aus maximal sechs Metern, solange es nicht kampfunfähig ist.","Ausdauer des Bären: Das Ziel ist bei Konstitutionswürfen im Vorteil. Es erhält zudem 2W6 temporäre Trefferpunkte, die verschwinden, wenn der Zauber endet.","Gerissenheit des Fuchses: Das Ziel ist bei Intelligenz würfen im Vorteil.","Pracht des Adlers: Das Ziel ist bei Charismawürfen im Vorteil.","Stärke des Stiers: Das Ziel ist bei Stärkewürfen im Vorteil und seine Traglast verdoppelt sich.","Weisheit der Eule: Das Ziel ist bei Weisheitswürfen im Vorteil."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, kannst du für jeden Grad über dem 2. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"aid","name":"Beistand","en":"Aid","level":2,"school":"abjuration","classes":["kleriker","paladin","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":false,"heal":{"slots":{"2":"5","3":"10","4":"15","5":"20","6":"25","7":"30","8":"35","9":"40"}},"desc":["Dein Zauber verleiht deinen Mitstreitern mehr Widerstandsfähigkeit und Entschlossenheit. Wähle bis zu drei Kreaturen in Reichweite.","Das Trefferpunktemaximum und die aktuellen Trefferpunkte jedes Ziels werden für die Wirkungsdauer um 5 erhöht."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, erhöhen sich die Trefferpunkte des Ziels für jeden Grad über dem 2. um 5 Punkte."]},
  {"id":"blindness-deafness","name":"Blindheit/Taubheit","en":"Blindness/Deafness","level":2,"school":"necromancy","classes":["barde","kleriker","zauberer","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V","duration":"1 Minute","conc":false,"ritual":false,"save":"con","desc":["Du kannst einen Feind blind oder taub werden lassen. Wähle eine Kreatur in Reichweite, die du sehen kannst Sie muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, ist das Ziel für die Wirkungsdauer entweder blind oder taub (du entscheidest). Am Ende jedes seiner Züge kann das Ziel einen Konstitutionsrettungswurf ausführen. Bei einem Erfolg endet der Zauber."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, kannst du für jeden Grad über dem 2. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"branding-smite","name":"Brandmarkendes Niederstrecken","en":"Branding Smite","level":2,"school":"evocation","classes":["paladin"],"time":"1 Bonusaktion","action":"bonus","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"damage":{"type":"radiant","slots":{"2":"2d6","3":"3d6","4":"4d6","5":"5d6","6":"6d6","7":"7d6","8":"8d6","9":"9d6"}},"desc":["Das nächste Mal, wenn du eine Kreatur mit einem Waffenangriff triffst, bevor der Zauber endet, umgibt die Waffe ein astrales Leuchten. Der Angriff fügt dem Ziel zusätzlich 2W6 gleißenden Schaden zu. Es wird sichtbar, falls es unsichtbar war, wirft dämmriges Licht in einem Umkreis von 1,5 Metern und kann nicht unsichtbar werden, bis der Zauber endet."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, steigt der zusätzliche Schaden für jeden Grad über dem 2. um 1W6."]},
  {"id":"continual-flame","name":"Dauerhafte Flamme","en":"Continual Flame","level":2,"school":"evocation","classes":["kleriker","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":false,"desc":["Eine Flamme, etwa so hell wie eine Fackel, entspringt einem Gegenstand, den du berührst. Der Effekt sieht aus wie eine gewöhnliche Flamme, erzeugt jedoch keine Hitze und verbraucht keinen Sauerstoff. Eine Dauerhafte Flamme kann verdeckt oder verborgen, aber nicht erstickt oder gelöscht werden."]},
  {"id":"spike-growth","name":"Dornenwuchs","en":"Spike Growth","level":2,"school":"transmutation","classes":["druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"damage":{"type":"piercing","slots":{"2":"2d4"}},"area":{"shape":"cylinder","size":6},"desc":["Der Boden in einem Radius von sechs Metern, der auf einen Punkt in Reichweite zentriert ist, wird von harten Stacheln und Dornen überwuchert Der Bereich wird für die Wirkungsdauer zu schwierigem Gelände. Bewegt sich eine Kreatur in den Bereich oder innerhalb davon, erleidet sie pro zurückgelegten 1,5 Metern 2W4 Stichschaden.","Die Verwandlung des Bodens ist getarnt und sieht natürlich aus. Jede Kreatur, die den Bereich nicht sehen kann, wenn der Zauber gewirkt wird, muss einen Weisheitswurf (Wahrnehmung) gegen deinen Zauberrettungswurf-SG ausführen. Bei einem Erfolg erkennt sie das Gelände vor dem Betreten als gefährlich."]},
  {"id":"darkness","name":"Dunkelheit","en":"Darkness","level":2,"school":"evocation","classes":["zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"area":{"shape":"sphere","size":4.5},"desc":["Beginnend an einem Punkt deiner Wahl in Reichweite breitet sich Dunkelheit zu einer Kugel mit einem Radius von 4,5 Metern aus. Die Dunkelheit breitet sich auch um Ecken aus. Kreaturen mit Dunkelsicht können in dieser Dunkelheit nicht sehen, und nichtmagische Lichtquellen können sie nicht erhellen.","Wenn der gewählte Punkt ein Objekt ist, das du hältst oder das nicht getragen wird, geht die Dunkelheit von diesem Objekt aus und bewegt sich mit ihm mit. Die Dunkelheit wird blockiert, wenn ihre Quelle mit einem undurchsichtigen Objekt wie einer Schüssel oder einem Helm bedeckt wird.","Wenn sich der Wirkbereich dieses Zaubers mit dem eines Lichts überschneidet, das durch einen Zauber des 2. Grades oder geringer erzeugt wurde, so wird der lichterzeugende Zauber gebannt."]},
  {"id":"darkvision","name":"Dunkelsicht","en":"Darkvision","level":2,"school":"transmutation","classes":["druide","waldlaeufer","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":false,"desc":["Du berührst eine bereitwillige Kreatur und verleihst ihr die Fähigkeit, im Dunkeln zu sehen. Für die Wirkungsdauer hat diese Kreatur Dunkelsicht mit einer Reichweite von 18 Metern."]},
  {"id":"suggestion","name":"Einflüsterung","en":"Suggestion","level":2,"school":"enchantment","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, M","duration":"Konzentration, bis zu 8 Stunden","conc":true,"ritual":false,"save":"wis","desc":["Du schlägst eine Vorgehensweise vor (auf einen oder zwei Sätze beschränkt) und beeinflusst auf magische Weise eine Kreatur in Reichweite, die du sehen kannst und die dich hören und verstehen kann. Kreaturen, die nicht bezaubert werden können, sind gegen diesen Effekt immun. Die Einflüsterung muss so formuliert sein, dass die vorgeschlagene Vorgehensweise angemessen erscheint. Aufforderungen, sich selbst zu erstechen, sich in einen Speer zu stürzen, sich anzuzünden oder auf andere Weise zu verletzen, beenden den Zauber.","Das Ziel muss einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, führt es die von dir beschriebene Vorgehensweise nach Kräften aus. Die vorgeschlagene Vorgehensweise kann während der gesamten Wirkungsdauer fortgesetzt werden. Wenn die vorgeschlagene Aktivität in kürzerer Zeit abgeschlossen werden kann, endet der Zauber, sobald das Ziel die Aktivität beendet hat.","Du kannst auch Bedingungen festlegen, die während der Wirkungsdauer eine besondere Handlung auslösen. Du könntest zum Beispiel vorschlagen, dass ein Ritter dem ersten Bettler, den er trifft, sein Pferd schenkt Wenn eine Bedingung vor Ablauf der Wirkungsdauer nicht erfüllt wird, so wird die Handlung nicht ausgeführt.","Wenn du oder einer deiner Begleiter das Ziel verletzt, endet der Zauber."]},
  {"id":"find-traps","name":"Fallen finden","en":"Find Traps","level":2,"school":"divination","classes":["kleriker","druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du spürst die Gegenwart von Fallen, die sich in Reichweite und in deiner Sichtlinie befinden. Für diesen Zauber zählt alles als Falle, was einen plötzlichen oder unerwarteten Effekt auslösen könnte, den du als schädlich oder unerwünscht erachtest und der von seinem Erschaffer derart beabsichtigt war. Somit spürt der Zauber einen Bereich mit dem Zauber Alarm oder Glyphe des Schutzes oder eine mechanische Fallgrube auf. Er offenbart jedoch keine natürliche Schwachstelle im Boden, eine instabile Decke oder ein verstecktes Senkloch.","Dieser Zauber zeigt nur an, dass eine Falle vorhanden ist. Du erfährst nicht, wo sich jede Falle befindet, kennst jedoch die allgemeine Art der Gefahr der gespürten Falle."]},
  {"id":"enthrall","name":"Fesseln","en":"Enthrall","level":2,"school":"enchantment","classes":["barde","hexenmeister"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"1 Minute","conc":false,"ritual":false,"save":"wis","desc":["Du intonierst eine ablenkende Folge von Worten. Kreaturen deiner Wahl in Reichweite, die du sehen kannst und die dich hören können, müssen Weisheitsrettungswürfe ausführen. Kreaturen, die nicht bezaubert werden können, bestehen diesen Rettungswurf automatisch. Kämpfen du oder deine Gefährten gegen eine Kreatur, ist sie beim Rettungswurf im Vorteil. Scheitert der Wurf, ist das Ziel bei Weisheitswürfen (Wahrnehmung) im Nachteil, um andere Kreaturen als dich wahrzunehmen. Dieser Effekt hält an, bis der Zauber endet oder bis das Ziel dich nicht mehr hören kann. Der Zauber endet, wenn du kampfunfähig wirst oder nicht mehr sprechen kannst."]},
  {"id":"flame-blade","name":"Flammenklinge","en":"Flame Blade","level":2,"school":"evocation","classes":["druide"],"time":"1 Bonusaktion","action":"bonus","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"damage":{"type":"fire","slots":{"2":"3d6"}},"desc":["Du erschaffst eine feurige Klinge in deiner freien Hand. Die Klinge ähnelt einem Krummsäbel und bleibt für die Wirkungsdauer bestehen. Lässt du die Klinge los, verschwindet sie. Du kannst sie jedoch als Bonusaktion wieder beschwören.","Du kannst eine Aktion verwenden, um einen Nahkampf-Zauberangriff mit der Flammenklinge auszuführen. Bei einem Treffer erleidet das Ziel 3W6 Feuerschaden.","Die Flammenklinge erhellt einen Radius von drei Metern mit hellem Licht und weitere drei Meter mit dämmrigem Licht."],"higher":["Wenn du diesen Zauber wirkst, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt der Schaden alle zwei Grade über dem 2. um 1W6."]},
  {"id":"flaming-sphere","name":"Flammenkugel","en":"Flaming Sphere","level":2,"school":"conjuration","classes":["druide","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"damage":{"type":"fire","slots":{"2":"2d6"}},"desc":["Eine flammende Sphäre mit 1,5 Metern Durchmesser erscheint an einer freien Stelle deiner Wahl in Reichweite und bleibt dort für die Wirkungsdauer bestehen. Jede Kreatur, die ihren Zug in einem Umkreis von 1,5 Metern um die Sphäre beendet, muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 2W6 Feuerschaden, anderenfalls die Hälfte.","Als Bonusaktion kannst du die Sphäre um bis zu neun Meter bewegen. Wenn du die Sphäre in eine Kreatur rammst, muss die Kreatur einen Rettungswurf gegen den Schaden der Sphäre ausführen und die Sphäre beendet ihre Bewegung für diesen Zug.","Bewegst du die Sphäre, kannst du sie über bis zu 1,5 Meter hohe Hürden dirigieren und über bis zu drei Meter breite Gruben springen lassen. Die Sphäre entzündet brennbare Gegenstände, die nicht getragen oder gehalten werden. Sie strahlt im Radius von sechs Metern helles Licht sowie im Radius von weiteren sechs Metern dämmriges Licht aus."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 2. um 1W6."]},
  {"id":"prayer-of-healing","name":"Gebet der Heilung","en":"Prayer of Healing","level":2,"school":"evocation","classes":["kleriker"],"time":"10 Minuten","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"heal":{"slots":{"2":"2d8 + MOD","3":"3d8 + MOD","4":"4d8 + MOD","5":"5d8 + MOD","6":"6d8 + MOD","7":"7d8 + MOD","8":"8d8 + MOD","9":"9d8 + MOD"}},"desc":["Bis zu sechs Kreaturen deiner Wahl in Reichweite, die du sehen kannst, erhalten jeweils Trefferpunkte in Höhe von 2W8 + deinem Zauberwirken-Attributsmodifikator zurück. Dieser Zauber wirkt nicht auf Untote oder Konstrukte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, steigt die Heilung für jeden Grad über dem 2. um 1W8."]},
  {"id":"detect-thoughts","name":"Gedanken wahrnehmen","en":"Detect Thoughts","level":2,"school":"divination","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Während der Wirkungsdauer kannst du die Gedanken bestimmter Kreaturen lesen. Wenn du den Zauber wirkst und als Aktion in jedem deiner Züge bis zum Ende der Wirkungsdauer, kannst du deinen Verstand auf eine Kreatur im Abstand von bis zu neun Metern von dir richten, die du sehen kannst. Besitzt die Kreatur eine Intelligenz von höchstens 3 oder spricht keine Sprache, ist sie von dem Zauber nicht betroffen.","Du erfährst zunächst die oberflächlichen Gedanken der Kreatur - ein Thema, das sie in diesem Augenblick am meisten beschäftigt. Als Aktion kannst du deine Aufmerksamkeit entweder auf die Gedanken einer anderen Kreatur richten oder versuchen, tiefer in den Verstand derselben Kreatur einzudringen. Wenn du tiefer in die Gedanken des Ziels eindringst, muss es einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, erhältst du Einsicht in seine Beweggründe (sofern es welche gibt), seinen emotionalen Zustand, sowie über etwas, das seine Gedanken beherrscht (beispielsweise etwas, das es beschäftigt, das es liebt oder hasst). Ist der Rettungswurf erfolgreich, endet der Zauber. In jedem Fall ist sich das Ziel bewusst, dass du in seinen Verstand eindringst Wenn du deine Aufmerksamkeit nicht den Gedanken einer anderen Kreatur zuwendest, kann dein aktuelles Ziel eine Aktion verwenden, um seinen Intelligenzwurf mit deinem Intelligenzwurf zu vergleichen. Bei einem Erfolg endet der Zauber.","Fragen, die verbal an die Zielkreatur gerichtet werden, formen auf natürliche Weise ihre Gedanken, sodass dieser Zauber als Verhör besonders effektiv ist","Du kannst diesen Zauber auch nutzen, um die Gegenwart denkender Kreaturen aufzuspüren, die du nicht sehen kannst. Wenn du den Zauber wirkst, oder als Aktion während der Wirkungsdauer, kannst du nach Gedanken im Umkreis von neun Metern von dir suchen. Der Zauber kann Barrieren durchdringen, wird aber von 60 Zentimetern Stein, fünf Zentimetern Metall oder von einer dünnen Bleischicht blockiert. Du kannst keine Kreatur wahrnehmen, deren Intelligenz höchstens 3 ist oder die keine Sprache spricht.","Sobald du die Gegenwart einer Kreatur auf diese Weise aufgespürt hast, kannst du bis zum Ende der Wirkungsdauer wie oben beschrieben ihre Gedanken lesen, selbst wenn du sie nicht sehen kannst. Die Kreatur muss sich allerdings in Reichweite befinden."]},
  {"id":"calm-emotions","name":"Gefühle besänftigen","en":"Calm Emotions","level":2,"school":"enchantment","classes":["barde","kleriker"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"cha","area":{"shape":"sphere","size":6},"desc":["Du versuchst, starke Gefühle in einer Gruppe zu unterdrücken. Alle Humanoide innerhalb einer Sphäre mit einem Radius von sechs Metern, die auf einen Punkt deiner Wahl in Reichweite des Zaubers zentriert ist, müssen einen Charismarettungswurf ausführen. Eine Kreatur kann bei diesem Rettungswurf freiwillig scheitern. Scheitert der Wurf, wähle einen der folgenden Effekte aus:","Du kannst jeden Effekt unterdrücken, der ein Ziel bezaubert oder verängstigt. Wenn der Zauber endet, wird jeder unterdrückte Effekt fortgesetzt, sofern seine Wirkungsdauer in der Zwischenzeit nicht abgelaufen ist.","Alternativ kannst du ein Ziel Kreaturen gegenüber gleichgültig machen, denen es feindlich gesinnt ist. Diese Gleichgültigkeit endet, wenn das Ziel angegriffen oder durch einen Zauber verletzt wird oder sieht, wie einem seiner Verbündeten Schaden zugefügt wird. Wenn der Zauber endet, wird die Kreatur wieder feindlich gesinnt, sofern der SL nichts anderes festlegt."]},
  {"id":"locate-object","name":"Gegenstand aufspüren","en":"Locate Object","level":2,"school":"divination","classes":["barde","kleriker","druide","paladin","waldlaeufer","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Beschreibe oder nenne einen Gegenstand, mit dem du vertraut bist. Solange sich der Gegenstand im Abstand von bis zu 300 Metern von dir befindet, spürst du, in welcher Richtung sein Aufenthaltsort liegt. Bewegt sich der Gegenstand, weißt du, in welche Richtung er sich bewegt.","Der Zauber kann einen bestimmtem dir bekannten Gegenstand aufspüren, sofern du ihn mindestens einmal aus der Nähe - aus maximal neun Metern Entfernung - gesehen hast. Alternativ kann der Zauber das nächstgelegene Objekt einer bestimmten Art aufspüren, wie eine bestimmte Art von Kleidung, Möbel, Schmuck, Waffe oder Werkzeug.","Dieser Zauber kann den Gegenstand nicht aufspüren, wenn Blei den direkten Weg zwischen dir und dem Gegenstand blockiert - egal, wie dünn es ist."]},
  {"id":"alter-self","name":"Gestalt verändern","en":"Alter Self","level":2,"school":"transmutation","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du nimmst eine andere Gestalt an. Wenn du den Zauber wirkst, wähle eine der folgenden Optionen aus. Deren Effekt hält für die Wirkungsdauer des Zaubers an. Solange der Zauber anhält, kannst du als Aktion eine Option beenden, um die Vorzüge einer anderen zu erhalten.","Aquatische Anpassung: Du passt deinen Körper an eine aquatische Umgebung an. Dir wachsen Kiemen und Schwimmhäute zwischen den Fingern. Du kannst unter Wasser atmen und erhältst eine Schwimmbewegungsrate, die deiner Schrittbewegungsrate entspricht.","Aussehen ändern: Du veränderst dein Aussehen. Du bestimmst, wie du aussiehst: Größe, Gewicht, Gesichtszüge, Klang deiner Stimme, Haarlänge, Haarfarbe, sowie etwaige besondere Merkmale. Du kannst dich als Mitglied eines anderen Volks ausgeben, wobei deine Werte unverändert bleiben. Du kannst nicht als Kreatur einer anderen Größenkategorie erscheinen. Deine Grundform bleibt ebenfalls gleich: Als Zweibeiner kannst du dich mit diesem Zauber beispielsweise nicht in einen Vierbeiner verwandeln. Während der Wirkungsdauer kannst du deine Aktion jederzeit verwenden, um dein Aussehen erneut zu verändern.","Natürliche Waffen: Dir wachsen Klauen, Fangzähne, Stacheln, Hörner oder andere natürliche Waffen deiner Wahl. Deine waffenlosen Angriffe verursachen 1W6 Wucht-, Stich- oder Hiebschaden, je nachdem, welche natürliche Waffe du gewählt hast. Du bist zudem in waffenlosen Angriffen geübt Die natürliche Waffe ist magisch und du erhältst einen Bonus von +1 auf alle Angriffs- und Schadenswürfe, die du mit ihr ausführst"]},
  {"id":"knock","name":"Klopfen","en":"Knock","level":2,"school":"transmutation","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Wähle einen Gegenstand in Reichweite, den du sehen kannst. Es kann sich um eine Tür, eine Kiste, Handschellen, ein Vorhängeschloss oder einen anderen Gegenstand handeln, der auf magische oder gewöhnliche Art verschlossen ist.","Ein Ziel, das von einem gewöhnlichen Schloss oder durch einen Riegel verschlossen ist oder klemmt, wird entriegelt, geöffnet oder gelöst. Wenn der Gegenstand mehrere Schlösser besitzt, wird nur eines von ihnen geöffnet.","Wählst du ein Ziel, das mit dem Zauber Arkanes Schloss verriegelt ist, wird dieser Zauber zehn Minuten lang unterdrückt. In dieser Zeit kann das Ziel normal geöffnet und geschlossen werden.","Wenn du diesen Zauber wirkst, gibt dein Ziel ein lautes Klopfgeräusch von sich, dass auf eine Entfernung von 90 Metern hörbar ist."]},
  {"id":"arcanists-magic-aura","name":"Magische Aura des Arkanisten","en":"Arcanist's Magic Aura","level":2,"school":"illusion","classes":["magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":false,"desc":["Du berührst eine Kreatur oder einen Gegenstand und platzierst damit eine Illusion, so dass Erkenntniszauber falsche Informationen darüber vermitteln. Beim Ziel kann es sich um eine bereitwillige Kreatur oder um einen Gegenstand handeln, der nicht von einer anderen Kreatur getragen wird.","Wenn du diesen Zauber wirkst, wähle einen oder beide der folgenden Effekte. Der Effekt bleibt für die Wirkungsdauer bestehen. Wenn du diesen Zauber 30 Tage lang auf dieselbe Kreatur oder denselben Gegenstand wirkst und dabei jedes Mal denselben Effekt auswählst, hält die Illusion an, bis sie gebannt wird.","Falsche Aura: Du veränderst die Art, wie das Ziel für Zauber und magische Effekte wie Magie entdecken erscheint, die magische Auren entdecken. Du kannst einen nichtmagischen Gegenstand magisch oder einen magischen Gegenstand nichtmagisch erscheinen lassen oder die magische Aura des Gegenstands verändern, so dass er einer Schule der Magie deiner Wahl angehören zu scheint. Wirkst du diesen Effekt auf einen Gegenstand, kannst du entscheiden, dass die Illusion von jeder Kreatur entdeckt wird, die den Gegenstand aufnimmt.","Maskierung: Du veränderst die Art, wie das Ziel für Zauber und magische Effekte erscheint, die Kreaturentypen entdecken (wie das göttliche Gespür des Paladins oder die Auslösebedingung des Zaubers Symbol). Du wählst einen Kreaturentyp aus und andere Zauber und magische Effekte behandeln das Ziel, als sei es eine Kreatur dieses Typs oder dieser Gesinnung."]},
  {"id":"magic-weapon","name":"Magische Waffe","en":"Magic Weapon","level":2,"school":"transmutation","classes":["paladin","magier","magieschmied"],"time":"1 Bonusaktion","action":"bonus","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du berührst eine nichtmagische Waffe. Während der Wirkungsdauer gilt diese Waffe als magisch mit einem Bonus von +1 bei Angriffs- und Schadenswürfen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt der Bonus auf +2. Mit einem Zauberplatz des 6. Grades oder höher steigt der Bonus auf +3."]},
  {"id":"magic-mouth","name":"Magischer Mund","en":"Magic Mouth","level":2,"school":"illusion","classes":["barde","magier","magieschmied"],"time":"1 Minute","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":true,"desc":["Du implantierst eine Botschaft in einen Gegenstand in Reichweite. Diese Nachricht wird bei einer bestimmten Auslösebedingung ausgesprochen. Wähle einen Gegenstand, den du sehen kannst und der nicht von einer anderen Kreatur getragen oder gehalten wird. Sprich dann eine Nachricht von maximal 25 Wörtern. Sie kann über einen Zeitraum von bis zu zehn Minuten übermittelt werden. Bestimme dann den Umstand, der den Zauber auslöst und deine Nachricht übermittelt.","Tritt dieser Umstand ein, erscheint ein magischer Mund auf dem Gegenstand und spricht die Botschaft in deiner Stimme und in derselben Lautstärke.","Verfügt der gewählte Gegenstand über einen Mund oder etwas, das wie ein Mund aussieht, etwa der Mund einer Statue, erscheint der magische Mund dort, so dass die Worte aus dem Mund des Gegenstands zu kommen scheinen. Wenn du diesen Zauber wirkst, kannst du entscheiden, ob er nach dem Übermitteln der Botschaft endet, oder bestehen bleibt und die Botschaft immer wiederholt, wenn die Auslösebedingung erfüllt ist.","Die Auslösebedingung kann so allgemein oder so detailliert sein, wie du willst. Sie muss jedoch auf sichtbaren und hörbaren Umständen basieren, die im Abstand von bis zu neun Metern um den Gegenstand auftreten. Beispielweise könntest du den Mund anweisen, die Botschaft zu sprechen, wenn sich eine Kreatur dem Gegenstand im Abstand von neun Metern nähert oder wenn eine Silberglocke im Abstand von bis zu neun Metern um ihn läutet."]},
  {"id":"heat-metal","name":"Metall erhitzen","en":"Heat Metal","level":2,"school":"transmutation","classes":["barde","druide","magieschmied"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"con","damage":{"type":"fire","slots":{"2":"2d8"}},"desc":["Wähle einen verarbeiteten Gegenstand aus Metall in Reichweite, den du sehen kannst - etwa eine metallene Waffe oder eine schwere oder mittelschwere Rüstung. Du lässt den Gegenstand glühend heiß werden. Wenn du den Zauber wirkst, erleiden alle Kreaturen in physischem Kontakt mit dem Gegenstand 2W8 Feuerschaden. Bis der Zauber endet, kannst du in jedem deiner darauffolgenden Züge eine Bonusaktion verwenden, um diesen Schaden erneut zu verursachen.","Trägt eine Kreatur den Gegenstand oder hält sie ihn in der Hand, während sie den Schaden erleidet, muss sie einen Konstitutionsrettungswurf bestehen, um den Gegenstand falls möglich fallenzulassen. Falls sie den Gegenstand nicht fallenlässt, ist sie bis zum Beginn deines nächsten Zuges bei Angriffs- und Attributswürfen im Nachteil."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 2. um 1W8."]},
  {"id":"moonbeam","name":"Mondstrahl","en":"Moonbeam","level":2,"school":"evocation","classes":["druide"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"con","damage":{"type":"radiant","slots":{"2":"2d10"}},"area":{"shape":"cylinder","size":1.5},"desc":["Ein silbriger Strahl fahlen Lichts scheint in einem zwölf Meter hohen Zylinder mit einem Radius von bis zu 1,5 Metern herab, der auf einem Punkt in Reichweite zentriert ist. Bis der Zauber endet, erfüllt dämmriges Licht den Zylinder.","Wenn eine Kreatur den Bereich des Zaubers in einem Zug erstmals betritt oder ihren Zug darin beginnt, wird sie von geisterhaften Flammen eingehüllt, die brennende Schmerzen verursachen. Sie muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 2W10 gleißenden Schaden, anderenfalls die Hälfte.","Ein Gestaltwandler ist bei diesem Rettungswurf im Nachteil. Scheitert der Wurf, nimmt der Gestaltwandler zudem sofort seine ursprüngliche Gestalt an und kann keine andere Gestalt annehmen, bis er das Licht des Zaubers verlässt.","Nachdem du den Zauber gewirkt hast, kannst du den Mondstrahl in jedem deiner Züge als Aktion 18 Meter in eine beliebige Richtung bewegen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 2. um 1W10."]},
  {"id":"misty-step","name":"Nebelschritt","en":"Misty Step","level":2,"school":"conjuration","classes":["zauberer","hexenmeister","magier"],"time":"1 Bonusaktion","action":"bonus","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du wirst kurz von einem silbrigen Nebel umgeben und teleportierst dich bis zu neun Meter weit an eine freie Stelle, die du sehen kannst."]},
  {"id":"web","name":"Netz","en":"Web","level":2,"school":"conjuration","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"damage":{"type":"fire","slots":{"2":"2d4"}},"area":{"shape":"cube","size":6},"desc":["Du beschwörst eine Masse aus dichten, klebrigen Netzen an einem Ort deiner Wahl in Reichweite. Während der Wirkungsdauer füllen die Netze einen würfelförmigen Bereich mit sechs Metern Kantenlänge. Die Netze gelten als schwieriges Gelände und verschleiern den Bereich leicht.","Wenn sich die Spinnweben nicht zwischen zwei festen Gegenständen wie Mauern oder Bäumen befinden oder über einen Fußboden, eine Wand oder eine Decke gespannt sind, fällt das beschworene Netz in sich zusammen und der Zauber endet zu Beginn deines nächsten Zugs. Netze, die über eine flache Oberfläche ausgebreitet sind, besitzen eine Dicke von 1,5 Metern.","Jede Kreatur, die ihren Zug in den Netzen beginnt oder diese während ihres Zugs betritt, muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, ist die Kreatur festgesetzt, solange sie sich in den Netzen befindet oder bis sie sich befreit.","Eine von den Netzen festgesetzte Kreatur kann als Aktion einen Stärkewurf gegen deinen Zauberrettungswurf-SG ausführen. Bei einem Erfolg ist sie nicht länger festgesetzt.","Die Netze sind brennbar. Alle Netze innerhalb eines würfelförmigen Bereichs mit 1,5 Metern Kantenlänge verbrennen innerhalb von einer Runde, wenn sie mit Feuer in Kontakt kommen, und verursachen dabei bei allen Kreaturen, die ihren Zug im Feuer beginnen, 2W4 Feuerschaden."]},
  {"id":"hold-person","name":"Person festhalten","en":"Hold Person","level":2,"school":"enchantment","classes":["barde","kleriker","druide","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Wähle einen Humanoiden in Reichweite, den du sehen kannst. Das Ziel muss einen Weisheitsrettungswurf ausführen oder es wird für die Wirkungsdauer gelähmt. Am Ende jedes seiner Züge kann das Ziel einen weiteren Weisheitsrettungswurf ausführen. Bei einem Erfolg endet die Wirkung des Zaubers auf das Ziel."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, kannst du für jeden Grad über dem 2. einen zusätzlichen Humanoiden als Ziel wählen. Deine humanoiden Ziele, die du festhältst, dürfen nicht mehr als neun Meter voneinander entfernt sein."]},
  {"id":"find-steed","name":"Reittier finden","en":"Find Steed","level":2,"school":"conjuration","classes":["paladin"],"time":"10 Minuten","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du beschwörst einen Geist, der die Gestalt eines ungewöhnlich intelligenten, starken und treuen Reittiers annimmt, und gehst eine langanhaltende Bindung mit ihm ein. Das Reittier erscheint an einer fi elen Stelle in Reichweite und nimmt eine Gestalt deiner Wahl an: Dogge, Elch, Kamel, Pony oder Schlachtross. (Dein SL kann Reittiere anderer Gestalten zulassen.) Das Reittier besitzt die Spielwerte der gewählten Gestalt, ist jedoch stattdessen ein celestisches Wesen, ein Feenwesen oder ein Unhold (deine Wahl), Verfügt dein Reittier über eine Intelligenz von höchstens 5, steigt dieser Wert auf 6. Zudem kann es eine Sprache deiner Wahl verstehen, die du ebenfalls sprichst","Die instinktive Bindung zwischen deinem Reittier und dir macht euch zu einer perfekten Einheit, sowohl im Kampf als auch außerhalb. Während du reitest, kannst du bestimmen, dass jeder von dir gewirkte Zauber, der dich zum Ziel hat, auch dein Reittier betrifft.","Sinken die Trefferpunkte des Reittiers auf 0, verschwindet es und hinterlässt keine physische Form. Du kannst dein Reittier auch jederzeit als Aktion fortschicken, wodurch es verschwindet. In beiden Fällen beschwörst du dasselbe Reittier, wenn du diesen Zauber erneut wirkst, und es verfügt wieder über sein Trefferpunktemaximum.","Während sich dein Reittier im Abstand von bis zu 1,6 Kilometern von dir aufhält, kannst du telepathisch mit ihm kommunizieren.","Du kannst mit diesem Zauber nur mit einem Reittier gleichzeitig eine Bindung eingehen. Als Aktion kannst du das Reittier jederzeit aus seiner Bindung entlassen, wodurch es verschwindet."]},
  {"id":"barkskin","name":"Rindenhaut","en":"Barkskin","level":2,"school":"transmutation","classes":["druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du berührst eine bereitwillige Kreatur. Bis der Zauber endet, wird die Haut des Ziels rau und rindenartig und seine RK beträgt mindestens 16, egal, welche Rüstung es trägt"]},
  {"id":"gentle-repose","name":"Sanfte Ruhe","en":"Gentle Repose","level":2,"school":"necromancy","classes":["kleriker","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"10 Tage","conc":false,"ritual":true,"desc":["Du berührst einen Leichnam oder andere sterbliche Überreste. Für die Wirkungsdauer wird das Ziel vor Verfall geschützt und kann nicht untot werden.","Der Zauber verlängert dadurch auch die Zeit, in der das Ziel wiederbelebt werden kann, da die Tage unter dem Einfluss dieses Zaubers nicht als verstrichene Zeit für Zauber wie Tote erwecken zählen."]},
  {"id":"acid-arrow","name":"Säurepfeil","en":"Acid Arrow","level":2,"school":"evocation","classes":["magier"],"time":"1 Aktion","action":"action","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"attack":"ranged","damage":{"type":"acid","slots":{"2":"4d4"}},"desc":["Ein schimmernder grüner Pfeil schießt auf ein Ziel in Reichweite und explodiert in einem Sprühregen aus Säure. Führe einen Fernkampf-Zauberangriff gegen das Ziel aus. Bei einem Treffer erleidet das Ziel sofort 4W4 Säureschaden und 2W4 Säureschaden am Ende seines nächsten Zugs. Verfehlst du, spritzt genug Säure auf das Ziel, um die Hälfte des anfänglichen Schadens zu verursachen. Das Ziel erleidet am Ende seines nächsten Zugs keinen Schaden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, steigt der Schaden (sowohl der anfängliche als auch der spätere) für jeden Grad über dem 2. um 1W4."]},
  {"id":"protection-from-poison","name":"Schutz vor Gift","en":"Protection from Poison","level":2,"school":"abjuration","classes":["kleriker","druide","paladin","waldlaeufer","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Du berührst eine Kreatur. Ist sie vergiftet, neutralisierst du das Gift Ist das Ziel von mehr als einem Gift betroffen, neutralisierst du ein Gift, von dem du weißt, dass es vorhanden ist, oder ein zufälliges.","Für die Wirkungsdauer ist das Ziel bei Rettungswürfen gegen Gift im Vorteil und gegen Giftschaden resistent"]},
  {"id":"warding-bond","name":"Schützendes Band","en":"Warding Bond","level":2,"school":"abjuration","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Dieser Zauber schützt eine bereitwillige Kreatur, die du berührst, und erschafft für die Wirkungsdauer eine magische Verbindung zwischen dir und dem Ziel. Solange sich das Ziel im Abstand von bis zu 18 Metern von dir befindet, erhält es einen Bonus von +1 auf seine RK und auf Rettungswürfe und ist gegen alle Schadensarten resistent. Allerdings erleidest du jedes Mal, wenn dem Ziel Schaden zugefügt wird, die gleiche Menge an Schaden.","Der Zauber endet, falls deine Trefferpunkte auf 0 sinken oder du und das Ziel sich mehr als 18 Meter voneinander entfernt. Der Zauber endet auch, wenn er erneut auf einen der beiden Beteiligten gewirkt wird. Du kannst den Zauber als Aktion aufheben."]},
  {"id":"lesser-restoration","name":"Schwache Genesung","en":"Lesser Restoration","level":2,"school":"abjuration","classes":["barde","kleriker","druide","paladin","waldlaeufer","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst eine Kreatur und beendest entweder eine Krankheit oder einen Zustand, unter dem sie leidet. Mögliche Zustände sind blind, gelähmt, taub oder vergiftet."]},
  {"id":"ray-of-enfeeblement","name":"Schwächestrahl","en":"Ray of Enfeeblement","level":2,"school":"necromancy","classes":["hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"attack":"ranged","save":"con","desc":["Ein schwarzer Strahl aus entkräftender Energie schießt aus deinem Finger auf eine Kreatur in Reichweite. Führe einen Fernkampf-Zauberangriff gegen das Ziel aus. Bei einem Treffer verursacht das Ziel mit Waffenangriffen, die Stärke verwenden, bis der Zauber endet nur den halben Schaden.","Am Ende jedes seiner Züge kann das Ziel einen Konstitutionsrettungswurf gegen den Zauber ausführen. Bei einem Erfolg endet der Zauber."]},
  {"id":"levitate","name":"Schweben","en":"Levitate","level":2,"school":"transmutation","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Eine Kreatur oder ein Gegenstand deiner Wahl in Reichweite steigt sechs Meter senkrecht empor und verbleibt für die Wirkungsdauer schwebend in der Luft Der Zauber kann Ziele mit einem Maximalgewicht von 250 Kilogramm anheben. Hat eine unwillige Kreatur bei einem Konstitutionsrettungswurf Erfolg, ist sie nicht betroffen.","Das Ziel kann sich nur bewegen, indem es sich von festen Gegenständen oder Oberflächen wie Wänden oder Decken in Reichweite abstößt oder sich an diesen entlanghangelt Dabei gilt die Klettergeschwindigkeit. Während deines Zugs kannst du das Ziel um bis zu sechs Meter anheben oder absenken. Wenn du das Ziel bist, kannst du dich im Rahmen deiner Bewegung selbst anheben oder absenken. Anderenfalls kannst du das Ziel mit deiner Aktion bewegen und musst dabei die Reichweite des Zaubers einhalten.","Wenn der Zauber endet und das Ziel noch schwebt, sinkt es sanft zu Boden."]},
  {"id":"rope-trick","name":"Seiltrick","en":"Rope Trick","level":2,"school":"transmutation","classes":["magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Du berührst ein bis zu 18 Meter langes Seil.","Ein Seilende erhebt sich dann in die Luft, bis das gesamte Seil senkrecht zum Boden in der Luft hängt. Am oberen Ende des Seils öffnet sich ein unsichtbarer Eingang zu einem extradimensionalen Raum, der bis zum Ende der Wirkungsdauer bestehen bleibt.","Kreaturen können diesen Raum erreichen, indem sie das Seil entlang nach oben klettern. Der Raum fasst bis zu acht maximal mittelgroße Kreaturen. Das Seil kann in den Raum gezogen werden, wodurch es von außen nicht mehr zu sehen ist.","Angriffe und Zauber können den extradimensionalen Raum weder von innen noch von außen durchdringen. Kreaturen im Raum können jedoch wie durch ein Fenster mit einer Größe von 0,9 Metern mal 1,5 Metern nach draußen sehen, das um das Seil zentriert ist.","Alles im extradimensionalen Raum fällt heraus, wenn der Zauber endet."]},
  {"id":"scorching-ray","name":"Sengender Strahl","en":"Scorching Ray","level":2,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"damage":{"type":"fire","slots":{"2":"2d6"}},"desc":["Du erschaffst drei Feuerstrahlen und schleuderst sie auf ein oder mehrere Ziele in Reichweite.","Führe für jeden Strahl einen Fernkampf-Zauberangriff aus. Bei einem Treffer erleidet das Ziel 2W6 Feuerschaden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, erschaffst du für jeden Grad über dem 2. einen zusätzlichen Strahl."]},
  {"id":"mirror-image","name":"Spiegelbilder","en":"Mirror Image","level":2,"school":"illusion","classes":["zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"1 Minute","conc":false,"ritual":false,"desc":["Drei illusionäre Duplikate deiner selbst erscheinen in deinem Bereich. Bis der Zauber endet, bewegen sich die Duplikate mit dir, ahmen deine Aktionen nach und verändern ihre Position, so dass es unmöglich ist, zu erkennen, was real ist. Du kannst deine Aktion verwenden, um die illusionären Duplikate fortzuschicken.","Jedes Mal, wenn dich eine Kreatur während der Wirkungsdauer angreift, würfle mit einem W20, um zu bestimmen, ob der Angriff stattdessen eines deiner Duplikate zum Ziel hat.","Wenn du drei Duplikate hast, musst du eine 6 oder höher würfeln, damit ein Duplikat das Ziel des Angriffs wird. Bei zwei Duplikaten musst du eine 8 oder höher würfeln. Bei einem Duplikat musst du eine 11 oder höher würfeln.","Die RK eines Duplikats beträgt 10 + dein Geschicklichkeitsmodifikator. Wenn ein Angriff ein Duplikat trifft, wird dieses zerstört. Ein Duplikat kann nur von einem Angriff zerstört werden, der es trifft. Es ignoriert alle anderen Schadensquellen und Effekte. Der Zauber endet, wenn alle drei Duplikate zerstört wurden.","Eine Kreatur ist von diesem Zauber nicht betroffen, wenn sie nicht sehen kann, wenn sie sich auf andere Sinne als Sicht verlässt (wie Blindsicht) oder wenn sie Illusionen als solche erkennen kann (wie mit Wahrer Blick)."]},
  {"id":"spider-climb","name":"Spinnenklettern","en":"Spider Climb","level":2,"school":"transmutation","classes":["zauberer","hexenmeister","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Eine bereitwillige Kreatur, die du berührst, erhält für die Wirkungsdauer die Fähigkeit, sich in alle Richtungen und mit freien Händen über senkrechte Oberflächen sowie an Decken zu bewegen. Ihre Kletterbewegungsrate entspricht zudem ihrer Schrittbewegungsrate."]},
  {"id":"pass-without-trace","name":"Spurloses Gehen","en":"Pass Without Trace","level":2,"school":"abjuration","classes":["druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Ein Schleier aus Schatten und Stille geht von dir aus und schützt dich und deine Gefährten vor Entdeckung. Für die Wirkungsdauer erhält jede Kreatur deiner Wahl im Abstand von bis zu neun Metern von dir (einschließlich dir selbst) einen Bonus von +10 auf Geschicklichkeitswürfe (Heimlichkeit) und kann nur durch Magie aufgespürt werden. Eine Kreatur mit diesem Bonus hinterlässt keine Fährten oder andere Spuren ihrer Anwesenheit."]},
  {"id":"silence","name":"Stille","en":"Silence","level":2,"school":"illusion","classes":["barde","kleriker","waldlaeufer"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":true,"area":{"shape":"sphere","size":6},"desc":["Für die Wirkungsdauer kann kein Ton in einer Sphäre mit einem Radius von sechs Metern erzeugt werden oder die Sphäre durchdringen. Die Sphäre wird an einem Ort deiner Wahl in Reichweite erzeugt. Alle Kreaturen und Objekte, die sich vollständig in der Sphäre befinden, sind taub und gegen Schallschaden immun. In der Sphäre kann kein Zauber gewirkt werden, der eine verbale Komponente enthält."]},
  {"id":"animal-messenger","name":"Tierbote","en":"Animal Messenger","level":2,"school":"enchantment","classes":["barde","druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":true,"desc":["Mit diesem Zauber kannst du ein Tier eine Nachricht überbringen lassen. Wähle ein winziges Tier in Reichweite, das du sehen kannst, beispielsweise ein Eichhörnchen, einen Blauhäher oder eine Fledermaus. Bestimme einen Ort, an dem du schon einmal warst, sowie einen Empfänger, der einer allgemeinen Beschreibung entspricht, etwa 'ein Mann oder eine Frau in einer Stadtwachenuniform' oder 'ein rothaariger Zwerg mit einem spitzen Hut'. Dann sprichst du eine Botschaft mit bis zu 25 Wörtern. Das Tier reist für die Wirkungsdauer des Zaubers in Richtung Zielort. Ein fliegender Bote legt in 24 Stunden etwa 80 Kilometer zurück, andere Tiere etwa 40 Kilometer.","Am Zielort übermittelt der Bote deine Botschaft an die von dir beschriebene Kreatur und ahmt dabei den Klang deiner Stimme nach. Der Bote spricht nur mit einer Kreatur, die deiner Beschreibung entspricht. Erreicht das Tier sein Ziel nicht vor dem Ende des Zaubers, geht die Botschaft verloren und das Tier kehrt an den Ort zurück, an dem du den Zauber gewirkt hast."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, erhöht sich die Wirkungsdauer für jeden Grad über dem 2. um 48 Stunden."]},
  {"id":"locate-animals-or-plants","name":"Tiere oder Pflanzen aufspüren","en":"Locate Animals or Plants","level":2,"school":"divination","classes":["barde","druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":true,"desc":["Beschreibe oder nenne ein bestimmtes Tier oder eine bestimmte Pflanze. Du konzentrierst dich auf die Stimme der Natur in deiner Umgebung und erfährst, wie weit entfernt und in welcher Richtung im Abstand von bis zu acht Kilometern die nächste Kreatur oder Pflanze dieser Art ist, sofern vorhanden."]},
  {"id":"see-invisibility","name":"Unsichtbares sehen","en":"See Invisibility","level":2,"school":"divination","classes":["barde","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Für die Wirkungsdauer siehst du unsichtbare Kreaturen und Gegenstände, als wären sie sichtbar. Du kannst zudem in die Ätherebene blicken. Ätherische Kreaturen und Gegenstände erscheinen geisterhaft und durchscheinend."]},
  {"id":"invisibility","name":"Unsichtbarkeit","en":"Invisibility","level":2,"school":"illusion","classes":["barde","zauberer","hexenmeister","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Eine Kreatur, die du berührst, wird unsichtbar, bis der Zauber endet. Alles, was das Ziel trägt, ist unsichtbar, solange es an der Person bleibt. Der Zauber endet, sobald das Ziel einen Angriff ausführt oder selbst einen Zauber wirkt."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, kannst du für jeden Grad über dem 2. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"enlarge-reduce","name":"Vergrößern/Verkleinern","en":"Enlarge/Reduce","level":2,"school":"transmutation","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute Für die Wirkungsdauer vergrößerst oder verkleinerst du eine Kreatur oder einen Gegenstand in Reichweite, die oder den du sehen kannst. Wähle eine Kreatur oder einen Gegenstand, die oder der nicht getragen wird. Ist das Ziel nicht bereitwillig, kann es einen Konstitutionsrettungswurf ausführen. Bei einem Erfolg hat der Zauber keine Wirkung.","conc":true,"ritual":false,"save":"con","desc":["Wenn das Ziel eine Kreatur ist, verändert ihre gesamte Ausrüstung ebenfalls die Größe. Wird ein Gegenstand von einer betroffenen Kreatur fallengelassen, kehrt er sofort zu seiner normalen Größe zurück.","Vergrößern: Die Größe des Ziels verdoppelt sich in alle Richtungen und sein Gewicht wird mit acht multipliziert. Dadurch steigt seine Größenkategorie um eins, beispielsweise von mittelgroß zu groß. Gibt es nicht genug Raum, um seine Größe zu verdoppelt, erreicht die Kreatur oder der Gegenstand die maximale Größe, die aufgrund der Gegebenheiten möglich ist. Bis der Zauber endet, ist das Ziel zudem bei Stärke-Attributs- und -rettungswürfen im Vorteil. Die Waffen des Ziels passen sich ebenfalls der neuen Größe an. Während sie vergrößert sind, fügen die Waffenangriffe des Ziels 1W4 zusätzlichen Schaden zu.","Verkleinern: Die Größe des Ziels halbiert sich in alle Richtungen und sein Gewicht wird auf ein Achtel verringert. Dadurch verringert sich seine Größenkategorie um eins, beispielsweise von mittelgroß zu klein. Bis der Zauber endet, ist das Ziel zudem bei Stärke-Attributs- und -rettungswürfen im Nachteil. Die Waffen des Ziels passen sich ebenfalls der neuen Größe an. Während sie verkleinert sind, fügen die Waffenangriffe des Ziels 1W4 weniger Schaden zu (der Schaden kann allerdings nicht unter 1 sinken)."]},
  {"id":"blur","name":"Verschwimmen","en":"Blur","level":2,"school":"illusion","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Alle, die dich sehen können, nehmen deinen Körper als unscharf und oszillierend wahr. Während der Wirkungsdauer sind Kreaturen bei Angriffswürfen gegen dich im Nachteil. Angreifer, die nicht auf ihre Sicht angewiesen sind (etwa durch Blindsicht) oder Illusionen durchschauen können (etwa mit wahrer Sicht), sind gegen diesen Effekt immun."]},
  {"id":"augury","name":"Vorahnung","en":"Augury","level":2,"school":"divination","classes":["kleriker"],"time":"1 Minute","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":true,"desc":["Wirf edelsteinverzierte Stöcke oder Drachenknochen, lege kunstvolle Karten oder nutze ein anderes Hilfsmittel und erhalte ein Omen von einem außerweltlichen Wesen zu einer bestimmten Vorgehensweise, die innerhalb der nächsten 30 Minuten geplant ist. Der SL wählt aus den folgenden möglichen Omen aus:","Der Zauber berücksichtigt keinerlei Umstände, die das Ergebnis ändern könnten, etwa das Wirken von zusätzlichen Zaubern oder der Verlust oder Gewinn eines Begleiters.","Wenn du den Zauber vor deiner nächsten langen Rast mindestens zweimal wirkst, steigt die Chance auf zufällige Omen mit jedem Wirken nach dem ersten um zusätzliche 25 Prozent. Der SL würfelt das Ergebnis geheim aus."]},
  {"id":"spiritual-weapon","name":"Waffe des Glaubens","en":"Spiritual Weapon","level":2,"school":"evocation","classes":["kleriker"],"time":"1 Bonusaktion","action":"bonus","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"1 Minute","conc":false,"ritual":false,"attack":"melee","desc":["Du erzeugst eine schwebende Spektralwaffe in Reichweite, die während der Wirkungsdauer oder bis du diesen Zauber erneut wirkst bestehen bleibt Wenn du den Zauber wirkst, kannst du einen Nahkampf-Zauberangriff gegen eine Kreatur im Abstand von bis zu 1,5 Metern von der Waffe ausführen. Bei einem Treffer erleidet das Ziel Energieschaden in Höhe von 1W8 + deinem Zauberwirken-Attributsmodifikator.","Als Bonusaktion kannst du die Waffe in deinem Zug um bis zu sechs Meter bewegen und einen weiteren Angriff gegen eine Kreatur im Abstand von bis zu 1,5 Metern von ihr ausführen.","Die Waffe kann eine Form deiner Wahl annehmen. Kleriker von Gottheiten, die mit einer bestimmten Waffe assoziiert sind - wie St. Cuthbert mit seinem Streitkolben und Thor mit seinem Hammer lassen den Effekt des Zaubers wie diese Waffe aussehen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, erhöht sich der Schaden alle zwei Grade über dem 2. um 1W8."]},
  {"id":"gust-of-wind","name":"Windstoß","en":"Gust of Wind","level":2,"school":"evocation","classes":["druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Linie von 18 m)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"str","area":{"shape":"line","size":18,"width":1.5},"desc":["Für die Wirkungsdauer weht ein starker Wind von dir ausgehend in einer Linie mit 18 Metern Länge und drei Metern Breite in eine Richtung deiner Wahl. Jede Kreatur, die ihren Zug innerhalb der Linie beginnt, muss einen Stärkerettungswurf bestehen, oder sie wird 4,5 Meter entlang der Linie von dir weggestoßen.","Jede Kreatur innerhalb der Linie muss für jeden Meter, den sie sich auf dich zu bewegt, zwei Meter Bewegungsrate verwenden.","Der Windstoß zerstreut Gas oder Dampf und löscht Kerzen, Fackeln und ähnliche ungeschützte Flammen in seinem Bereich. Geschützte Flammen, wie die von Laternen, flackern wild und haben eine Chance von 50 Prozent, gelöscht zu werden.","Als Bonusaktion kannst du in jedem deiner Züge vor Ablauf der Wirkungsdauer die Richtung ändern, in die der Wind weht."]},
  {"id":"tiny-hut","name":"Winzige Hütte","en":"Tiny Hut","level":2,"school":"evocation","classes":["barde","magier"],"time":"1 Minute","action":"long","range":"Selbst (Halbkugel mit 3 m Radius)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":true,"area":{"shape":"sphere","size":3},"desc":["Eine unbewegliche Kuppel aus Energie mit einem Radius von drei Metern entsteht um dich herum und bleibt für die Wirkungsdauer bestehen. Der Zauber endet, wenn du den Bereich verlässt.","Außer dir passen in die Kuppel bis zu neun maximal mittelgroße Kreaturen. Der Zauber schlägt fehl, wenn der Bereich eine größere Kreatur oder mehr als neun Kreaturen enthält. Kreaturen und Gegenstände, die sich beim Wirken des Zaubers in der Kuppel aufhalten, können sich frei durch sie bewegen. Allen anderen Kreaturen und Gegenständen ist der Zugang verwehrt. Zauber und andere magische Effekte können nicht in die Kuppel eindringen oder durch sie hindurch gewirkt werden. Die Atmosphäre innerhalb des Bereichs ist angenehm und trocken, ungeachtet des Wetters außerhalb.","Bis der Zauber endet, kannst du das Innere in dämmriges Licht tauchen oder verdunkeln. Die Kuppel ist von außen undurchsichtig und erscheint in einer Farbe deiner Wahl. Von innen ist sie durchsichtig."]},
  {"id":"shatter","name":"Zerbersten","en":"Shatter","level":2,"school":"evocation","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"thunder","slots":{"2":"3d8"}},"area":{"shape":"sphere","size":3},"desc":["Von einem Punkt deiner Wahl in Reichweite geht ein schmerzhaft lautes Klingelgeräusch aus. Alle Kreaturen im Radius von drei Metern um diesen Punkt müssen einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleiden sie 3W8 Schallschaden, anderenfalls die Hälfte. Kreaturen aus anorganischem Material wie Stein, Kristall oder Metall sind beim Rettungswurf im Nachteil.","Nichtmagische Objekte, die nicht getragen werden, erleiden innerhalb des Bereichs den gleichen Schaden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 3. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 2. um 1W8."]},
  {"id":"zone-of-truth","name":"Zone der Wahrheit","en":"Zone of Truth","level":2,"school":"enchantment","classes":["barde","kleriker","paladin"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"10 Minuten","conc":false,"ritual":false,"save":"cha","area":{"shape":"sphere","size":4.5},"desc":["Du erschaffst eine magische Zone in einer Sphäre mit einem Radius von 4,5 Metern, die auf einen Punkt deiner Wahl in Reichweite zentriert ist. Die Zone schützt vor Täuschung. Bis der Zauber endet, muss jede Kreatur, die den Bereich des Zaubers in einem Zug erstmals betritt oder ihren Zug darin beginnt, einen Charismarettungswurf ausführen. Scheitert der Wurf, so kann die Kreatur innerhalb des Radius nicht absichtlich lügen. Du weißt, ob eine Kreatur ihren Rettungswurf besteht oder nicht.","Eine betroffene Kreatur ist sich des Zaubers bewusst und kann somit Fragen vermeiden, bei denen sie als Antwort lügen würde. In diesem Fall kann eine Kreatur die Antwort ausweichend formulieren, solange sie innerhalb der Grenzen der Wahrheit bleibt."]},
  {"id":"water-walk","name":"Auf Wasser gehen","en":"Water Walk","level":3,"school":"transmutation","classes":["kleriker","druide","waldlaeufer","zauberer","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":true,"desc":["Dieser Zauber verleiht die Fähigkeit, sich über flüssige Oberflächen zu bewegen, darunter Wasser, Säure, Schlamm, Schnee, Treibsand oder Lava, als handele es sich um ungefährlichen, festen Boden (Kreaturen, die sich über geschmolzene Lava bewegen, können jedoch trotzdem Hitzeschaden erleiden). Bis zu zehn bereitwillige Kreaturen in Reichweite, die du sehen kannst, erhalten für die Wirkungsdauer diese Fähigkeit.","Wählst du eine Kreatur als Ziel, die in einer Flüssigkeit untergetaucht ist, bringt der Zauber sie mit einer Geschwindigkeit von 18 Metern pro Runde an die Oberfläche."]},
  {"id":"lightning-bolt","name":"Blitz","en":"Lightning Bolt","level":3,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Linie von 30 m)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"lightning","slots":{"3":"8d6"}},"area":{"shape":"line","size":30,"width":1.5},"desc":["Du schleuderst einen Blitz von dir ausgehend in einer 30 Meter langen und 1,5 Meter breiten Linie in eine Richtung deiner Wahl. Alle Kreaturen innerhalb der Linie müssen einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet eine Kreatur 8W6 Blitzschaden, anderenfalls die Hälfte.","Der Blitz entzündet brennbare Gegenstände im Wirkungsbereich, die nicht getragen werden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 3. um 1W6."]},
  {"id":"call-lightning","name":"Blitze herbeirufen","en":"Call Lightning","level":3,"school":"conjuration","classes":["druide"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"damage":{"type":"lightning","slots":{"3":"3d10"}},"area":{"shape":"sphere","size":1.5},"desc":["Eine Sturmwolke in Form eines drei Meter hohen Zylinders mit einem Radius von 18 Metern erscheint zentriert auf einem Punkt 30 Meter direkt über dir, den du sehen kannst. Der Zauber schlägt fehlt, wenn du keinen Punkt in der Luft sehen kannst, an dem die Sturmwolke erscheinen kann (beispielsweise, wenn du dich in einem Raum befindest, der zu klein für die Wolke ist).","Wenn du diesen Zauber wirkst, wähle einen Punkt in Reichweite, den du sehen kannst. Ein Blitz schlägt von der Wolke in diesen Punkt ein. Jede Kreatur im Umkreis von 1,5 Metern um diesen Punkt muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 3W10 Blitzschaden, anderenfalls die Hälfte. Bis der Zauber endet, kannst du deine Aktion in jedem deiner Züge verwenden, um erneut einen Blitz einschlagen zu lassen. Dabei kannst du denselben Punkt oder einen anderen als Ziel auswählen.","Wenn du dich draußen aufhältst und ein Sturm herrscht, wenn du diesen Zauber wirkst, verleiht er dir Kontrolle über den bestehenden Sturm und erschafft keinen neuen. Unter diesen Umständen erhöht sich der Schaden des Zaubers um 1W10."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 3. um 1W10."]},
  {"id":"fireball","name":"Feuerball","en":"Fireball","level":3,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"fire","slots":{"3":"8d6"}},"area":{"shape":"sphere","size":6},"desc":["Ein heller Lichtstrahl schießt aus deinem deutenden Finger auf einen Punkt deiner Wahl in Reichweite und explodiert dort mit einem dumpfen Grollen in lodernden Flammen. Jede Kreatur in einer Sphäre mit einem Radius von sechs Metern um diesen Punkt muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet das Ziel 8W6 Feuerschaden, anderenfalls die Hälfte.","Das Feuer breitet sich um Ecken aus. Es entzündet brennbare Gegenstände in der Umgebung, die nicht getragen oder gehalten werden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 3. um 1W6."]},
  {"id":"fly","name":"Fliegen","en":"Fly","level":3,"school":"transmutation","classes":["zauberer","hexenmeister","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Du berührst eine bereitwillige Kreatur. Für die Wirkungsdauer erhält das Ziel eine Flugbewegungsrate von 18 Metern. Wenn der Zauber endet und das Ziel noch fliegt, fällt es herunter, sofern es den Sturz nicht verhindern kann."],"higher":["Wenn du diesen Zauber wirkst, indem du einen Zauberplatz des 4. Grades oder höher nutzt, kannst du für jeden Grad über dem 3. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"blink","name":"Flimmern","en":"Blink","level":3,"school":"transmutation","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"1 Minute","conc":false,"ritual":false,"desc":["Würfle, solange der Zauber anhält, am Ende jedes deiner Züge mit einem W20. Bei einer 11 oder höher verschwindest du von deiner derzeitigen Existenzebene und erscheinst auf der Ätherebene (der Zauber schlägt fehl und das Wirken ist vergeudet, wenn du dich bereits auf dieser Ebene befindest). Wenn du dich zu Beginn deines nächsten Zugs oder wenn der Zauber endet auf der Ätherebene befindest, kehrst du an eine freien Stelle deiner Wahl zurück, die du im Umkreis von drei Metern um den Ort deines Verschwindens herum sehen kannst Ist innerhalb dieser Reichweite keine freie Stelle vorhanden, erscheinst du an der nächstgelegenen freien Stelle (gibt es mehr als eine Stelle in Reichweite, wird sie zufällig ausgewählt). Du kannst als Aktion den Zauber aufheben.","Während du dich auf der Ätherebene befindest, kannst du deine ursprüngliche Ebene sehen und hören. Sie ist jedoch monochrom und deine Sichtweite beträgt maximal 18 Meter. Du kannst nur Kreaturen beeinflussen oder von ihnen beeinflusst werden, die sich ebenfalls auf der Ätherebene aufhalten. Kreaturen, die nicht hier sind, können dich nicht wahrnehmen oder mit dir interagieren, es sei denn, eine Fähigkeit erlaubt es ihnen."]},
  {"id":"bestow-curse","name":"Fluch","en":"Bestow Curse","level":3,"school":"necromancy","classes":["barde","kleriker","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Du berührst eine Kreatur, die einen Weisheitsrettungswurf ausführen muss oder für die Wirkungsdauer verflucht wird. Wähle beim Wirken des Zaubers die Art des Fluchs aus den folgenden Optionen aus:","Der Zauber Fluch brechen beendet diesen Effekt. Der SL kann einen alternativen Effekt für den Fluch zulassen, der jedoch nicht mächtiger sein sollte als die beschriebenen Effekte. Der SL hat das letzte Wort, was den Effekt angeht."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, ändert sich die Wirkungsdauer zu: Konzentration, bis zu 10 Minuten. Bei einem Zauberplatz des 5. Grades oder höher beträgt die Wirkungsdauer 8 Stunden. Bei einem Zauberplatz des 7. Grades oder höher beträgt die Wirkungsdauer 24 Stunden. Bei einem Zauberplatz des 9. Grades hält der Zauber an, bis er gebannt wird. Bei einem Zauberplatz des 5. Grades oder höher wird keine Konzentration mehr benötigt."]},
  {"id":"remove-curse","name":"Fluch brechen","en":"Remove Curse","level":3,"school":"abjuration","classes":["kleriker","paladin","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Auf deine Berührung hin enden alle Flüche, die eine Kreatur oder einen Gegenstand betreffen. Ist der verfluchte Gegenstand magisch, bleibt der Fluch zwar bestehen, aber der Zauber bricht die Einstimmung des Besitzers, so dass der Gegenstand entfernt oder weggeworfen werden kann."]},
  {"id":"fear","name":"Furcht","en":"Fear","level":3,"school":"illusion","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Kegel von 9 m)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","area":{"shape":"cone","size":9},"desc":["Du projizierst ein Trugbild der schlimmsten Ängste einer Kreatur. Jede Kreatur in einem Kegel von neun Metern muss einen Weisheitsrettungswurf bestehen, oder sie lässt fallen, was auch immer sie hält, und ist für die Wirkungsdauer verängstigt.","Wenn eine Kreatur aufgrund dieses Zaubers verängstigt ist, muss sie in jedem ihrer Züge die Spurt-Aktion ausführen und sich auf dem sichersten Weg von dir fortbewegen, sofern dies technisch möglich ist. Wenn eine Kreatur ihren Zug an einem Ort beendet, an dem sie dich nicht sehen kann, kann sie einen Weisheitsrettungswurf ausführen. Bei einem Erfolg endet der Zauber für diese Kreatur."]},
  {"id":"gaseous-form","name":"Gasförmige Gestalt","en":"Gaseous Form","level":3,"school":"transmutation","classes":["zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Für die Wirkungsdauer verwandelst du eine bereitwillige Kreatur, die du berührst, mitsamt ihrer Ausrüstung in eine Nebelwolke. Wenn die Trefferpunkte der Kreatur auf 0 sinken, endet der Zauber. Eine körperlose Kreatur ist nicht betroffen.","Während sie sich in dieser Gestalt befindet, verfügt das Ziel als einzige Bewegungsrate über eine Flugbewegungsrate von drei Metern. Das Ziel kann den Bereich einer anderen Kreatur betreten und besetzen. Das Ziel ist bei Rettungswürfen auf Stärke, Geschicklichkeit und Konstitution im Vorteil und gegen nichtmagischen Schaden resistent. Das Ziel passt durch kleine Löcher, schmale Öffnungen und sogar Spalten. Flüssigkeiten stellen für es jedoch solide Oberflächen dar. Das Ziel kann nicht fallen und schwebt selbst dann in der Luft, wenn es betäubt oder kampfunfähig ist.","In der Gestalt einer Nebelwolke kann das Ziel weder sprechen noch mit Gegenständen interagieren. Es kann keine von ihm getragenen Objekte fallenlassen, verwenden oder anderweitig mit ihnen interagieren. Das Ziel kann nicht angreifen und keine Zauber wirken."]},
  {"id":"counterspell","name":"Gegenzauber","en":"Counterspell","level":3,"school":"abjuration","classes":["zauberer","hexenmeister","magier"],"time":"1 Reaktion, die du ausführst, wenn du siehst, dass eine Kreatur im Umkreis von 18 Meter um dich einen Zauber wirkt","action":"reaction","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du versuchst, eine Kreatur beim Wirken eines Zaubers zu unterbrechen. Wirkt die Kreatur einen Zauber des 3. Grades oder niedriger, scheitert ihr Zauber und hat keinen Effekt. Wirkt sie einen Zauber des 4. Grades oder höher, führe einen Attributswurf mit deinem Attribut zum Zauberwirken aus. Der SG ist 10 + der Grad des Zaubers. Bei einem Erfolg schlägt der Zauber der Kreatur fehl und hat keinen Effekt"],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, hat der unterbrochene Zauber keinen Effekt, wenn sein Grad niedriger als er Zauberplatz ist, den du zum Wirken verwendet hast, oder ihm entspricht."]},
  {"id":"phantom-steed","name":"Geisterross","en":"Phantom Steed","level":3,"school":"illusion","classes":["magier"],"time":"1 Minute","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"1 Stunde","conc":false,"ritual":true,"desc":["Eine große, quasi reale, pferdeartige Kreatur erscheint in einem freien Bereich deiner Wahl in Reichweite, den du sehen kannst Du bestimmst das Aussehen der Kreatur. Sie ist jedoch mit einem Sattel und Zaumzeug ausgerüstet Von diesem Zauber erschaffene Ausrüstung löst sich in Rauch auf, wenn sie mehr als drei Meter vom Ross entfernt wird.","Für die Wirkungsdauer kannst du beziehungsweise kann eine Kreatur deiner Wahl auf dem Ross reiten. Die Kreatur verwendet die Spielwerte eines Reitpferds, verfügt jedoch über eine Bewegungsrate von 30 Metern und kann in einer Stunde 16 Kilometer zurücklegen - oder 21 Kilometer bei einem schnellen Reittempo. Wenn der Zauber endet, verblasst das Ross langsam und der Reiter hat eine Minute Zeit, um abzusteigen. Der Zauber endet, wenn du ihn als Aktion beendest oder wenn das Ross Schaden erleidet"]},
  {"id":"glyph-of-warding","name":"Glyphe des Schutzes","en":"Glyph of Warding","level":3,"school":"abjuration","classes":["barde","kleriker","magier","magieschmied"],"time":"1 Stunde","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Bis der Zauber gebannt oder ausgelöst wird","conc":false,"ritual":false,"desc":["Wenn du diesen Zauber wirkst, zeichnest du eine Glyphe, die anderen Kreaturen Schaden zufügt. Dies geschieht entweder auf einer Oberfläche (wie einem Tisch, dem Fußboden oder einer Wand) oder in einem Gegenstand, der verschlossen werden kann (wie einem Buch, einer Schriftrolle oder einer Schatztruhe), um die Glyphe zu verbergen. Wählst du eine Oberfläche, kann die Glyphe einen Bereich mit einem Radius von maximal drei Metern abdecken. Wählst du einen Gegenstand, muss dieser an seinem Standort bleiben. Wird er mehr als drei Meter von dem Ort entfernt, an dem du den Zauber gewirkt hast, wird die Glyphe zerstört und der Zauber endet, ohne ausgelöst zu werden.","Die Glyphe ist nahezu unsichtbar. Es ist ein erfolgreicher Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG nötig, um sie zu entdecken.","Wenn du den Zauber wirkst, entscheidest du, was die Glyphe auslöst. Glyphen auf Oberflächen werden meist dadurch ausgelöst, dass jemand sie berührt oder darauf steht, einen Gegenstand bewegt, der die Glyphe verdeckt, sich der Glyphe auf eine bestimmte Entfernung nähert oder mit dem Gegenstand interagiert, auf den die Glyphe geschrieben wurde. Glyphen auf Gegenständen werden meist dadurch ausgelöst, dass jemand den Gegenstand öffnet, sich ihm auf eine bestimmte Entfernung nähert oder die Glyphe sieht oder liest. Sobald die Glyphe ausgelöst wurde, endet der Zauber.","Du kannst die Auslösebedingung des Zaubers weiter verfeinern, so dass der Zauber nur bei bestimmten Umständen oder körperlichen Eigenschaften (wie Größe oder Gewicht) sowie Kreaturentypen (etwa Aberrationen oder Drow) oder bei einer bestimmten Gesinnung ausgelöst wird. Du kannst auch Bedingungen für Kreaturen festlegen, die die Glyphe nicht auslösen, wenn sie beispielsweise ein bestimmtes Passwort aussprechen.","Beim Zeichnen der Glyphe wählst du aus, ob es sich um explosive Runen oder eine Zauberglyphe handelt.","Explosive Runen: Wird die Glyphe ausgelöst, explodiert ihre magische Energie in einer Sphäre mit einem Radius von sechs Metern mit der Glyphe im Zentrum. Die Sphäre breitet sich um Ecken aus. Jede Kreatur in diesem Bereich muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 5W8 Blitz-, Feuer-, Kälte-, Säure- oder Schallschaden (deine Wahl beim Wirken der Glyphe), anderenfalls die Hälfte.","Zauberglyphe: Du kannst einen vorbereiteten Zauber des maximal 3. Grades in der Glyphe speichern, den du beim Erschaffen der Glyphe wirkst Der Zauber muss eine einzelne Kreatur oder einen Bereich zum Ziel haben. Wenn er auf diese Weise gewirkt wird, hat der gespeicherte Zauber keinen unmittelbaren Effekt. Erst wenn die Glyphe ausgelöst wird, wird der gespeicherte Zauber gewirkt. Ein gezielter Zauber hat die Kreatur zum Ziel, die die Glyphe auslöst.","Wirkt der Zauber auf einen Bereich, ist dieser auf die Kreatur zentriert. Wenn der Zauber feindlich gesinnte Kreaturen beschwört oder schädliche Gegenstände oder Fallen erschafft, erscheinen sie so nahe wie möglich beim Eindringling und greifen ihn an. Erfordert der Zauber Konzentration, hält er bis zum Ende seiner Wirkungsdauer an."],"higher":["Wenn du diesen Zauber wirkst, indem du einen Zauberplatz des 4. Grades oder höher nutzt, erhöht sich der Schaden der explosiven Runen für jeden Grad über dem 3. um 1W8. Wenn du eine Zauberglyphe erschaffst, kannst du Zauber bis zum selben Grad des Zauberplatzes speichern, den du für die Glyphe des Schutzes verwendet hast."]},
  {"id":"haste","name":"Hast","en":"Haste","level":3,"school":"transmutation","classes":["zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Wähle eine bereitwillige Kreatur in Reichweite, die du sehen kannst. Bis der Zauber endet, wird die Bewegungsrate des Ziels verdoppelt, es erhält einen Bonus von +2 auf seine RK, ist bei Rettungswürfen auf Geschicklichkeit im Vorteil und kann in jedem seiner Züge eine zusätzliche Aktion ausführen. Diese Aktion darf nur für Folgendes eingesetzt werden: Angriff (nur ein Waffenangriff), Gegenstand benutzen, Rückzug, Spurt, Verstecken.","Wenn der Zauber endet, kann das Ziel bis zum Ende seines nächsten Zugs keine Aktion ausführen und sich nicht bewegen, weil es von einer Welle der Erschöpfung ergriffen wird."]},
  {"id":"clairvoyance","name":"Hellsehen","en":"Clairvoyance","level":3,"school":"divination","classes":["barde","kleriker","zauberer","magier"],"time":"10 Minuten","action":"long","range":"1,6 km","rangeKind":"dist","rangeM":1600,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Du erschaffst einen unsichtbaren Sensor in Reichweite an einem dir bekannten Ort (den du bereits gesehen oder besucht hast) oder an einem offensichtlichen Ort, der dir unbekannt ist (wie hinter einer Tür, um eine Ecke oder in einem Hain), Der Sensor bleibt für die Wirkungsdauer bestehen und kann weder angegriffen noch anderweitig beeinflusst werden.","Wenn du diesen Zauber wirkst, wählst du Sehen oder Hören aus. Du nimmst den gewählten Sinn durch den Sensor wahr, als ob du dich in seinem Bereich befindest. Als Aktion kannst du zwischen Sehen und Hören wechseln.","Eine Kreatur, die den Sensor sehen kann (beispielsweise mit Unsichtbares sehen oder Wahrer Blick), sieht eine leuchtende, etwa faustgroße und immaterielle Kugel."]},
  {"id":"hypnotic-pattern","name":"Hypnotisches Muster","en":"Hypnotic Pattern","level":3,"school":"illusion","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Du erschaffst ein wirbelndes Muster aus Farben, das sich innerhalb eines Würfels mit neun Metern Kantenlänge in Reichweite durch die Luft schlängelt Das Muster erscheint für einen Moment und verschwindet dann. Jede Kreatur in diesem Bereich, die das Muster sieht muss einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, ist die Kreatur für die Wirkungsdauer bezaubert. Auf diese Art bezauberte Kreaturen sind kampfunfähig und haben eine Bewegungsrate von 0.","Der Zauber endet für eine betroffene Kreatur, wenn sie Schaden erleidet, oder wenn jemand anderes eine Aktion verwendet, um die Kreatur aus ihrer Betäubung zu rütteln."]},
  {"id":"beacon-of-hope","name":"Leuchtfeuer der Hoffnung","en":"Beacon of Hope","level":3,"school":"abjuration","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Dieser Zauber verleiht Hoffnung und Lebenskraft. Wähle eine beliebige Anzahl Kreaturen in Reichweite aus. Während der Wirkungsdauer ist jedes Ziel bei Weisheits- und Todesrettungswürfen im Vorteil und gewinnt durch Heilung die maximal mögliche Anzahl an Trefferpunkten zurück."]},
  {"id":"major-image","name":"Mächtiges Trugbild","en":"Major Image","level":3,"school":"illusion","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"area":{"shape":"cube","size":6},"desc":["Du erschaffst ein Abbild eines Objekts, einer Kreatur oder eines anderen sichtbaren Phänomens, das nicht größer als ein Würfel mit sechs Metern Kantenlänge sein darf. Das Abbild erscheint an einem Punkt in Reichweite und bleibt während der Wirkungsdauer bestehen. Es ist von der Realität nicht zu unterscheiden und simuliert auch die dazu passenden Geräusche, Gerüche und Temperatur. Da die Hitze oder Kälte eine Illusion ist, verursacht sie keinen Schaden. Du kannst keine Geräusche erzeugen, die laut genug sind, um Schallschaden zu verursachen oder eine Kreatur zu betäuben, und keinen Geruch, der Übelkeit auslösen könnte - wie den Gestank eines Troglodyten.","Solange du dich in der Reichweite der Illusion befindest, kannst du mit deiner Aktion das Abbild an einen anderen Ort deiner Wahl in Reichweite bewegen. Dabei kannst du das Bild so verändern, dass seine Bewegung natürlich erscheint. Beispiel: Wenn du das Abbild einer Kreatur erstellst und bewegst, kannst du es so verändern, dass es zu laufen scheint. Außerdem kann die Illusion verschiedene Geräusche machen oder sogar ein Gespräch führen.","Physische Interaktionen mit dem Abbild enttarnen es als Illusion, da Dinge es einfach durchdringen können. Eine Kreatur, die ihre Aktion verwendet, um das Abbild zu untersuchen, kann einen Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG ausführen. Bei einem Erfolg erkennt eine Kreatur das Abbild als Illusion und es wird für sie durchscheinend. Die anderen sensorischen Eigenschaften werden ebenfalls abgeschwächt."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, bleibt der Zauber bestehen, bis er gebannt wird und erfordert keine Konzentration deinerseits."]},
  {"id":"dispel-magic","name":"Magie bannen","en":"Dispel Magic","level":3,"school":"abjuration","classes":["barde","kleriker","druide","paladin","zauberer","hexenmeister","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Wähle eine Kreatur, ein Objekt oder einen magischen Effekt in Reichweite. Jeder Zauber des 3. Grades oder niedriger, der auf dem Ziel liegt, endet. Führe für jeden Zauber des 4. Grades oder höher, der auf dem Ziel liegt, einen Attributswurf mit deinem Attribut zum Zauberwirken aus. Der SG ist gleich 10 + der Grad des Zaubers. Bei einem erfolgreichen Wurf endet der Zauber."],"higher":["Wenn du diesen Zauber wirkst, indem du einen Zauberplatz des 4. Grades oder höher nutzt, beendest du automatisch die Effekte von Zaubern, die auf dem Ziel liegen und deren Grad gleich oder niedriger als der Grad des Zauberplatzes ist, den du gerade nutzt."]},
  {"id":"mass-healing-word","name":"Massen-Heilendes Wort","en":"Mass Healing Word","level":3,"school":"evocation","classes":["kleriker"],"time":"1 Bonusaktion","action":"bonus","range":"18 m ","rangeKind":"dist","rangeM":18,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"heal":{"slots":{"3":"1d4 + MOD","4":"2d4 + MOD","5":"3d4 + MOD","6":"4d4 + MOD","7":"5d4 + MOD","8":"6d4 + MOD","9":"7d4 + MOD"}},"desc":["Du sprichst magische Worte der Heilung und bis zu sechs Kreaturen deiner Wahl in Reichweite, die du sehen kannst, erhalten Trefferpunkte in Höhe von 1W4 + deinem Zauberwirken-Attributsmodifikator zurück. Dieser Zauber wirkt nicht auf Untote oder Konstrukte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt die Heilung für jeden Grad über dem 3. um 1W4."]},
  {"id":"speak-with-plants","name":"Mit Pflanzen sprechen","en":"Speak with Plants","level":3,"school":"transmutation","classes":["barde","druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"Selbst (Radius von 9 m)","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"10 Minuten","conc":false,"ritual":false,"area":{"shape":"sphere","size":9},"desc":["Du erfüllst Pflanzen im Abstand von bis zu neun Metern von dir mit begrenztem Bewusstsein und Leben, so dass sie mit dir kommunizieren und einfache Befehle befolgen können. Du kannst die Pflanzen über Ereignisse des letzten Tags im Bereich des Zaubers befragen und so Information über vorbeiziehende Kreaturen, das Wetter und andere Umstände erhalten.","Du kannst auch schwieriges Gelände wie Dickicht oder Unterholz aufgrund von Pflanzenwachstum für die Wirkungsdauer in normales Gelände verwandeln. Gleichermaßen kannst du normales Gelände mit Pflanzen für die Wirkungsdauer zu schwierigem Gelände machen, indem Ranken und Äste beispielsweise Verfolger behindern.","Nach Ermessen des SL könnten die Pflanzen auch andere Aufgaben für dich erfüllen. Der Zauber ermöglicht es ihnen zwar nicht, sich zu entwurzeln und umherzulaufen, aber sie sind in der Lage, ihre Zweige, Ranken und Stiele frei zu bewegen.","Befindet sich eine Pflanzenkreatur in der Umgebung, kannst du mit ihr kommunizieren, als würdet ihr dieselbe Sprache sprechen. Du kannst sie jedoch nicht magisch beeinflussen.","Dieser Zauber kann bewirken, dass Pflanzen, die mit dem Zauber Verstricken erschaffen wurden, eine festgesetzte Kreatur freilassen."]},
  {"id":"meld-into-stone","name":"Mit Stein verschmelzen","en":"Meld Into Stone","level":3,"school":"transmutation","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"8 Stunden","conc":false,"ritual":true,"damage":{"type":"force","slots":{"3":"6d6"}},"desc":["Du betrittst einen steinernen Gegenstand oder eine Oberfläche, die groß genug ist, um deinen Körper aufzunehmen, und verschmilzt für die Wirkungsdauer mitsamt deiner gesamten Ausrüstung mit dem Stein. Du verwendest deine Bewegungsrate, um an einem Punkt, den du berühren kannst, in den Stein zu treten. Du bist nicht sichtbar und kannst nur auf magische Weise wahrgenommen werden.","Während du mit dem Stein verschmolzen bist, kannst du nicht sehen, was außerhalb vor sich geht. Du bist zudem bei Weisheitswürfen (Wahrnehmung), um Geräusche von außen zu hören, im Nachteil. Du bemerkst, wie die Zeit vergeht, und kannst Zauber auf dich selbst wirken. Zudem kannst du deine Bewegungsrate verwenden, um den Stein dort zu verlassen, wo du ihn betreten hast. Dadurch endet der Zauber. Anderenfalls kannst du dich nicht bewegen.","Geringer physischer Schaden am Stein verletzt dich nicht. Wird er teilweise zerstört oder seine Form verändert, so dass du nicht mehr hineinpasst, wirst du ausgestoßen und erleidest 6W6 Wuchtschaden. Wird der Stein vollständig zerstört oder in eine andere Substanz verwandelt, wirst du ausgestoßen und erleidest 50 Wuchtschaden. Wenn du ausgestoßen wirst, fällst du auf eine freie Stelle, die deinem Eintrittsort am nächsten liegt."]},
  {"id":"speak-with-dead","name":"Mit Toten sprechen","en":"Speak with Dead","level":3,"school":"necromancy","classes":["barde","kleriker"],"time":"1 Aktion","action":"action","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G, M","duration":"10 Minuten","conc":false,"ritual":false,"desc":["Du erfüllst einen Leichnam deiner Wahl in Reichweite mit dem Anschein von Leben und Intelligenz, damit er Fragen beantworten kann, die du ihm stellst Die Leiche muss einen Mund besitzen und darf nicht untot sein. Der Zauber scheitert, wenn die Leiche innerhalb der letzten zehn Tage bereits Ziel dieses Zaubers war.","Bis der Zauber endet, kannst du der Leiche bis zu fünf Fragen stellen. Die Leiche besitzt nur das Wissen, das sie zu Lebzeiten hatte, und spricht nur die zu Lebzeiten bekannten Sprachen. Die Antworten sind normalerweise kurz, kryptisch oder monoton. Der Leichnam muss dir nicht wahrheitsgemäß antworten, wenn du ihm feindlich gesinnt bist oder er dich als Feind ansieht. Dieser Zauber bringt nicht die Seele der Kreatur in ihren Körper zurück, nur ihren belebenden Geist Daher kann die Leiche keine neuen Informationen erhalten, nichts verstehen, das nach ihrem Tod geschehen ist und nicht über zukünftige Ereignisse mutmaßen."]},
  {"id":"create-food-and-water","name":"Nahrung und Wasser erschaffen","en":"Create Food and Water","level":3,"school":"conjuration","classes":["kleriker","druide","paladin","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du erschaffst 22,5 Kilogramm Nahrung und 120 Liter Wasser auf dem Boden oder in Behältern in Reichweite. Diese Vorräte reichen aus, um bis zu fünfzehn Humanoide oder fünf Reittiere 24 Stunden lang zu versorgen. Das Essen ist fade, aber nahrhaft, und verdirbt, wenn es nicht innerhalb von 24 Stunden gegessen wird. Das Wasser ist sauber und verdirbt nicht."]},
  {"id":"plant-growth","name":"Pflanzenwachstum","en":"Plant Growth","level":3,"school":"transmutation","classes":["barde","druide","waldlaeufer"],"time":"1 Aktion oder 8 Stunden","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"area":{"shape":"sphere","size":30},"desc":["Dieser Zauber kanalisiert Vitalität in Pflanzen in einem bestimmten Bereich. Es gibt zwei Anwendungsarten für diesen Zauber, die entweder unmittelbare oder langfristige Effekte haben.","Wirkst du diesen Zauber als Aktion, wähle einen Punkt in Reichweite aus. Alle normalen Pflanzen in einem Radius von 30 Metern um diesen Punkt wachsen und wuchern. Jede Kreatur in dem Bereich muss für jeden Meter, den sie sich bewegt, vier Meter ihrer Bewegungsrate verwenden.","Du kannst einen oder mehrere Bereiche beliebiger Größe im Wirkungsbereich davon ausschließen.","Wirkst du diesen Zauber im Verlauf von acht Stunden, machst du das Land fruchtbar. Alle Pflanzen in einem Radius von 0,8 Kilometern, der auf einem Punkt in Reichweite zentriert ist, werden ein Jahr lang ertragreich. Bei der Ernte erzeugen sie doppelt so viel Nahrung wie gewöhnlich."]},
  {"id":"sleet-storm","name":"Schneesturm","en":"Sleet Storm","level":3,"school":"conjuration","classes":["druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"area":{"shape":"cylinder","size":12},"desc":["Bis der Zauber endet, fallen Regen und Schnee in einem sechs Meter hohen Zylinder mit einem Radius von zwölf Metern, der auf einen Punkt deiner Wahl in Reichweite zentriert ist Der Bereich ist komplett verschleiert und offene Flammen erlöschen darin.","Der Boden in dem Bereich ist mit glattem Eis bedeckt und wird zu schwierigem Gelände. Wenn eine Kreatur den Bereich des Zaubers in einem Zug erstmals betritt oder ihren Zug darin beginnt, muss sie einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, fällt sie hin und ist liegend.","Konzentriert sich eine Kreatur im Bereich des Zaubers, muss sie einen Konstitutionsrettungswurf gegen deinen Zauberrettungswurf-SG bestehen, um nicht die Konzentration zu verlieren."]},
  {"id":"protection-from-energy","name":"Schutz vor Energie","en":"Protection From Energy","level":3,"school":"abjuration","classes":["kleriker","druide","waldlaeufer","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Für die Wirkungsdauer ist eine willige Kreatur, die du berührst, gegen eine Schadensart deiner Wahl resistent: Blitz, Feuer, Kälte, Säure oder Schall."]},
  {"id":"magic-circle","name":"Schutzkreis","en":"Magic Circle","level":3,"school":"abjuration","classes":["kleriker","paladin","hexenmeister","magier"],"time":"1 Minute","action":"long","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"save":"cha","area":{"shape":"cylinder","size":3},"desc":["Du erschaffst einen sechs Meter hohen Zylinder aus magischer Energie mit einem Radius von drei Metern, der in Reichweite auf einen Punkt auf dem Boden zentriert ist, den du sehen kannst. Leuchtende Runen erscheinen dort, wo der Zylinder den Boden oder eine andere Oberfläche überschneidet","Wähle einen oder mehrere der folgenden Kreaturentypen: celestische Wesen, Elementare, Feenwesen, Unholde oder Untote. Der Kreis beeinflusst eine Kreatur des gewählten Typs auf die folgende Art:","Wenn du diesen Zauber wirkst, kannst du seine Wirkung umkehren, so dass Kreaturen des ausgewählten Typs den Zylinder nicht verlassen können und Ziele außerhalb des Zylinders geschützt sind."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt die Wirkungsdauer für jeden Grad über dem 3. um eine Stunde."]},
  {"id":"stinking-cloud","name":"Stinkende Wolke","en":"Stinking Cloud","level":3,"school":"conjuration","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"con","area":{"shape":"sphere","size":6},"desc":["Du erschaffst eine Sphäre aus gelbem, übelriechendem Gas mit einem Radius von sechs Metern an einem Ort in Reichweite. Die Wolke breitet sich um Ecken aus und ihr Bereich ist komplett verschleiert. Sie schwebt für die Wirkungsdauer in der Luft.","Jede Kreatur, die sich zu Beginn ihres Zugs vollständig in der Wolke befindet, muss einen Konstitutionsrettungswurf gegen Gift ausführen. Scheitert der Wurf, verbringt die Kreatur ihre Aktion in dieser Runde mit Würgen und Taumeln. Kreaturen, die nicht atmen müssen oder gegen Gift immun sind, bestehen diesen Rettungswurf automatisch.","Ein mäßiger Wind (mindestens 16 Kilometer pro Stunde) löst die Wolke nach vier Runden auf. Ein starker Wind (mindestens 32 Kilometer pro Stunde) löst sie nach einer Runde auf."]},
  {"id":"daylight","name":"Tageslicht","en":"Daylight","level":3,"school":"evocation","classes":["kleriker","druide","paladin","waldlaeufer","zauberer"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"1 Stunde","conc":false,"ritual":false,"area":{"shape":"sphere","size":18},"desc":["Eine Sphäre aus Licht breitet sich von einem Punkt deiner Wahl in Reichweite mit einem Radius von 18 Metern aus. Bei der Sphäre handelt es sich um helles Licht, das weitere 18 Meter dämmriges Licht gewährt.","Wenn der gewählte Punkt ein Objekt ist, das du hältst oder das nicht getragen wird, geht das Licht von diesem Objekt aus und bewegt sich mit ihm mit. Das Licht wird blockiert, wenn seine Quelle mit einem undurchsichtigen Objekt wie einer Schüssel oder einem Helm bedeckt wird.","Wenn sich der Wirkbereich dieses Zaubers mit dem einer Dunkelheit überschneidet, die durch einen Zauber des 3. Grades oder niedriger erzeugt wurde, so wird die Dunkelheit gebannt."]},
  {"id":"conjure-animals","name":"Tiere beschwören","en":"Conjure Animals","level":3,"school":"conjuration","classes":["druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du beschwörst Feengeister in Form von Tieren, die in freien Bereichen in Reichweite erscheinen, die du sehen kannst. Wähle eine der folgenden Optionen aus:","Jedes Tier ist gleichzeitig ein Feenwesen und verschwindet, wenn der Zauber endet oder seine Trefferpunkte auf 0 sinken.","Die beschworenen Kreaturen sind dir und deinen Gefährten freundlich gesinnt. Würfle die Initiative für die beschworenen Kreaturen als Gruppe aus, die über ihren eigenen Zug verfügt. Sie gehorchen deinen mündlichen Befehlen (erfordert keine Aktion), Wenn du ihnen keine Befehle erteilst, verteidigen sie sich gegen feindlich gesinnte Kreaturen, führen aber anderenfalls keine Aktionen aus.","Der SL hat die Werte der Kreaturen."],"higher":["Wirkst du diesen Zauber mit bestimmten Zauberplätzen höheren Grades, erscheinen mehr Kreaturen, wenn du eine der oben genannten Optionen auswählst: doppelt so viele mit einem Zauberplatz des 5. Grades, dreimal so viele mit einem Zauberplatz des 7. Grades und viermal so viele mit einem Zauberplatz des 9. Grades."]},
  {"id":"animate-dead","name":"Tote beleben","en":"Animate Dead","level":3,"school":"necromancy","classes":["kleriker","magier"],"time":"1 Minute","action":"long","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Dieser Zauber erschafft einen untoten Diener. Wähle einen Knochenhaufen oder die Leiche eines kleinen oder mittelgroßen Humanoiden in Reichweite. Dein Zauber durchdringt das Ziel mit einer verdorbenen Nachahmung des Lebens und erweckt es zu einer untoten Kreatur. Das Ziel wird zu einem Skelett, wenn du Knochen wählst, oder zu einem Zombie, wenn du eine Leiche wählst (der SL hat die Spielwerte der Kreatur),","Du kannst deine Bonusaktion in jedem deiner Züge verwenden, um jede Kreatur, die du mit diesem Zauber belebt hast und die sich im Abstand von bis zu 18 Metern von dir befindet, mental zu befehligen. Wenn du mehrere Kreaturen kontrollierst, kannst du gleichzeitig eine oder alle befehligen, wobei jeder derselbe Befehl erteilt wird. Du entscheidest über die Aktion der Kreatur und ihre Bewegung in ihrem nächsten Zug. Alternativ kannst du einen allgemeinen Befehl erteilen, etwa das Bewachen einer bestimmten Kammer oder eines Korridors. Erteilst du keine Befehle, verteidigt sich die Kreatur lediglich gegen feindlich gesinnte Kreaturen. Sobald die Kreatur einen Befehl erhalten hat, führt sie ihn aus, bis die Aufgabe abgeschlossen ist.","Die Kreatur steht 24 Stunden lang unter deiner Kontrolle. Danach folgt sie keinem deiner Befehle mehr. Um weitere 24 Stunden die Kontrolle über die Kreatur zu behalten, musst du diesen Zauber vor dem Ablauf der ersten 24 Stunden erneut auf die Kreatur wirken. Setzt du den Zauber auf diese Weise ein, erlangst du die Kontrolle über bis zu vier Kreaturen, die du mit diesem Zauber belebt hast, anstatt einen neuen Diener zu erschaffen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, kannst du für jeden Grad über dem 3. Grad zwei zusätzliche untote Kreaturen beleben oder wieder unter deine Kontrolle bringen. Für jede Kreatur benötigst du eine separate Leiche oder einen separaten Knochenhaufen."]},
  {"id":"nondetection","name":"Unauffindbarkeit","en":"Nondetection","level":3,"school":"abjuration","classes":["barde","waldlaeufer","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":false,"desc":["Für die Wirkungsdauer verbirgst du ein Ziel, das du berührst, vor Erkenntniszaubern. Beim Ziel kann es sich um eine bereitwillige Kreatur, einen Ort oder einen Gegenstand handeln, die oder der in keiner Abmessung größer als drei Meter sein darf. Das Ziel kann nicht von Erkenntniszaubern beeinflusst oder durch magische Ausspähungssensoren wahrgenommen werden."]},
  {"id":"vampiric-touch","name":"Vampirgriff","en":"Vampiric Touch","level":3,"school":"necromancy","classes":["hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"attack":"melee","damage":{"type":"necrotic","slots":{"3":"3d6"}},"heal":{"dice":"3d6","mod":false},"desc":["Die Berührung deiner in Schatten gehüllten Hand entzieht anderen Lebenskraft, um dich zu heilen. Führe einen Nahkampf-Zauberangriff gegen eine Kreatur innerhalb deiner Reichweite aus. Bei einem Treffer erleidet das Ziel 3W6 nekrotischen Schaden und du erhältst Trefferpunkte in Höhe der Hälfte des nekrotischen Schadens zurück. Bis der Zauber endet, kannst du in jedem deiner Züge den Angriff als Aktion wiederholen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 3. um 1W6."]},
  {"id":"slow","name":"Verlangsamen","en":"Slow","level":3,"school":"transmutation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","area":{"shape":"cube","size":12},"desc":["Du verlangsamst die Zeit um bis zu sechs Kreaturen deiner Wahl in einem Würfel mit zwölf Metern Kantenlänge in Reichweite. Jedes Ziel muss einen Weisheitsrettungswurfbestehen oder es wird für die Wirkungsdauer von diesem Zauber betroffen.","Die Bewegungsrate eines betroffenen Ziels wird halbiert, es erleidet einen Malus von -2 auf seine RK und Geschicklichkeitsrettungswürfe. Außerdem kann es keine Reaktionen verwenden. Es kann in seinem Zug entweder eine Aktion oder eine","Bonusaktion einsetzen, aber nicht beides. Unabhängig von den Fähigkeiten oder magischen Gegenständen der Kreatur kann sie in ihrem Zug maximal einen Nahkampf- oder Fernkampfangriff ausführen.","Versucht die Kreatur, einen Zauber mit einem Zeitaufwand von einer Aktion zu wirken, würfle mit einem W20. Bei einer 11 oder höher tritt der Zauber erst beim nächsten Zug der Kreatur in Kraft und die Kreatur muss ihre Aktion in jenem Zug verwenden, um den Zauber abzuschließen. Falls dies nicht möglich ist, ist der Zauber vergeudet","Eine von diesem Zauber betroffene Kreatur muss am Ende ihres Zugs einen weiteren Weisheitsrettungswurf ausführen. Ist der Rettungswurf erfolgreich, endet der Effekt für die Kreatur."]},
  {"id":"sending","name":"Verständigung","en":"Sending","level":3,"school":"evocation","classes":["barde","kleriker","magier"],"time":"1 Aktion","action":"action","range":"Unbegrenzt","rangeKind":"unl","rangeM":null,"comps":"V, G, M","duration":"1 Runde","conc":false,"ritual":false,"desc":["Du sendest eine kurze Nachricht von höchstens 25 Wörtern an eine Kreatur, mit der du vertraut bist. Die Kreatur hört die Nachricht in ihrem Kopf, erkennt dich als Absender, wenn sie dich kennt, und kann auf gleiche Weise sofort antworten. Der Zauber ermöglicht es Kreaturen mit einem Intelligenzwert von mindestens 1, die Bedeutung deiner Nachricht zu verstehen.","Du kannst die Nachricht über beliebige Entfernungen und sogar auf andere Ebenen senden. Befindet sich das Ziel jedoch auf einer anderen Ebene als du, besteht ein Risiko von fünf Prozent, dass die Nachricht nicht ankommt."]},
  {"id":"spirit-guardians","name":"Wächtergeister","en":"Spirit Guardians","level":3,"school":"conjuration","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"Selbst (Radius von 4,5 Metern)","rangeKind":"self","rangeM":0,"comps":"V, G, M","material":"ein heiliges Symbol","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"save":"wis","damage":{"type":"radiant","slots":{"3":"3d8"}},"area":{"shape":"sphere","size":4.5},"desc":["Du rufst Geister herbei, die dich beschützen. Sie schwirren während der Wirkungsdauer in einer Entfernung von 4,5 Metern um dich herum. Wenn du gut oder neutral bist, erscheint ihre Spektralform engelsgleich oder feenhaft (deine Wahl). Wenn du böse bist, erscheinen sie teuflisch.","Wenn du diesen Zauber wirkst, kannst du eine beliebige Anzahl von Kreaturen bestimmen, die du sehen kannst. Sie werden von dem Zauber nicht betroffen. Die Bewegungsrate betroffener Kreaturen wird im Wirkungsbereich halbiert. Wenn eine Kreatur den Wirkungsbereich in einem Zug erstmals betritt oder ihren Zug darin beginnt, muss sie einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 3W8 gleißenden Schaden (wenn du gut oder neutral bist) oder 3W8 nekrotischen Schaden (wenn du böse bist). Bei einem erfolgreichen Rettungswurf erleidet die Kreatur halb so viel Schaden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 4. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 3. um 1W8."]},
  {"id":"water-breathing","name":"Wasser atmen","en":"Water Breathing","level":3,"school":"transmutation","classes":["druide","waldlaeufer","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":true,"desc":["Bis zu zehn bereitwillige Kreaturen in Reichweite, die du sehen kannst, können bis zum Ende des Zaubers unter Wasser atmen. Betroffene Kreaturen verfügen weiterhin über ihre normale Atmung."]},
  {"id":"revivify","name":"Wiederbeleben","en":"Revivify","level":3,"school":"necromancy","classes":["kleriker","paladin","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst eine Kreatur, die innerhalb der letzten Minute gestorben ist. Diese Kreatur wird mit 1 Trefferpunkt wieder lebendig. Dieser Zauber kann keine Kreatur wieder zum Leben erwecken, die an Altersschwäche gestorben ist, und auch keine fehlenden Körperteile wiederherstellen."]},
  {"id":"wind-wall","name":"Windwall","en":"Wind Wall","level":3,"school":"evocation","classes":["druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"str","damage":{"type":"bludgeoning","slots":{"3":"3d8"}},"area":{"shape":"line","size":15,"width":1.5},"desc":["Eine Wand aus starkem Wind erscheint an einem Punkt deiner Wahl in Reichweite. Die Wand kann bis zu 15 Meter lang, 4,5 Meter hoch und 30 Zentimeter dick sein. Du kannst die Wand beliebig formen, solange sie einem ununterbrochenen Pfad auf dem Boden folgt. Sie bleibt für die Wirkungsdauer bestehen.","Wenn die Wand erscheint, muss jede Kreatur in ihrem Bereich einen Stärkerettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 3W8 Wuchtschaden, anderenfalls die Hälfte.","Der starke Wind hält Nebel, Rauch und andere Gase auf Abstand. Maximal kleine fliegende Kreaturen oder Gegenstände können die Wand nicht durchdringen. Lose, leichte Materialien, die in die Wand gebracht werden, fliegen nach oben. Pfeile, Bolzen und andere gewöhnliche Geschosse, die auf Ziele hinter der Wand geschossen werden, werden nach oben abgelenkt und verfehlen ihr Ziel automatisch. (Felsbrocken, die von Riesen oder Belagerungsmaschinen geschleudert werden, und ähnliche Geschosse sind hiervon nicht betroffen.) Kreaturen in gasförmiger Gestalt können die Wand nicht passieren."]},
  {"id":"tongues","name":"Zungen","en":"Tongues","level":3,"school":"divination","classes":["barde","kleriker","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, M","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Dieser Zauber gewährt der berührten Kreatur die Fähigkeit, jede gesprochene Sprache zu verstehen, die sie hört Wenn das Ziel spricht, können außerdem alle Kreaturen verstehen, was es sagt, die mindestens eine Sprache beherrschen und das Ziel hören können."]},
  {"id":"arcane-eye","name":"Arkanes Auge","en":"Arcane Eye","level":4,"school":"divination","classes":["kleriker","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"area":{"shape":"sphere","size":9},"desc":["Du erschaffst ein unsichtbares, magisches Auge in Reichweite, das für die Wirkungsdauer in der Luft schwebt.","Du erhältst mental visuelle Informationen von dem Auge, das über normale Sicht und Dunkelsicht bis zu neun Metern verfügt. Das Auge kann in alle Richtungen blicken.","Du kannst als Aktion das Auge bis zu neun Meter in jede Richtung bewegen. Es kann sich beliebig weit von dir entfernen, aber keine andere Existenzebene betreten. Eine solide Barriere blockiert die Bewegung des Auges. Es kann jedoch Öffnungen mit 2,5 Zentimetern Durchmesser passieren."]},
  {"id":"freedom-of-movement","name":"Bewegungsfreiheit","en":"Freedom of Movement","level":4,"school":"abjuration","classes":["barde","kleriker","druide","waldlaeufer","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Du berührst eine bereitwillige Kreatur. Für die Wirkungsdauer wird die Bewegungsrate des Ziels nicht von schwierigem Gelände eingeschränkt. Zudem können Zauber oder andere magische Effekte weder seine Bewegungsrate verringern noch das Ziel lähmen oder festsetzen.","Das Ziel kann außerdem 1,5 Meter seiner Bewegungsrate verwenden, um nichtmagischen Fesseln automatisch zu entkommen (beispielsweise Handschellen oder einer Kreatur, die es gepackt hat). Die Bewegungsrate oder Angriffe des Ziels unterliegen keinem Nachteilen, wenn es sich unter Wasser befindet"]},
  {"id":"dimension-door","name":"Dimensionstür","en":"Dimension Door","level":4,"school":"conjuration","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"150 m","rangeKind":"dist","rangeM":150,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"damage":{"type":"force","slots":{"4":"4d6"}},"desc":["Du teleportierst dich von deiner aktuellen Position zu einem beliebigen anderen Ort in Reichweite. Dabei triffst du genau an dem gewünschten Punkt ein. Es kann sich um einen Ort handeln, den du sehen oder dir vorstellen kannst, oder den du beschreibst, indem du die Entfernung und Richtung angibst (beispielsweise '60 Meter direkt nach unten' oder '90 Meter nordöstlich in einem 45-Grad-Winkel nach oben').","Du kannst Gegenstände mitnehmen, sofern ihr Gewicht deine Traglast nicht übersteigt. Du kannst auch eine bereitwillige Kreatur deiner Größe oder kleiner mit Ausrüstung bis zu ihrer Traglast mitnehmen. Die Kreatur muss sich im Abstand von bis zu 1,5 Metern von dir befinden, wenn du diesen Zauber wirkst.","Würdest du an einem Ort ankommen, an dem sich bereits ein Gegenstand oder eine Kreatur befindet, erleidet du und dein Mitreisender jeweils 4W6 Energieschaden und werdet nicht teleportiert."]},
  {"id":"ice-storm","name":"Eissturm","en":"Ice Storm","level":4,"school":"evocation","classes":["druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"90 m","rangeKind":"dist","rangeM":90,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"bludgeoning","slots":{"4":"2d8","5":"3d8","6":"4d8","7":"5d8","8":"6d8","9":"7d8"}},"area":{"shape":"cylinder","size":6},"desc":["Ein Hagel aus steinhartem Eis hämmert in einem zwölf Meter hohen Zylinder mit einem Radius von sechs Metern auf den Boden. Der Zylinder ist auf einen Punkt in Reichweite zentriert. Jede Kreatur im Zylinder muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 2W8 Wuchtschaden und 4W6 Kälteschaden, anderenfalls die Hälfte.","Hagelkörner verwandeln den Wirkungsbereich des Sturms bis zum Ende deines nächsten Zugs in schwieriges Gelände."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 5. Grades oder höher nutzt, steigt der Wuchtschaden für jeden Grad über dem 4. um 1W8."]},
  {"id":"fire-shield","name":"Feuerschild","en":"Fire Shield","level":4,"school":"evocation","classes":["magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"10 Minuten","conc":false,"ritual":false,"damage":{"type":"fire","slots":{"4":"2d8"}},"area":{"shape":"sphere","size":1.5},"desc":["Feine Flammen umgeben deinen Körper für die Wirkungsdauer und spenden in einem Radius von drei Metern helles Licht und in einem Radius von zusätzlichen drei Metern dämmriges Licht Du kannst den Zauber als Aktion vorzeitig beenden.","Die Flammen verleihen dir einen Wärmeschild oder einen Kälteschild (deine Wahl), Der Wärmeschild gewährt dir Resistenz gegen Kälteschaden, der Kälteschild Resistenz gegen Feuerschaden.","Immer, wenn dich eine Kreatur im Abstand von bis zu 1,5 Metern von dir mit einem Nahkampfangriff trifft, geht der Schild in Flammen auf. Der Angreifer erleidet 2W8 Feuerschaden von einem Wärmeschild und 2W8 Kälteschaden von einem Kälteschild."]},
  {"id":"wall-of-fire","name":"Feuerwand","en":"Wall of Fire","level":4,"school":"evocation","classes":["druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"dex","damage":{"type":"fire","slots":{"4":"5d8"}},"area":{"shape":"line","size":18,"width":1.5},"desc":["Du erschaffst eine Feuerwand auf einer festen Oberfläche in Reichweite. Du kannst eine gerade Wand erschaffen, die bis zu 18 Meter lang ist, oder eine ringförmige Wand mit bis zu sechs Metern Durchmesser. In beiden Fällen ist die Wand sechs Meter hoch und 0,3 Meter dick Die Wand ist undurchsichtig und bleibt für die Wirkungsdauer bestehen.","Wenn die Wand erscheint, muss jede Kreatur in ihrem Bereich einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 5W8 Feuerschaden, anderenfalls die Hälfte.","Eine Seite der Wand, die du beim Wirken des Zaubers bestimmst, fügt jeder Kreatur 5W8 Feuerschaden zu, die ihren Zug im Abstand von bis zu drei Metern von dieser Seite oder in der Wand beendet. Eine Kreatur erleidet den Schaden ebenfalls, wenn sie die Wand in einem Zug erstmals betritt. Die andere Seite der Wand verursacht keinen Schaden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 5. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 4. um 1W8."]},
  {"id":"secret-chest","name":"Geheime Truhe","en":"Secret Chest","level":4,"school":"conjuration","classes":["magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du versteckst eine Truhe und ihren gesamten Inhalt auf der Ätherebene. Du musst die Truhe und die winzige Nachbildung berühren, die als Materialkomponenten für den Zauber dienen. Die Truhe kann bis zu 336 Liter anorganischen Materials aufhehmen (90 mal 60 mal 60 Zentimeter),","Solange sich die Truhe auf der Ätherebene befindet, kannst du als Aktion die Nachbildung berühren, um die Truhe herbeizurufen. Sie erscheint in einem freien Bereich auf dem Boden im Abstand von bis zu 1,5 Metern von dir. Du kannst die Truhe wieder auf die Ätherebene zurückschicken, indem du sie und die Nachbildung als Aktion gleichzeitig berührst.","Nach 60 Tagen besteht eine kumulative Chance von fünf Prozent pro Tag, dass der Zauber endet. Er endet zudem, wenn du den Zauber erneut wirkst, wenn die kleine Nachbildung zerstört wird oder wenn du den Zauber als Aktion beendest Endet der Zauber, während sich die große Truhe auf der Ätherebene befindet, ist sie unwiederbringlich verloren."]},
  {"id":"guardian-of-faith","name":"Hüter des Glaubens","en":"Guardian of Faith","level":4,"school":"conjuration","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V","duration":"8 Stunden","conc":false,"ritual":false,"save":"dex","area":{"shape":"cylinder","size":3},"desc":["Ein großer, geisterhafter Wächter erscheint in Reichweite an einer freien Stelle deiner Wahl, die du sehen kannst. Er schwebt dort für die Wirkungsdauer. Der Wächter besetzt diesen Bereich und ist bis auf ein leuchtendes Schwert und einen Schild mit dem Symbol deiner Gottheit nicht zu erkennen.","Alle Kreaturen, die dir feindlich gesinnt sind und sich dem Wächter in einem Zug erstmals auf bis zu drei Meter nähern, müssen einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 20 gleißenden Schaden, anderenfalls die Hälfte. Der Wächter verschwindet, wenn er insgesamt 60 Schaden verursacht hat."]},
  {"id":"locate-creature","name":"Kreatur aufspüren","en":"Locate Creature","level":4,"school":"divination","classes":["barde","kleriker","druide","paladin","waldlaeufer","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Beschreibe oder nenne eine Kreatur, mit der du vertraut bist. Solange sich die Kreatur im Abstand von bis zu 300 Metern von dir befindet, spürst du, in welcher Richtung ihr Aufenthaltsort liegt. Bewegt sich die Kreatur, weißt du, in welche Richtung sie sich bewegt.","Der Zauber kann eine bestimmte dir bekannte Kreatur aufspüren oder die nächstgelegene Kreatur einer bestimmten Art (wie ein Mensch oder ein Einhorn), sofern du eine derartige Kreatur mindestens einmal aus der Nähe (aus maximal neun Metern Entfernung) gesehen hast. Hat die von dir beschriebene oder genannte Kreatur eine andere Gestalt angenommen, wie beispielsweise unter dem Effekt des Zaubers Verwandlung, spürt dieser Zauber die Kreatur nicht auf.","Dieser Zauber kann die Kreatur nicht aufspüren, wenn fließendes Wasser mit einer Breite von mindestens drei Metern den direkten Weg zwischen dir und der Kreatur blockiert."]},
  {"id":"greater-invisibility","name":"Mächtige Unsichtbarkeit","en":"Greater Invisibility","level":4,"school":"illusion","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Du - oder eine Kreatur, die du berührst - wirst unsichtbar, bis der Zauber endet. Alles, was das Ziel trägt, ist unsichtbar, solange es an der Person bleibt."]},
  {"id":"blight","name":"Plage","en":"Blight","level":4,"school":"necromancy","classes":["druide","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"necrotic","slots":{"4":"8d8"}},"desc":["Nekromantische Energie trifft eine Kreatur deiner Wahl in Reichweite, die du sehen kannst, und entzieht ihr Feuchtigkeit und Vitalität. Das Ziel muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet das Ziel 8W8 nekrotischen Schaden, anderenfalls die Hälfte. Dieser Zauber wirkt nicht auf Untote oder Konstrukte.","Wenn du eine Pflanzenkreatur oder eine magische Pflanze als Ziel des Zaubers wählst, ist sie beim Rettungswurf im Nachteil und der Zauber fügt ihr maximalen Schaden zu.","Wenn du eine nichtmagische Pflanze als Ziel wählst, die keine Kreatur ist, etwa einen Baum oder Strauch, führt sie keinen Rettungswurf aus. Sie verdorrt einfach und stirbt."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 5. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 4. um 1W8."]},
  {"id":"private-sanctum","name":"Privates Heiligtum","en":"Private Sanctum","level":4,"school":"abjuration","classes":["magier","magieschmied"],"time":"10 Minuten","action":"long","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":false,"area":{"shape":"cube","size":30},"desc":["Du sicherst einen Bereich in Reichweite auf magische Weise. Dabei handelt es sich um einen Würfel mit einer Kantenlänge zwischen 1,5 und 30 Metern. Der Zauber bleibt für die Wirkungsdauer bestehen oder bis du ihn als Aktion beendest.","Beim Wirken des Zaubers entscheidest du, welche Sicherheit er bietet. Du kannst beliebig viele der folgenden Eigenschaften auswählen:","Wirkst du diesen Zauber ein Jahr lang jeden Tag am selben Ort, wird der Effekt dauerhaft."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 5. Grades oder höher nutzt, kannst du für jeden Grad über dem 4. die Größe des Würfels um 30 Meter erweitern. Somit könntest du mit einem Zauberplatz des 5. Grades einen Würfel mit 60 Metern Kantenlänge schützen."]},
  {"id":"giant-insect","name":"Rieseninsekt","en":"Giant Insect","level":4,"school":"transmutation","classes":["druide"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Für die Wirkungsdauer verwandelst du bis zu zehn Tausendfüßler, drei Spinnen, fünf Wespen oder einen Skorpion in Reichweite in riesige Versionen ihrer normalen Gestalt. Ein Tausendfüßler wird zu einem Riesentausendfüßler, eine Spinne zu einer Riesenspinne, eine Wespe zu einer Riesenwespe und ein Skorpion zu einem Riesenskorpion.","Jede Kreatur gehorcht deinen verbalen Befehlen. Im Kampf handelt sie in jeder Runde in deinem Zug. Der SL hat die Spielwerte für diese Kreaturen und wickelt ihre Aktionen und Bewegung ab.","Kreaturen bleiben in ihrer Riesengestalt, bis die Wirkungsdauer abgelaufen ist, ihre Trefferpunkte auf 0 sinken oder du den Zauber als Aktion beendest.","Der SL erlaubt dir möglicherweise, andere Ziele auszuwählen. Beispielsweise könntest du eine Biene verwandeln, die über dieselben Spielwerte wie eine Riesenwespe verfügt."]},
  {"id":"hallucinatory-terrain","name":"Scheingelände","en":"Hallucinatory Terrain","level":4,"school":"illusion","classes":["barde","druide","hexenmeister","magier"],"time":"10 Minuten","action":"long","range":"90 m","rangeKind":"dist","rangeM":90,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":false,"area":{"shape":"cube","size":45},"desc":["Du lässt natürliches Gelände innerhalb eines Würfels mit 45 Metern Kantenlänge wie ein anderes natürliches Gelände aussehen, klingen und riechen. Weite Felder oder eine Straße können somit wie ein Sumpf, ein Hügel, eine Erdspalte oder anderes schwieriges oder unpassierbares Gelände erscheinen. Ein Tümpel kann wie eine grüne Wiese wirken, ein Abhang wie ein sanftes Gefälle oder ein mit Felsen übersäter Graben wie eine breite, flache Straße. Bauwerke, Ausrüstung und Kreaturen im Bereich verändern ihr Aussehen nicht.","Die ertastbaren Eigenschaften des Geländes bleiben unverändert, so dass Kreaturen, die den Bereich betreten, die Illusion wahrscheinlich durchschauen. Ist der Unterschied bei Berührung nicht offensichtlich, kann eine Kreatur die Illusion sorgfältig untersuchen. Sie kann einen Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG ausführen, um sie zu durchschauen. Eine Kreatur, die die Illusion als solche erkennt, sieht sie als vages Bild über dem darunter befindlichen Gelände."]},
  {"id":"conjure-minor-elementals","name":"Schwache Elementare beschwören","en":"Conjure Minor Elementals","level":4,"school":"conjuration","classes":["druide","magier"],"time":"1 Minute","action":"long","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du beschwörst Elementare, die in freien Bereichen in Reichweite erscheinen, die du sehen kannst. Wähle eine der folgenden Optionen aus:","Ein auf diese Weise beschworener Elementar verschwindet, wenn der Zauber endet oder seine Trefferpunkte auf 0 sinken.","Die beschworenen Kreaturen sind dir und deinen Gefährten freundlich gesinnt. Würfle die Initiative für die beschworenen Kreaturen als Gruppe aus, die über ihren eigenen Zug verfügt. Sie gehorchen deinen mündlichen Befehlen (erfordert keine Aktion), Wenn du ihnen keine Befehle erteilst, verteidigen sie sich gegen feindlich gesinnte Kreaturen, führen aber anderenfalls keine Aktionen aus.","Der SL hat die Werte der Kreaturen."],"higher":["Wirkst du diesen Zauber mit bestimmten Zauberplätzen höheren Grades, erscheinen mehr Kreaturen, wenn du eine der oben genannten Optionen auswählst: doppelt so viele mit einem Zauberplatz des 6. Grades und dreimal so viele mit einem Zauberplatz des 8. Grades."]},
  {"id":"black-tentacles","name":"Schwarze Tentakel","en":"Black Tentacles","level":4,"school":"conjuration","classes":["magier"],"time":"1 Aktion","action":"action","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"dex","damage":{"type":"bludgeoning","slots":{"4":"3d6"}},"area":{"shape":"cube","size":6},"desc":["Zuckende tiefschwarze Tentakel füllen einen sechs Meter großen, würfelförmigen Bereich in Reichweite, den du sehen kannst. Während der Wirkungsdauer verwandeln diese Tentakel den Boden im Bereich in schwieriges Gelände.","Kreaturen, die in ihrem Zug in den betroffenen Bereich gelangen oder den Zug darin beginnen, müssen einen Geschicklichkeitsrettungswurfbestehen. Anderenfalls erleiden sie 3W6 Wuchtschaden und sind von den Tentakeln festgesetzt, bis der Zauber endet. Jede Kreatur, die ihren Zug im Bereich beginnt und bereits von den Tentakeln festgesetzt wurde, erleidet 3W6 Wuchtschaden.","Eine von den Tentakeln festgesetzte Kreatur kann als Aktion einen Stärke- oder Geschicklichkeitswurf (ihrer Wahl) gegen deinen Zauberrettungswurf-SG ausführen. Bei einem Erfolg befreit sie sich."]},
  {"id":"stone-shape","name":"Stein formen","en":"Stone Shape","level":4,"school":"transmutation","classes":["kleriker","druide","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst einen maximal mittelgroßen, steinernen Gegenstand oder einen Bereich aus Stein, der in keiner Abmessung größer als 1,5 Meter sein darf, und verformst ihn nach deinen Wünschen. Du könntest beispielsweise einen großen Felsen in eine Waffe, einen Götzen oder eine Truhe formen, oder einen kleinen Durchgang durch eine Mauer schaffen, solange die Mauer nicht dicker als 1,5 Meter ist. Du könntest auch eine Steintür oder ihren Rahmen umformen, um sie zu versiegeln. Der von dir erschaffene Gegenstand kann bis zu zwei Scharniere und einen Riegel besitzen, feinere mechanische Details sind jedoch nicht möglich."]},
  {"id":"stoneskin","name":"Steinhaut","en":"Stoneskin","level":4,"school":"abjuration","classes":["druide","waldlaeufer","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Der Zauber macht das Fleisch einer bereitwilligen Kreatur, die du berührst, so hart wie Stein. Bis der Zauber endet, ist das Ziel gegen nichtmagischen Hieb-, Stich und Wuchtschaden resistent."]},
  {"id":"dominate-beast","name":"Tier beherrschen","en":"Dominate Beast","level":4,"school":"enchantment","classes":["druide","zauberer"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Du versuchst, ein Tier in Reichweite zu betören, das du sehen kannst. Es muss einen Weisheitsrettungswurfbestehen oder es wird für die Wirkungsdauer von dir bezaubert Wenn du oder deine Verbündeten gegen das Tier kämpfen, ist es beim Rettungswurf im Vorteil.","Während das Tier bezaubert ist und ihr euch auf derselben Existenzebene aufhaltet, verfügst du über eine telepathische Verbindung zu ihm. Diese kannst du verwenden, um der Kreatur Befehle zu erteilen, solange du bei Bewusstsein bist (erfordert keine Aktion), Die Kreatur befolgt diese nach Kräften. Du kannst eine einfache, allgemeine Aktion angeben, wie 'Greife diese Kreatur an', 'Lauf dorthin' oder 'Hole diesen Gegenstand'. Wenn die Kreatur den Befehl erfüllt hat und keine weiteren Anweisungen von dir erhält, verteidigt sie sich und versucht nach Kräften, am Leben zu bleiben.","Du kannst eine Aktion verwenden, um vollständige und präzise Kontrolle über das Ziel zu erlangen. Bis zum Ende deines nächsten Zugs führt die Kreatur nur Aktionen deiner Wahl aus und tut nichts, was du ihr nicht erlaubst. Währenddessen kannst du die Kreatur auch reagieren lassen, allerdings musst du dafür deine eigene Reaktion verwenden.","Jedes Mal, wenn das Ziel Schaden erleidet, führt es einen neuen Weisheitsrettungswurf gegen den Zauber aus. Ist der Rettungswurf erfolgreich, endet der Zauber."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 5. Grades nutzt, ändert sich die Wirkungsdauer zu: Konzentration, bis zu 10 Minuten. Bei einem Zauberplatz des 6. Grades beträgt die Wirkungsdauer: Konzentration, bis zu 1 Stunde. Bei einem Zauberplatz des 7. Grades beträgt die Wirkungsdauer: Konzentration, bis zu 8 Stunden."]},
  {"id":"death-ward","name":"Todesschutz","en":"Death Ward","level":4,"school":"abjuration","classes":["kleriker","paladin"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"8 Stunden","conc":false,"ritual":false,"desc":["Du berührst eine Kreatur und verleihst ihr einen gewissen Schutz vor dem Tod.","Wenn die Trefferpunkte des Ziels durch erlittenen Schaden erstmals auf 0 sinken würden, sinken sie stattdessen auf 1 Trefferpunkt und der Zauber endet.","Erleidet das Ziel während der Wirkungsdauer einen Effekt, der es sofort töten würde, ohne Schaden zu verursachen, wird die Kreatur nicht von diesem Effekt betroffen und der Zauber endet."]},
  {"id":"phantasmal-killer","name":"Tödliches Phantom","en":"Phantasmal Killer","level":4,"school":"illusion","classes":["magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","damage":{"type":"psychic","slots":{"4":"4d10"}},"desc":["Du zapfst die Alpträume einer Kreatur in Reichweite an, die du sehen kannst, und erschaffst eine illusionäre Manifestation ihrer tiefsten Ängste, die nur für diese Kreatur sichtbar ist. Das Ziel muss einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, ist das Ziel für die Wirkungsdauer verängstigt. Bis der Zauber endet, muss das Ziel am Ende jedes seiner Züge einen Weisheitsrettungswurfbestehen, oder es erleidet 4W10 psychischen Schaden.","Bei einem erfolgreichen Wurf endet der Zauber."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 5. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 4. um 1W10."]},
  {"id":"faithful-hound","name":"Treuer Hund","en":"Faithful Hound","level":4,"school":"conjuration","classes":["magier","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":false,"attack":"melee","damage":{"type":"force","slots":{"4":"4d8"}},"desc":["Du beschwörst einen geisterhaften Wachhund an einer freien Stelle in Reichweite, die du sehen kannst. Der Wachhund bleibt für die Wirkungsdauer bestehen, bis du ihn als Aktion fortschickst oder du dich mehr als 30 Meter von ihm entfernst.","Der Hund ist für alle Kreaturen außer dir unsichtbar und kann nicht verletzt werden. Wenn sich ihm eine mindestens kleine Kreatur auf neun Meter nähert, ohne zuvor das Passwort zu sprechen, das du beim Wirken des Zaubers festlegst, bellt der Hund laut. Der Hund sieht unsichtbare Kreaturen und kann in die Ätherebene sehen. Er ignoriert Illusionen.","Zu Beginn jedes deiner Züge versucht der Hund, eine Kreatur im Abstand von bis zu 1,5 Metern von ihm zu beißen, die dir feindlich gesinnt ist. Der Angriffsbonus des Hunds entspricht deinem Zauberwirken-Attributsmodifikator + deinem Übungsbonus. Bei einem Treffer verursacht er 4W8 Stichschaden."]},
  {"id":"resilient-sphere","name":"Unverwüstliche Sphäre","en":"Resilient Sphere","level":4,"school":"evocation","classes":["magier","magieschmied"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"dex","desc":["Eine Sphäre aus schimmernder Energie umschließt eine maximal große Kreatur oder einen maximal großen Gegenstand in Reichweite. Eine unwillige Kreatur muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, ist die Kreatur für die Wirkungsdauer eingeschlossen.","Physische Objekte, Energie und Zaubereffekte können die Barriere nicht durchdringen, weder von außen noch von innen. Eine Kreatur in der Sphäre kann jedoch atmen. Die Sphäre ist gegen alle Schadensarten immun, und eine Kreatur oder ein Gegenstand im Innern kann nicht von Angriffen oder Effekten von außerhalb verletzt werden. Gleichermaßen kann eine Kreatur in der Sphäre nichts außerhalb davon verletzten.","Die Sphäre ist schwerelos und gerade groß genug für die Kreatur oder den Gegenstand im Innern. Eine gefangene Kreatur kann sich als Aktion gegen die Wand der Sphäre lehnen und die Sphäre so bis zur halben Schrittbewegungsrate der Kreatur bewegen. Ebenso kann die Sphäre von anderen Kreaturen aufgehoben und bewegt werden.","Wird der Zauber Auflösung auf die Sphäre gewirkt, zerstört er sie, ohne etwas im Innern zu verletzten."]},
  {"id":"fabricate","name":"Verarbeitung","en":"Fabricate","level":4,"school":"transmutation","classes":["magier","magieschmied"],"time":"10 Minuten","action":"long","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"area":{"shape":"cube","size":3},"desc":["Du wandelst Rohmaterial in Erzeugnisse desselben Materials um. Du kannst beispielsweise eine Holzbrücke aus einem Stück Baum erschaffen, ein Seil aus etwas Hanf und Kleider aus Flachs oder Wolle.","Wähle Rohmaterial in Reichweite, das du sehen kannst. Du kannst einen maximal großen Gegenstand herstellen (der in einen Würfel mit drei Metern Kantenlänge oder in acht verbundene Würfel mit jeweils 1,5 Metern Kantenlänge passt), sofern du über genug Rohmaterial verfügst. Wenn du mit Metall, Stein oder einem anderen Mineral arbeitest, kann der hergestellte Gegenstand maximal groß sein und muss in einen einzelnen Würfel mit 1,5 Metern Kantenlänge passen. Die Qualität der mit dem Zauber erschaffenen Gegenstände hängt von der Qualität des Rohmaterials ab.","Kreaturen oder magische Gegenstände können mit diesem Zauber nicht erschaffen oder verwandelt werden. Du kannst zudem keine Gegenstände wie Schmuck, Waffen, Glas oder Rüstung erschaffen, die normalerweise ein hohes Maß an Handwerkskunst erfordern, es sei denn, du bist im Umgang mit Handwerkszeug geübt, das für die Herstellung dieser Gegenstände erforderlich ist."]},
  {"id":"banishment","name":"Verbannung","en":"Banishment","level":4,"school":"abjuration","classes":["kleriker","paladin","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"cha","desc":["Du versuchst, eine Kreatur in Reichweite, die du sehen kannst, auf eine andere Existenzebene zu verbannen. Das Ziel muss einen Charismarettungswurf bestehen, oder es wird verbannt.","Ist das Ziel auf der Existenzebene heimisch, auf der du dich befindest, verbannst du das Ziel auf eine harmlose Halbebene. Solange sich das Ziel dort befindet, ist es kampfunfähig. Das Ziel bleibt dort, bis der Zauber endet. Dann erscheint es wieder an der Stelle, von der es wegteleportiert wurde, oder an der nächstgelegenen freien Stelle.","Ist das Ziel auf einer anderen Existenzebene heimisch als der, auf der du dich befindest, verbannst du das Ziel mit einem leisen Knall und es kehrt auf seine Heimatebene zurück. Endet der Zauber, bevor eine Minute vergangen ist, erscheint das Ziel wieder an der Stelle, von der es wegteleportiert wurde, oder an der nächstgelegenen freien Stelle. Anderenfalls kehrt das Ziel nicht zurück."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 5. Grades oder höher nutzt, kannst du für jeden Grad über dem 4. eine zusätzliche Kreatur als Ziel wählen."]},
  {"id":"polymorph","name":"Verwandlung","en":"Polymorph","level":4,"school":"transmutation","classes":["barde","druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"save":"wis","desc":["Dieser Zauber verwandelt eine Kreatur in Reichweite, die du sehen kannst, in eine neue Gestalt Eine unwillige Kreatur muss einen Weisheitsrettungswurf ausführen, um den Effekt zu verhindern. Der Zauber wirkt nicht auf einen Gestaltwandler oder eine Kreatur mit 0 Trefferpunkten.","Die Verwandlung hält bis zum Ende der Wirkungsdauer an, oder bis die Trefferpunkte des Ziels auf 0 fallen oder es stirbt. Bei der neuen Gestalt kann es sich um ein beliebiges Tier handeln, dessen Herausforderungsgrad gleich oder niedriger als der des Ziels ist (wenn das Ziel keinen Herausforderungsgrad hat, verwende seine Stufe). Die Spielwerte des Ziels, inklusive mentaler Attributswerte, werden durch die Werte des gewählten Tiers ersetzt. Es behält seine Gesinnung und Persönlichkeit.","Das Ziel erhält die Trefferpunkte seiner neuen Gestalt. Nimmt es wieder seine ursprüngliche Gestalt an, besitzt es die gleichen Trefferpunkte wie vor der Verwandlung. Findet die Rückverwandlung statt, weil die Trefferpunkte des Ziels auf 0 sinken, wird überschüssiger Schaden auf seine ursprüngliche Gestalt übertragen. Sofern dieser überschüssige Schaden die ursprüngliche Gestalt der Kreatur nicht auf 0 Trefferpunkte reduziert, wird sie nicht bewusstlos.","Die Kreatur kann nur Aktionen durchführen, die in ihrer neuen Gestalt möglich sind. Sie kann nicht sprechen, Zauber wirken oder andere Aktionen ausführen, die Hände oder Sprache erfordern.","Die Ausrüstung des Ziels verschmilzt mit seiner neuen Gestalt Es kann die Ausrüstung nicht aktivieren, verwenden, führen oder anderweitig nutzen."]},
  {"id":"confusion","name":"Verwirrung","en":"Confusion","level":4,"school":"enchantment","classes":["barde","druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","area":{"shape":"sphere","size":3},"desc":["Dieser Zauber attackiert und verdreht den Verstand von Kreaturen, was zu Wahnvorstellungen und unkontrollierten Handlungen führt. Wenn du diesen Zauber wirkst, muss jede Kreatur in einer Sphäre mit einem Radius von drei Metern, die auf einen Punkt deiner Wahl in Reichweite zentriert ist, einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, ist die Kreatur von dem Zauber betroffen.","Ein betroffenes Ziel kann nicht reagieren und muss zu Beginn jedes seiner Züge mit einem W10 würfeln, um sein Verhalten in diesem Zug zu bestimmen.","Am Ende jedes seiner Züge kann ein betroffenes Ziel einen Weisheitsrettungswurf ausführen.","Bei einem Erfolg endet der Effekt für dieses Ziel."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 5. Grades oder höher nutzt, erhöht sich der Radius der Sphäre für jeden Grad über dem 4. um 1,5 Meter."]},
  {"id":"control-water","name":"Wasser kontrollieren","en":"Control Water","level":4,"school":"transmutation","classes":["kleriker","druide","magier"],"time":"1 Aktion","action":"action","range":"90 m","rangeKind":"dist","rangeM":90,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"save":"str","area":{"shape":"cube","size":30},"desc":["Bis der Zauber endet, kontrollierst du jedes offene Gewässer in einem Bereich deiner Wahl, der einem Würfel mit bis zu 30 Metern Kantenlänge entspricht. Wähle beim Wirken des Zaubers einen der folgenden Effekte aus. Als Aktion in deinem Zug kannst du denselben Effekt wiederholen oder einen anderen auswählen.","Fluss umlenken: Du bewirkst, dass sich fließendes Wasser im Bereich in eine Richtung deiner Wahl bewegt, selbst wenn es dafür über Hindernisse, Wände empor oder in andere unwahrscheinliche Richtungen strömen muss. Das Wasser im Bereich bewegt sich nach deinen Vorgaben. Sobald es jedoch den Bereich des Zaubers verlässt, fließt es wieder nach den Geländebedingungen. Das Wasser strömt in die Richtung deiner Wahl, bis der Zauber endet oder du einen anderen Effekt wählst.","Flut: Du lässt den Wasserspiegel aller stehenden Gewässer im Bereich um bis zu sechs Meter ansteigen. Ist ein Ufer Teil des Bereichs, tritt das Wasser auf das Land über.","Wählst du einen Bereich in einem größeren Gewässer, erschaffst du stattdessen eine sechs Meter hohe Welle, die sich von einer Seite des Bereichs zum anderen bewegt und sich dann bricht Alle maximal riesigen Fahrzeuge im Pfad der Welle werden mit ihr zur anderen Seite bewegt. Wird ein derartiges Fahrzeug von der Welle getroffen, besteht eine Chance von 25 Prozent, dass es kentert.","Der Wasserspiegel bleibt erhöht, bis der Zauber endet oder du einen anderen Effekt auswählst. Erzeugt dieser Effekt eine Welle, wiederholt sich diese zu Beginn deines nächsten Zugs, solange die Flut anhält.","Wasserstrudel: Dieser Effekt benötigt ein Gewässer mit einer Fläche von mindestens 15 Metern mal 15 Metern und einer Tiefe von 7,5 Metern. Du erschaffst einen Wasserstrudel in der Mitte des Bereichs. Dieser Wirbel ist an der Basis 1,5 Meter breit, an der Spitze bis zu 15 Meter breit und 7,5 Meter hoch. Alle Kreaturen und Objekte, die sich im Wasser im Abstand von bis zu 7,5 Metern um den Wirbel befinden, werden drei Meter in seine Richtung gezogen. Eine Kreatur kann vom Wirbel wegschwimmen, indem sie einen Stärkewurf (Athletik) gegen deinen Zauberrettungswurf-SG ausführt.","Wasser teilen: Du bewegst Wasser in dem Bereich auseinander und erschaffst einen Graben, der sich durch den Wirkungsbereich zieht. Das Wasser ragt auf beiden Seiten wie eine Mauer auf. Der Graben bleibt bestehen, bis der Zauber endet, oder du einen anderen Effekt auswählst. Anschließend füllt das Wasser im Verlauf der nächsten Runde langsam den Graben, bis der normale Wasserspiegel wiederhergestellt ist."]},
  {"id":"divination","name":"Weissagung","en":"Divination","level":4,"school":"divination","classes":["druide"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":true,"desc":["Mit deiner Magie und einer Opfergabe kannst du mit einer Gottheit oder ihren Dienern Kontakt aufhehmen. Du stellst eine einzige Frage über ein bestimmtes Ziel, ein Ereignis oder eine Aktivität, die in den nächsten sieben Tagen stattfindet. Der SL antwortet wahrheitsgemäß. Bei der Antwort kann es sich um einen kurzen Satz, einen kryptischen Reim oder ein Omen handeln.","Der Zauber berücksichtigt keinerlei Umstände, die das Ergebnis ändern könnten, wie das Wirken von zusätzlichen Zaubern oder der Verlust oder Gewinn eines Begleiters.","Wenn du den Zauber vor deiner nächsten langen Rast mindestens zweimal wirkst, steigt die Chance auf zufällige Omen mit jedem Wirken nach dem ersten um zusätzliche 25 Prozent. Der SL würfelt das Ergebnis geheim aus."]},
  {"id":"conjure-woodland-beings","name":"Wesen des Waldes beschwören","en":"Conjure Woodland Beings","level":4,"school":"conjuration","classes":["druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du beschwörst Feenwesen, die in freien Bereichen in Reichweite erscheinen, die du sehen kannst. Wähle eine der folgenden Optionen aus:","Eine beschworene Kreatur verschwindet, wenn der Zauber endet oder ihre Trefferpunkte auf 0 sinken.","Die beschworenen Kreaturen sind dir und deinen Gefährten freundlich gesinnt. Würfle die Initiative für die beschworenen Kreaturen als Gruppe aus, die über ihren eigenen Zug verfügt. Sie gehorchen deinen mündlichen Befehlen (erfordert keine Aktion), Wenn du ihnen keine Befehle erteilst, verteidigen sie sich gegen feindlich gesinnte Kreaturen, führen aber anderenfalls keine Aktionen aus.","Der SL hat die Werte der Kreaturen."],"higher":["Wirkst du diesen Zauber mit bestimmten Zauberplätzen höheren Grades, erscheinen mehr Kreaturen, wenn du eine der oben genannten Optionen auswählst: doppelt so viele mit einem Zauberplatz des 6. Grades und dreimal so viele mit einem Zauberplatz des 8. Grades."]},
  {"id":"compulsion","name":"Zwang","en":"Compulsion","level":4,"school":"enchantment","classes":["barde"],"time":"1 Aktion","action":"action","range":"9 m ","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Kreaturen deiner Wahl in Reichweite, die du sehen kannst und die dich hören können, müssen Weisheitsrettungswürfe ausführen. Ein Ziel besteht den Rettungswurf automatisch, wenn es nicht bezaubert werden kann. Scheitert der Wurf, ist das Ziel von diesem Zauber betroffen. Bis der Zauber endet, kannst du in jedem deiner Züge eine Bonusaktion verwenden, um eine Richtung zu bestimmen, die horizontal von dir verläuft. Jedes betroffene Ziel muss in seinem nächsten Zug so viel seiner Bewegungsrate wie möglich verwenden, um sich in diese Richtung zu bewegen. Es kann vor der Bewegung eine Aktion ausführen. Nachdem es sich auf diese Weise bewegt hat, kann es einen erneuten Weisheitsrettungswurf ausführen, um den Effekt zu beenden.","Ein Ziel kann nicht gezwungen werden, sich in eine offensichtlich tödliche Gefahr zu begeben, etwa ein Feuer oder eine Grube. Es provoziert jedoch Gelegenheitsangriffe, wenn es sich in die angegebene Richtung bewegt."]},
  {"id":"mislead","name":"Ablenkung","en":"Mislead","level":5,"school":"illusion","classes":["barde","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du wirst unsichtbar und gleichzeitig erscheint ein illusionärer Doppelgänger von dir an deinem Standort Der Doppelgänger bleibt für die Wirkungsdauer bestehen, die Unsichtbarkeit endet jedoch, wenn du angreifst oder einen Zauber wirkst.","Du kannst deine Aktion verwenden, um deinen illusionären Doppelgänger bis zu deiner doppelten Bewegungsrate zu bewegen und ihn gestikulieren, sprechen und auf eine beliebige Art handeln zu lassen.","Du kannst durch seine Augen sehen und durch seine Ohren hören, als befändest du dich am selben Ort. In jedem deiner Züge kannst du als Bonusaktion von den Sinnen des Doppelgängers zu deinen eigenen wechseln, oder wieder zurück. Während du seine Sinne benutzt, bist du in deiner eigenen Umgebung blind und taub."]},
  {"id":"contagion","name":"Ansteckung","en":"Contagion","level":5,"school":"necromancy","classes":["kleriker","druide"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"7 Tage","conc":false,"ritual":false,"attack":"melee","save":"con","desc":["Deine Berührung verursacht Krankheiten. Führe einen Nahkampf-Zauberangriff gegen eine Kreatur innerhalb deiner Reichweite aus. Bei einem Treffer verursachst du bei der Kreatur eine der unten beschriebenen Krankheiten deiner Wahl.","Am Ende jedes seiner Züge muss das Ziel einen Konstitutionsrettungswurf ausführen. Nach drei gescheiterten Rettungswürfen hält die Krankheit für die Wirkungsdauer an und die Kreatur führt keine Rettungswürfe mehr aus. Nach drei erfolgreichen Rettungswürfen erholt sich die Kreatur von der Krankheit und der Zauber endet.","Da dieser Zauber beim Ziel eine natürliche Krankheit verursacht, sind alle Effekte wirksam, die Krankheiten heilen oder anderweitig lindern.","Blendende Krankheit: Schmerz packt den Verstand der Kreatur und ihre Augen werden milchig weiß. Sie ist bei Attributs- und Rettungswürfen auf Weisheit im Nachteil und ist blind.","Fleischfäule: Das Fleisch der Kreatur verwest. Sie ist bei Charismawürfen im Nachteil und anfällig für sämtlichen Schaden.","Gedankenfeuer: Der Verstand der Kreatur wird fieberhaft Sie ist bei Attributs- und Rettungswürfen auf Intelligenz im Nachteil und verhält sich im Kampf, als ob sie unter dem Einfluss des Zaubers Verwirrung stünde.","Krampfanfall: Die Kreatur wird von Krampfanfällen überwältigt. Sie ist bei Attributs-, Rettungs- und Angriffswürfen auf Geschicklichkeit im Nachteil.","Schleimiges Verderben: Die Kreatur beginnt unkontrolliert zu bluten. Sie ist bei Attributs- und Rettungswürfen auf Konstitution im Nachteil. Außerdem wird die Kreatur, wenn sie Schaden erleidet, bis zum Ende ihres nächsten Zugs betäubt.","Schmutzfieber: Ein rasendes Fieber erfasst den Körper der Kreatur. Sie ist bei Attributs-, Rettungs- und Angriffswürfen auf Stärke im Nachteil."]},
  {"id":"arcane-hand","name":"Arkane Hand","en":"Arcane Hand","level":5,"school":"evocation","classes":["magier","magieschmied"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"damage":{"type":"force","slots":{"5":"4d8","6":"6d8","7":"8d8","8":"10d8","9":"12d8"}},"desc":["Du erschaffst eine große Hand aus schimmernder, durchsichtiger Energie in einem freien Bereich in Reichweite, den du sehen kannst. Die Hand bleibt für die Wirkungsdauer des Zaubers bestehen. Sie bewegt sich auf deinen Befehl und ahmt die Bewegungen deiner eigenen Hand nach.","Die Hand ist ein Gegenstand mit einer RK von 20. Ihre Trefferpunkte entsprechen deinem Trefferpunktemaximum. Wenn ihre Trefferpunkte auf 0 sinken, endet der Zauber. Sie besitzt eine Stärke von 26 (+8) und eine Geschicklichkeit von 10 (+0), Der Bereich der Hand gilt nicht als besetzt.","Nach dem Wirken des Zaubers und als Bonusaktion in deinen darauffolgenden Zügen kannst du die Hand bis zu 18 Meter weit bewegen und einen der folgenden Effekte auslösen.","Blockierende Hand: Die Hand platziert sich zwischen dir und einer Kreatur deiner Wahl, bis du der Hand einen anderen Befehl erteilst. Die Hand bewegt sich, um diese Position beizubehalten, und gewährt dir Teildeckung gegen das Ziel. Das Ziel kann sich nicht durch den Bereich der Hand bewegen, wenn sein Stärkewert kleiner oder gleich dem Stärkewert der Hand ist. Ist sein Stärkewert größer als der Stärkewert der Hand, kann sich das Ziel durch den Bereich der Hand auf dich zubewegen. Der Bereich gilt jedoch für das Ziel als schwieriges Gelände.","Geballte Faust: Die Hand schlägt eine Kreatur oder einen Gegenstand im Abstand von bis zu 1,5 Metern von ihr. Führe einen Nahkampf-Zauberangriff für die Hand mit deinen Spielwerten aus. Bei einem Treffer erleidet das Ziel 4W8 Energieschaden.","Greifende Hand: Die Hand versucht, eine höchstens riesige Kreatur im Abstand von bis zu 1,5 Metern von ihr zu packen. Verwende den Stärkewert der Hand für den Ringenwurf. Ist das Ziel höchstens mittelgroß, bist du beim Wurf im Vorteil. Während die Hand das Ziel gepackt hat, kannst du eine Bonusaktion verwenden, damit die Hand es zerquetscht. Dabei erleidet das Ziel Wuchtschaden in Höhe von 2W6 + deinem Zauberwirken-Attributsmodifikator.","Kraftvolle Hand: Die Hand versucht, eine Kreatinin 1,5 Metern Entfernung in eine Richtung deiner Wahl zu schieben. Führe einen Stärkewurf für die Hand aus, der mit dem Stärkewurf (Athletik) des Ziels verglichen wird. Ist das Ziel höchstens mittelgroß, bist du beim Wurf im Vorteil. Bei einem Erfolg schiebt die Hand das Ziel bis zu 1,5 Meter + (1,5 Meter mal deinem Zauberwirken-Attributsmodifikator). Die Hand bewegt sich mit dem Ziel, um im Abstand von bis zu 1,5 Metern von ihm zu bleiben."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, erhöht sich für jeden Grad über dem 5. der Schaden der geballten Faust um 2W8 und der Schaden der greifenden Hand um 2W6."]},
  {"id":"seeming","name":"Äußerlichkeiten","en":"Seeming","level":5,"school":"illusion","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"8 Stunden","conc":false,"ritual":false,"save":"cha","desc":["Mit diesem Zauber kannst du das Aussehen einer beliebigen Anzahl an Kreaturen in Reichweite verändern, die du sehen kannst. Jedes gewählte Ziel erhält ein neues, illusionäres Erscheinungsbild. Ein unwilliges Ziel kann einen Charismarettungswurf ablegen. Bei einem Erfolg wird es nicht von diesem Effekt betroffen.","Der Zauber verschleiert die physische Erscheinung sowie Kleidung, Rüstung, Waffen und Ausrüstung. Du kannst jede Kreatur 30 Zentimeter größer oder kleiner sowie dicker oder dünner erscheinen lassen. Den Körpertyp des Ziels kannst du nicht verändern. Du musst also eine Form mit der gleichen Grundanordnung von Gliedmaßen auswählen. Abgesehen davon sind Form und Ausmaß der Illusion dir überlassen. Der Zauber bleibt für die Wirkungsdauer bestehen oder bis du ihn als Aktion beendest.","Einer genauen körperlichen Untersuchung halten die Veränderungen dieser Illusion nicht stand. Nutzt du diesen Zauber beispielsweise, um einer Kreatur einen Hut aufzusetzen, durchdringen Gegenstände diesen einfach. Will jemand den Hut berühren, fühlt er dort nichts außer den Haaren und den Kopf der Kreatur. Lässt der Zauber die Kreatur dünner erscheinen, würde eine nach ihr greifende Hand schon mit ihr kollidieren, wenn sie noch in der Luft zu sein scheint.","Eine Kreatur kann als Aktion ein Ziel untersuchen und einen Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG ausführen. Bei einem Erfolg weiß es, dass das Ziel verkleidet wurde."]},
  {"id":"scrying","name":"Ausspähung","en":"Scrying","level":5,"school":"divination","classes":["barde","kleriker","druide","hexenmeister","magier"],"time":"10 Minuten","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"save":"wis","desc":["Du kannst eine bestimmte Kreatur deiner Wahl sehen und hören, die sich auf derselben Existenzebene wie du befindet Das Ziel muss einen Weisheitsrettungswurf ausführen, der dadurch modifiziert wird, wie gut du das Ziel kennst und ob du einen Gegenstand hast, der dich mit ihm verbindet. Weiß das Ziel, dass du diesen Zauber wirkst, und will es beobachtet werden, kann es den Rettungswurf freiwillig scheitern lassen.","Bei einem erfolgreichen Rettungswurf ist das Ziel nicht betroffen und du kannst diesen Zauber erst nach 24 Stunden erneut auf das Ziel wirken.","Scheitert der Wurf, erschafft der Zauber einen unsichtbaren Sensor im Abstand von bis zu drei Metern vom Ziel. Du kannst durch den Sensor sehen und hören, als ob du dich dort befindest. Der Sensor bewegt sich mit dem Ziel und bleibt für die Wirkungsdauer im Abstand von bis zu drei Metern von ihm. Eine Kreatur, die unsichtbare Gegenstände sehen kann, sieht den Sensor als leuchtende, etwa faustgroße Kugel.","Anstelle einer Kreatur kannst du einen Ort, den du schon einmal gesehen hast, als Ziel des Zaubers wählen. In diesem Fall erscheint der Sensor an diesem Ort und bewegt sich nicht."]},
  {"id":"planar-binding","name":"Bindung der Ebenen","en":"Planar Binding","level":5,"school":"abjuration","classes":["barde","kleriker","druide","magier"],"time":"1 Stunde","action":"long","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":false,"save":"cha","desc":["Mit diesem Zauber versuchst du, ein celestisches Wesen, einen Elementar, ein Feenwesen oder einen Unhold in deinen Dienst zu verpflichten. Die Kreatur muss sich für die gesamte Wirkungsdauer in Reichweite befinden. (Normalerweise wird die Kreatur zuerst in einen umgekehrten Schutzkreis beschworen, wo sie gefangen bleibt, während du den Zauber wirkst.) Nach Wirken des Zaubers muss das Ziel einen Charismarettungswurf ausführen. Scheitert der Wurf, muss es dir für die Wirkungsdauer dienen. Wurde die Kreatur durch einen anderen Zauber beschworen oder erschaffen, verlängert sich dessen Wirkungsdauer auf die Wirkungsdauer von Bindung der Ebenen.","Eine verpflichtete Kreatur muss deine Befehle nach Kräften befolgen. Du kannst der Kreatur befehlen, dich auf ein Abenteuer zu begleiten, einen Ort zu bewachen oder eine Botschaft zu übermitteln.","Die Kreatur befolgt deine Anweisungen wortwörtlich. Ist sie dir jedoch feindlich gesinnt, versucht sie, deine Worte zu verdrehen, um ihre eigenen Ziele zu verfolgen. Führt die Kreatur deine Anweisungen vollständig aus, bevor der Zauber endet, kehrt sie zu dir zurück und erstattet dir Bericht, sofern du dich auf derselben Existenzebene befindest. Anderenfalls kehrt sie an den Ort zurück, an dem du sie verpflichtet hast, und verbleibt dort, bis der Zauber endet."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz eines höheren Grades verwendest, verlängert sich die Wirkungsdauer: zehn Tage bei einem Zauberplatz des 6. Grades, 30 Tage bei einem des 7. Grades, 180 Tage bei einem des 8. Grades und ein Jahr und einen Tag bei einem des 9. Grades."]},
  {"id":"commune-with-nature","name":"Einswerden mit der Natur","en":"Commune With Nature","level":5,"school":"divination","classes":["druide","waldlaeufer"],"time":"1 Minute","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":true,"desc":["Du wirst kurzzeitig eins mit der Natur und erlangst Wissen über deine Umgebung. Im Freien gewährt dir der Zauber Wissen über das Land im Abstand von bis zu 4,8 Kilometern um dich herum. In Höhlen und anderen natürlichen unterirdischen Umgebungen beträgt der Radius 90 Meter. Der Zauber funktioniert nicht in Gebieten, in denen die Natur durch Bauten ersetzt wurde, beispielsweise in Gewölben und Städten.","Du erhältst sofort Wissen über bis zu drei Fakten deiner Wahl zu einem der folgenden Themen der Umgebung:","Beispielsweise könntest du herausfinden, wo sich in dieser Gegend ein mächtiger Untoter aufhält, sich Trinkwasserquellen befinden und nahe Städte liegen."]},
  {"id":"conjure-elemental","name":"Elementar beschwören","en":"Conjure Elemental","level":5,"school":"conjuration","classes":["druide","magier"],"time":"1 Minute","action":"long","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"area":{"shape":"cube","size":3},"desc":["Du rufst einen Elementardiener herbei. Wähle einen Bereich mit Erde, Feuer, Luft oder Wasser in Reichweite, der einen Würfel mit drei Metern Kantenlänge füllt. Ein Elementar mit Herausforderungsgrad 5 oder niedriger, der dem gewählten Bereich entspricht, erscheint an einer freien Stelle im Umkreis von drei Metern um diesen Bereich. Ein Feuerelementar tritt beispielsweise aus einem Lagerfeuer hervor und ein Erdelementar erhebt sich aus dem Boden.","Der Elementar verschwindet, wenn der Zauber endet oder seine Trefferpunkte auf 0 sinken.","Der Elementar ist dir und deinen Gefährten für die Wirkungsdauer freundlich gesinnt. Würfle die Initiative für den Elementar aus, der über seinen eigenen Zug verfügt. Er gehorcht deinen mündlichen Befehlen (erfordert keine Aktion), Wenn du dem Elementar keine Befehle erteilst, verteidigt er sich gegen feindlich gesinnte Kreaturen, führt aber anderenfalls keine Aktionen aus.","Wenn deine Konzentration unterbrochen wird, verschwindet der Elementar nicht. Stattdessen verlierst du die Kontrolle über den Elementar und er wird dir und deinen Gefährten gegenüber feindlich gesinnt und greift möglicherweise an. Ein unkontrollierter Elementar kann nicht von dir fortgeschickt werden und verschwindet eine Stunde nach seiner Beschwörung.","Der SL hat die Werte des Elementars."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, erhöht sich der Herausforderungsgrad für jeden Grad über dem 5. um 1."]},
  {"id":"wall-of-force","name":"Energiewand","en":"Wall of Force","level":5,"school":"evocation","classes":["magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Eine unsichtbare Energiewand erscheint an einem Punkt deiner Wahl in Reichweite. Sie erscheint in einer Ausrichtung deiner Wahl, als senkrechte, waagerechte oder abgewinkelte Barriere. Sie kann frei schweben oder auf einer festen Oberfläche stehen. Du kannst sie auch zu einer halbrunden Kuppel oder einer Sphäre mit einem Radius von bis zu drei Metern formen, oder du kannst eine flache Oberfläche aus zehn Platten erschaffen, die jeweils neun Quadratmeter groß sind, jede Platte muss an eine andere angrenzen. In jeder Form ist die Wand 6,25 Millimeter dick. Sie bleibt für die","Wirkungsdauer bestehen. Erschaffst du die Wand so, dass sie den Bereich einer Kreatur durchdringt, wird die Kreatur auf eine Seite der Wand gestoßen (deine Wahl),","Nichts kann die Wand physisch durchdringen. Sie ist gegen alle Schadensarten immun und kann nicht durch Magie bannen aufgehoben werden. Der Zauber Auflösung zerstört die Wand jedoch sofort. Die Wand erstreckt sich auch in die Ätherebene und blockiert damit Reisen über diese Ebene."]},
  {"id":"modify-memory","name":"Erinnerung verändern","en":"Modify Memory","level":5,"school":"enchantment","classes":["barde","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Du versuchst, die Erinnerungen einer anderen Kreatur umzuformen. Eine Kreatur, die du sehen kannst, muss einen Weisheitsrettungswurf ausführen. Kämpfst du gegen die Kreatur, ist sie bei ihrem Rettungswurf im Vorteil. Scheitert der Wurf, ist das Ziel für die Wirkungsdauer von dir bezaubert. Das bezaubert Ziel ist kampfunfähig und sich seiner Umgebung nicht bewusst, es kann dich jedoch hören. Erleidet es Schaden oder wird es von einem anderen Zauber betroffen, endet dieser Zauber und die Erinnerungen des Ziels werden nicht verändert.","Während diese Bezauberung anhält, kannst du die Erinnerungen des Ziels an ein Ereignis der letzten 24 Stunden verändern, das maximal zehn Minuten andauerte. Du kannst dauerhaft sämtliche Erinnerungen an das Ereignis löschen, dem Ziel ermöglichen, sich mit absoluter Klarheit und Detailtreue an das Ereignis zu erinnern, seine Erinnerungen an die Details des Ereignisses verändern oder eine andere Erinnerung erschaffen.","Du musst mit dem Ziel sprechen und beschreiben, wie seine Erinnerungen beeinflusst werden. Es muss deine Sprache sprechen, damit die veränderten Erinnerungen Fuß fassen können. Sein Verstand füllt etwaige Lücken in den von dir beschriebenen Details. Endet der Zauber, bevor du die veränderten Erinnerungen beschrieben hast, werden die Erinnerungen der Kreatur nicht modifiziert. Anderenfalls setzen sich die neuen Erinnerungen mit dem Ende des Zaubers fest.","Veränderte Erinnerungen beeinflussen nicht unbedingt, wie sich eine Kreatur verhält -insbesondere, wenn die Erinnerungen den natürlichen Neigungen, der Gesinnung oder dem Glauben der Kreatur widersprechen. Eine unlogische veränderte Erinnerung, etwa daran, wie gerne die Kreatur in Säure gebadet hat, wird als Alptraum abgetan. Der SL kann eine veränderte Erinnerung als zu unsinnig erklären, um die Kreatur signifikant zu beeinflussen.","Die Zauber Fluch brechen oder Vollständige Genesung stellen die wahren Erinnerungen der Kreatur wieder her."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, kannst du die Erinnerungen des Ziels an ein Ereignis verändern, das bis zu sieben Tage (6. Grad), 30 Tage (7. Grad) oder ein Jahr (8. Grad) zurückliegt oder an einem beliebigen Zeitpunkt in der Vergangenheit stattgefunden hat (9. Grad)."]},
  {"id":"creation","name":"Erschaffung","en":"Creation","level":5,"school":"illusion","classes":["zauberer","magier","magieschmied"],"time":"1 Minute","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Besonders","conc":false,"ritual":false,"area":{"shape":"cube","size":1.5},"desc":["Du ziehst Fäden aus Schattenmaterial aus dem Schattenfell und erschaffst ein unbelebtes Objekt aus pflanzlichem Material in Reichweite: Textilien, Seil, Holz oder dergleichen. Du kannst mit dem Zauber auch Mineralien erschaffen, etwa Stein, Kristall oder Metall. Der erschaffene Gegenstand darf nicht größer als ein Würfel mit 1,5 Metern Kantenlänge sein und muss aus einem Material bestehen sowie eine Form besitzen, die du bereits gesehen hast.","Die Wirkungsdauer hängt vom Material des Gegenstands ab. Besteht der Gegenstand aus mehreren Materialien, verwende die kürzeste Wirkungsdauer.","Wird mit diesem Zauber erschaffenes Material als Materialkomponente für einen anderen Zauber verwendet, schlägt dieser Zauber fehl."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, erhöht sich die Kantenlänge des Würfels für jeden Grad über dem 5. um 1,5 Meter."]},
  {"id":"awaken","name":"Erwecken","en":"Awaken","level":5,"school":"transmutation","classes":["barde","druide"],"time":"8 Stunden","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du verbringst die Wirkungszeit damit, magische Pfade in einen kostbaren Edelstein zu zeichnen, und berührst anschließend ein höchstens riesiges Tier oder eine Pflanze. Das Ziel muss entweder über keinen Intelligenzwert oder über eine Intelligenz von maximal 3 verfügen. Das Ziel erhält eine Intelligenz von 10. Das Ziel erhält zudem die Fähigkeit, eine dir bekannte Sprache zu sprechen. Wenn es sich beim Ziel um eine Pflanze handelt, kann sie ihre Wurzeln, Ranken, Schlingpflanzen und ähnliches bewegen und erhält Sinne, die denen eines Menschen ähneln. Dein SL wählt Spielwerte aus, die für die erweckte Pflanze geeignet sind, etwa die Spielwerte für den erwachten Busch oder den erwachten Baum.","Das erweckte Tier oder die Pflanze ist 30 Tage lang von dir bezaubert. Der Zauber endet, wenn du oder deine Gefährten ihm oder ihr Schaden zufügen. Wenn die Bezauberung endet, entscheidet die erweckte Kreatur anhand dessen, wie du sie während der Bezauberung behandelt hast, ob sie dir gegenüber freundlich gesinnt bleibt."]},
  {"id":"flame-strike","name":"Flammenschlag","en":"Flame Strike","level":5,"school":"evocation","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"fire","slots":{"5":"4d6","6":"5d6","7":"6d6","8":"7d6","9":"8d6"}},"area":{"shape":"cylinder","size":12},"desc":["Eine vertikale Säule aus göttlichem Feuer fährt an einem Ort deiner Wahl vom Himmel herab. Jede Kreatur in einem zwölf Meter hohen Zylinder mit einem Radius von drei Metern, der um einen Punkt in Reichweite zentriert ist, muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet eine Kreatur 4W6 Feuerschaden und 4W6 gleißenden Schaden, anderenfalls die Hälfte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, steigt der Feuerschaden oder der gleißende Schaden (deine Wahl) für jeden Grad über dem 5. um 1W6."]},
  {"id":"geas","name":"Geas","en":"Geas","level":5,"school":"enchantment","classes":["barde","kleriker","druide","paladin","magier"],"time":"1 Minute","action":"long","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V","duration":"30 Tage","conc":false,"ritual":false,"save":"wis","damage":{"type":"psychic","slots":{"5":"5d10"}},"desc":["Du platzierst einen magischen Befehl auf einer Kreatur in Reichweite, die du sehen kannst. Damit zwingst du sie, eine Aufgabe zu erfüllen oder eine bestimmte Handlung deiner Wahl zu vermeiden. Wenn die Kreatur dich verstehen kann, muss sie einen Weisheitsrettungswurfbestehen, oder sie wird für die Wirkungsdauer von dir bezaubert. Während die Kreatur von dir bezaubert ist, erleidet sie jedes Mal 5W10 psychischen Schaden, wenn sie direkt gegen deine Anweisungen handelt. Dies kann nur einmal pro Tag auftreten. Eine Kreatur, die dich nicht verstehen kann, ist von dem Zauber nicht betroffen.","Du kannst einen beliebigen Befehl erteilen, außer Handlungen, die zum sicheren Tod führen würden. Erteilst du einen selbstmörderischen Befehl, endet der Zauber.","Du kannst den Zauber als Aktion vorzeitig beenden. Die Zauber Fluch brechen, Vollständige Genesung oder Wunsch beenden den Zauber ebenfalls."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. oder 8. Grades nutzt, beträgt die Wirkungsdauer ein Jahr. Wirkst du diesen Zauber, indem du einen Zauberplatz des 9. Grades nutzt, hält er an, bis einer der zuvor genannten Zauber ihn bannt."]},
  {"id":"animate-objects","name":"Gegenstände beleben","en":"Animate Objects","level":5,"school":"transmutation","classes":["barde","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Objekte erwachen auf deinen Befehl hin zum Leben. Wähle bis zu zehn nichtmagische Gegenstände in Reichweite, die nicht getragen oder gehalten werden. Mittelgroße Ziele zählen als zwei Gegenstände, große Ziele als vier und riesige Ziele als acht. Du kannst keine Gegenstände beleben, die größer als riesig sind. Jedes Ziel wird belebt und zu einer Kreatur unter deiner Kontrolle. Dies hält an, bis der Zauber endet oder die Treffpunkte des Ziels auf 0 sinken.","Als Bonusaktion kannst du jede Kreatur, die du mit diesem Zauber belebt hast und die sich im Abstand von bis zu 150 Metern von dir befindet, mental befehligen. Wenn du mehrere Kreaturen kontrollierst, kannst du gleichzeitig eine oder alle befehligen, wobei jeder derselbe Befehl erteilt wird. Du entscheidest über die Aktion der Kreatur und ihre Bewegung in ihrem nächsten Zug. Alternativ kannst du einen allgemeinen Befehl erteilen, etwa das Bewachen einer bestimmten Kammer oder eines Korridors. Erteilst du keine Befehle, verteidigt sich die Kreatur lediglich gegen feindlich gesinnte Kreaturen. Sobald die Kreatur einen Befehl erhalten hat, führt sie ihn aus, bis die Aufgabe abgeschlossen ist","Ein animierter Gegenstand ist ein Konstrukt, dessen RK, Trefferpunkte, Angriffe, Stärke und Geschicklichkeit von seiner Größe festgelegt werden. Seine Konstitution beträgt 10, seine Intelligenz und Weisheit 3 und sein Charisma 1. Es verfügt über eine Bewegungsrate von neun Metern. Wenn der Gegenstand keine Beine oder ähnliches zur Fortbewegung besitzt, verfügt er stattdessen über eine Flugbewegungsrate von neun Metern und kann schweben. Ist der Gegenstand an einer Oberfläche oder einem größeren Gegenstand befestigt, etwa mit einer Kette an einer Wand, beträgt seine Bewegungsrate 0. Der belebte Gegenstand besitzt Blindsicht mit einem Radius von neun Metern. Über diese Entfernung hinaus ist er blind. Sinken die Trefferpunkte des animierten Gegenstands auf 0, nimmt er wieder seine unbelebte Form an. Verbleibender Schaden wird auf diese Form übertragen.","Wenn du einem Gegenstand befiehlst anzugreifen, führt er einen einzelnen Nahkampfangriff gegen eine Kreatur im Abstand von bis zu 1,5 Metern von ihm aus. Dabei handelt es sich um einen Hiebangriff, dessen Angriffsbonus und Wuchtschaden von der Größe des Gegenstands abhängen. Der SL kann bestimmen, dass ein bestimmter Gegenstand aufgrund seiner Form Hieb- oder Stichschaden verursacht."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, kannst du für jeden Grad über dem 5. zwei zusätzliche Gegenstände beleben."]},
  {"id":"dispel-evil-and-good","name":"Gutes und Böses bannen","en":"Dispel Evil and Good","level":5,"school":"abjuration","classes":["kleriker","paladin"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"cha","desc":["Schimmernde Energie umgibt dich und beschützt dich vor Feenwesen, Untoten und Kreaturen, die nicht von der materiellen Ebene stammen. Während der Wirkungsdauer sind celestische Wesen, Elementare, Feenwesen, Unholde und Untote bei Angriffswürfen gegen dich im Nachteil.","Du kannst den Zauber vorzeitig beenden, indem du einen der folgenden besonderen Effekte verwendest:","Vertreiben: Als Aktion führst du einen Nahkampf-Zauberangriff gegen ein celestisches Wesen, einen Elementar, ein Feenwesen, einen Unhold oder einen Untoten innerhalb deiner Reichweite aus. Bei einem Treffer versuchst du, die Kreatur wieder auf ihre Heimatebene zu vertreiben. Das Ziel muss einen Charismarettungswurf bestehen, oder es wird auf seine Heimatebene verbannt (falls es sich nicht bereits dort befindet). Wenn sie sich nicht auf ihrer Heimatebene befinden, werden Untote ins Schattenfell und Feenwesen ins Feywild verbannt.","Verzauberung brechen: Als Aktion berührst du eine Kreatur in Reichweite, die von einem celestischen Wesen, einem Elementar, einem Feenwesen, einem Unhold oder einem Untoten bezaubert, verängstigt oder besessen wurde. Die von dir berührte Kreatur ist nicht länger von derartigen Kreaturen bezaubert, verängstigt oder besessen."]},
  {"id":"commune","name":"Heiliges Gespräch","en":"Commune","level":5,"school":"divination","classes":["kleriker"],"time":"1 Minute","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"1 Minute","conc":false,"ritual":true,"desc":["Du nimmst mit deiner Gottheit oder einem göttlichen Gesandten Kontakt auf und stellst bis zu drei Fragen, die mit Ja oder Nein beantwortet werden können. Du musst deine Fragen stellen, bevor der Zauber endet. Du erhältst eine korrekte Antwort auf jede Frage.","Göttliche Wesen sind nicht unbedingt allwissend. Bezieht sich die Frage auf Informationen, die das Wissen der Gottheit übersteigen, könntest du 'unklar' als Antwort erhalten. Falls eine Antwort mit nur einem Wort irreführend sein oder nicht dem Interesse der Gottheit entsprechen könnte, kann der SL stattdessen einen kurzen Satz als Antwort geben.","Wenn du den Zauber vor deiner nächsten langen Rast mindestens zweimal wirkst, besteht eine","Chance von 25 Prozent für jedes Wirken nach dem ersten, dass du keine Antwort bekommst. Der SL würfelt das Ergebnis geheim aus."]},
  {"id":"tree-stride","name":"Hölzerner Weg","en":"Tree Stride","level":5,"school":"conjuration","classes":["druide","waldlaeufer"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Du erhältst die Fähigkeit, einen Baum zu betreten und aus einem anderen Baum derselben Art im Abstand von bis zu 150 Metern wieder herauszusteigen. Beide Bäume müssen lebendig und mindestens so groß wie du sein. Es kostet 1,5 Meter deiner Bewegungsrate, den Baum zu betreten. Du erfährst sofort die Position aller anderen Bäume derselben Art im Abstand von bis zu 150 Metern. Als Teil der Bewegung, den Baum zu betreten, kannst du entweder in einen dieser Bäume wechseln und oder aus dem Baum heraustreten, in dem du dich befindest. Du erscheinst an einem Ort deiner Wahl im Abstand von bis zu 1,5 Metern vom Zielbaum, was dich weitere 1,5 Meter deiner Bewegungsrate kostet. Hast du keine Bewegungsrate übrig, erscheinst du im Abstand von bis zu 1,5 Metern von dem Baum, den du betreten hast","Während der Wirkungsdauer kannst du diese Transportmöglichkeit einmal pro Runde verwenden. Du musst jeden Zug außerhalb eines Baums beenden."]},
  {"id":"insect-plague","name":"Insektenplage","en":"Insect Plague","level":5,"school":"conjuration","classes":["kleriker","druide","zauberer"],"time":"1 Aktion","action":"action","range":"90 m","rangeKind":"dist","rangeM":90,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"save":"con","damage":{"type":"piercing","slots":{"5":"4d10"}},"area":{"shape":"sphere","size":6},"desc":["Schwärmende, beißende Heuschrecken erscheinen in einer Sphäre mit einem Radius von sechs Metern, die um einen Punkt deiner Wahl in Reichweite zentriert ist. Die Sphäre breitet sich um Ecken aus.","Die Sphäre bleibt für die Wirkungsdauer bestehen und ihr Bereich ist leicht verschleiert. Der Bereich der Sphäre ist schwieriges Gelände.","Wenn der Bereich erscheint, muss jede Kreatur darin einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 4W10 Stichschaden, anderenfalls die Hälfte. Wenn eine Kreatur den Bereich des Zaubers in einem Zug erstmals betritt oder ihren Zug darin beendet, muss sie diesen Rettungswurf ebenfalls ausführen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 5. um 1W10."]},
  {"id":"cone-of-cold","name":"Kältekegel","en":"Cone of Cold","level":5,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Kegel von 18 m)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"cold","slots":{"5":"8d8"}},"area":{"shape":"cone","size":18},"desc":["Eiskalte Luft strömt aus deinen Händen. Jede Kreatur in einem Kegel von 18 Metern muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 8W8 Kälteschaden, anderenfalls die Hälfte.","Wird eine Kreatur durch diesen Zauber getötet, wird sie zu einer gefrorenen Statue, bis sie auftaut."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 5. um 1W8."]},
  {"id":"contact-other-plane","name":"Kontakt zu anderen Ebenen","en":"Contact Other Plane","level":5,"school":"divination","classes":["hexenmeister","magier"],"time":"1 Minute","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V","duration":"1 Minute","conc":false,"ritual":true,"save":"int","damage":{"type":"psychic","slots":{"5":"6d6"}},"desc":["Du trittst mental mit einem Halbgott, dem Geist eines lang verstorbenen Weisen oder einem anderen geheimnisvollen Wesen von einer anderen Ebene in Kontakt. Dieser Kontakt kann deinen Verstand überfordern oder sogar brechen. Führe beim Wirken dieses Zaubers einen SG-15-Intelligenzrettungswurf aus. Scheitert der Wurf, erleidest du 6W6 psychischen Schaden und bist wahnsinnig, bis du eine lange Rast abschließt. Während du wahnsinnig bist, kannst du keine Aktionen ausführen, verstehst nicht, was andere Kreaturen sagen, kannst nicht lesen und dich nicht verständlich ausdrücken. Der Zauber Vollständige Genesung beendet diesen Effekt.","Ist der Rettungswurf erfolgreich, kannst du dem Wesen bis zu fünf Fragen stellen. Du musst deine Fragen stellen, bevor der Zauber endet. Der SL beantwortet jede Frage mit einem einzelnen Wort wie 'ja', 'nein', 'vielleicht', 'niemals', 'irrelevant' oder 'unklar' (wenn das Wesen die Antwort nicht kennt). Falls eine Antwort mit nur einem Wort irreführend wäre, kann der SL stattdessen einen kurzen Satz als Antwort geben."]},
  {"id":"teleportation-circle","name":"Kreis der Teleportation","en":"Teleportation Circle","level":5,"school":"conjuration","classes":["barde","zauberer","magier"],"time":"1 Minute","action":"long","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, M","duration":"1 Runde","conc":false,"ritual":false,"area":{"shape":"sphere","size":3},"desc":["Während du den Zauber wirkst, zeichnest du einen Kreis mit einem Durchmesser von drei Metern auf den Boden. In den Kreis arbeitest du Siegel ein, die deine aktuelle Position mit einem dauerhaften Kreis der Teleportation deiner Wahl verbinden, dessen Siegelsequenz du kennst und der sich auf derselben Existenzebene befindet. Im Kreis öffnet sich ein schimmerndes Portal und bleibt bis zum Ende deines nächsten Zugs geöffnet. Jede Kreatur, die durch das Portal tritt, erscheint sofort im Abstand von bis zu 1,5 Metern um den Zielkreis oder im nächsten freien Bereich, falls kein freier Platz vorhanden ist.","Viele wichtige Tempel, Gilden oder andere wichtige Orte verfügen über dauerhafte Kreise der Teleportation. Jeder dieser Kreise besitzt eine einzigartige Siegelsequenz, eine Reihe magischer Runen, die in einem bestimmten Muster angeordnet sind. Wenn du diesen Zauber erlernst, erhältst du die Siegelsequenzen zweier Zielorte auf der materiellen Ebene nach Wahl des SL. Im Laufe deiner Abenteuer kannst du weitere Siegelsequenzen lernen. Du prägst dir eine neue Siegelsequenz ein, wenn du sie eine Minute lang studierst.","Wenn du diesen Zauber ein Jahr lang jeden Tag an demselben Ort wirkst, kannst du einen dauerhaften Kreis der Teleportation erschaffen. Du musst den Kreis nicht zur Teleportation nutzen, wenn du den Zauber auf diese Art wirkst."]},
  {"id":"mass-cure-wounds","name":"Massen-Wunden heilen","en":"Mass Cure Wounds","level":5,"school":"evocation","classes":["barde","kleriker","druide"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"heal":{"slots":{"5":"3d8 + MOD","6":"4d8 + MOD","7":"5d8 + MOD","8":"6d8 + MOD","9":"7d8 + MOD"}},"area":{"shape":"sphere","size":9},"desc":["Eine Woge aus heilender Energie geht von einem Punkt deiner Wahl in Reichweite aus. Wähle bis zu sechs Kreaturen innerhalb einer Sphäre mit einem Radius von neun Metern aus, die um den Zielort zentriert ist. Jedes Ziel gewinnt Trefferpunkte in Höhe von 3W8 + deinem Zauberwirken-Attributsmodifikator zurück. Dieser Zauber wirkt nicht auf Untote oder Konstrukte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, steigt die Heilung für jeden Grad über dem 5. um 1W8."]},
  {"id":"hold-monster","name":"Monster festhalten","en":"Hold Monster","level":5,"school":"enchantment","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Wähle eine Kreatur in Reichweite, die du sehen kannst. Das Ziel muss einen Weisheitsrettungswurf ausführen oder es wird für die Wirkungsdauer gelähmt. Dieser Zauber wirkt nicht auf Untote. Am Ende jedes seiner Züge kann das Ziel einen weiteren Weisheitsrettungswurf ausführen. Bei einem Erfolg endet die Wirkung des Zaubers auf das Ziel."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, kannst du für jeden Grad über dem 5. eine zusätzliche Kreatur als Ziel wählen. Die Kreaturen müssen sich im Abstand von bis zu neun Metern voneinander befinden, wenn du sie als Ziel wählst."]},
  {"id":"dominate-person","name":"Person beherrschen","en":"Dominate Person","level":5,"school":"enchantment","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Du versuchst, eine humanoide Kreatur in Reichweite zu betören, die du sehen kannst. Sie muss einen Weisheitsrettungswurfbestehen oder sie wird für die Wirkungsdauer von dir bezaubert. Wenn du oder deine Verbündeten gegen die Kreatur kämpfen, ist sie beim Rettungswurf im Vorteil.","Während das Ziel bezaubert ist und ihr euch auf derselben Existenzebene aufhaltet, verfügst du über eine telepathische Verbindung zu ihm. Diese kannst du verwenden, um der Kreatur Befehle zu erteilen, solange du bei Bewusstsein bist (erfordert keine Aktion). Die Kreatur befolgt diese nach Kräften. Du kannst eine einfache, allgemeine Aktion angeben, wie 'Greife diese Kreatur an', 'Lauf dorthin' oder 'Hole diesen Gegenstand'. Wenn die Kreatur den Befehl erfüllt hat und keine weiteren Anweisungen von dir erhält, verteidigt sie sich und versucht nach Kräften, am Leben zu bleiben.","Du kannst eine Aktion verwenden, um vollständige und präzise Kontrolle über das Ziel zu erlangen. Bis zum Ende deines nächsten Zugs führt die Kreatur nur Aktionen deiner Wahl aus und tut nichts, was du ihr nicht erlaubst. Währenddessen kannst du die Kreatur auch reagieren lassen, allerdings musst du dafür deine eigene Reaktion verwenden.","Jedes Mal, wenn das Ziel Schaden erleidet, führt es einen neuen Weisheitsrettungswurf gegen den Zauber aus. Ist der Rettungswurf erfolgreich, endet der Zauber."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades nutzt, ändert sich die Wirkungsdauer zu: Konzentration, bis zu 10 Minuten. Bei einem Zauberplatz des 7. Grades beträgt die Wirkungsdauer: Konzentration, bis zu 1 Stunde. Bei einem Zauberplatz des 8. Grades beträgt die Wirkungsdauer: Konzentration, bis zu 8 Stunden."]},
  {"id":"legend-lore","name":"Sagenkunde","en":"Legend Lore","level":5,"school":"divination","classes":["barde","kleriker","magier"],"time":"10 Minuten","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Nenne oder beschreibe eine Person, einen Ort oder einen Gegenstand. Der Zauber zeigt dir mental eine kurze Zusammenfassung der Überlieferungen des Genannten. Dabei kann es sich um aktuelle Geschichten, vergessene Erzählungen oder sogar geheimes Wissen handeln, das nicht allgemein bekannt ist Ist das Genannte nicht von legendärer Bedeutung, erhältst du keine Informationen. Je mehr Informationen dir bereits zur Verfügung stehen, desto präzisere und detailliertere Informationen erhältst du durch den Zauber.","Die erhaltenen Informationen sind korrekt, können aber in bildlicher Sprache erscheinen. Hast du beispielsweise eine mysteriöse Axt vor dir, übermittelt der Zauber vielleicht die folgenden Informationen: 'Wehe dem Übeltäter, der die Axt berührt, denn selbst der Griff schneidet die Hand des Bösen. Nur ein wahres Kind des Steins, Jünger und Schützling von Moradin, vermag die wahre Macht der Axt zu erwecken, und nur mit dem heiligen Wort Rudnogg auf den Lippen.'"]},
  {"id":"antilife-shell","name":"Schutzhülle gegen Lebendes","en":"Antilife Shell","level":5,"school":"abjuration","classes":["druide"],"time":"1 Aktion","action":"action","range":"Selbst (Radius von 3 m)","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"area":{"shape":"sphere","size":3},"desc":["Eine schimmernde Barriere mit einem Radius von drei Metern umgibt dich. Sie bewegt sich mit dir im Mittelpunkt und hält Kreaturen auf Abstand, die keine Untoten oder Konstrukte sind. Die Barriere bleibt für die Wirkungsdauer bestehen.","Die Barriere verhindert, dass betroffene Kreaturen hindurchgehen oder hindurchgreifen. Sie können jedoch Zauber wirken oder mit Fernkampfwaffen oder Waffen mit Reichweite durch die Barriere angreifen.","Bewegst du dich, so dass eine betroffene Kreatur durch die Barriere passieren muss, endet der Zauber."]},
  {"id":"wall-of-stone","name":"Steinwand","en":"Wall of Stone","level":5,"school":"evocation","classes":["druide","zauberer","magier","magieschmied"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Eine nichtmagische Steinwand erscheint an einem Punkt deiner Wahl in Reichweite. Die Wand ist 15 Zentimeter dick und besteht aus zehn neun Quadratmeter großen Platten. Jede Platte muss an mindestens eine andere angrenzen. Alternativ kannst du drei Meter mal sechs Meter große Platten erschaffen, die nur 7,5 Zentimeter dick sind.","Erschaffst du die Wand so, dass sie den Bereich einer Kreatur durchdringt, wird die Kreatur auf eine Seite der Wand gestoßen (deine Wahl). Wenn eine Kreatur von allen Seiten von der Wand eingeschlossen wäre (oder zwischen der Wand und einer anderen soliden Oberfläche), kann diese Kreatur einen Geschicklichkeitsrettungswurf ausführen. Bei einem Erfolg kann sie ihre Reaktion verwenden, um sich bis zu ihrer Bewegungsrate zu bewegen, so dass sie nicht länger von der Wand eingeschlossen ist.","Die Wand kann jede gewünschte Form annehmen, kann jedoch nicht denselben Bereich wie eine Kreatur oder ein Gegenstand einnehmen. Die Wand muss nicht senkrecht sein oder auf festem Untergrund stehen. Allerdings muss sie mit bestehendem Stein verschmelzen und von ihm getragen werden. Somit kannst du diesen Zauber verwenden, um eine Schlucht zu überwinden oder eine Rampe zu erschaffen.","Wenn du eine Brücke von mehr als sechs Metern Länge erschaffen willst, musst du die halbe Größe jeder Platte für Stützpfeiler verbrauchen. Du kannst die Steinwand grob formen, um Zinnen, Wehranlagen oder dergleichen zu erschaffen.","Die Wand ist ein Objekt aus Stein, das beschädigt und somit durchbrochen werden kann. Jede Platte besitzt eine RK von 15 und 30 Trefferpunkte pro 2,5 Zentimetern Dicke. Sinken die Trefferpunkte einer Platte auf 0, wird sie zerstört, was angrenzende Platten nach Ermessen des SL zum Einsturz bringen könnte.","Konzentrierst du dich für die gesamte Wirkungsdauer auf diesen Zauber, wird die Wand dauerhaft und kann nicht gebannt werden. Ansonsten verschwindet sie, wenn der Zauber endet."]},
  {"id":"telekinesis","name":"Telekinese","en":"Telekinesis","level":5,"school":"transmutation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"area":{"shape":"sphere","size":9},"desc":["Du erhältst die Fähigkeit, Kreaturen oder Gegenstände mit deinen Gedanken zu bewegen oder zu manipulieren. Wenn du den Zauber wirkst und als deine Aktion in jeder Runde während der Wirkungsdauer, kannst du deinen Willen auf eine Kreatur oder einen Gegenstand in Reichweite konzentrieren, den du sehen kannst, und den entsprechenden Effekt auslösen. Du kannst jede Runde dasselbe Ziel beeinflussen oder ein neues wählen. Wechselst du das Ziel, ist das vorherige nicht mehr von dem Zauber betroffen.","Kreatur: Du kannst versuchen, eine maximal riesige Kreatur zu bewegen. Führe einen vergleichenden Attributswurf mit deinem Attribut zum Zauberwirken gegen den Stärkewurf der Kreatur aus. Ist dein Ergebnis höher, kannst du die Kreatur um bis zu neun Meter in eine beliebige Richtung bewegen, auch nach oben, solange sie in Reichweite des Zaubers bleibt. Bis zum Ende deines nächsten Zugs ist die Kreatur in deinem telekinetischen Griff festgesetzt. Eine Kreatur, die nach oben gehoben wird, schwebt in der Luft.","In darauffolgenden Runden kannst du als Aktion versuchen, deinen telekinetischen Griff um die Kreatur aufrecht zu erhalten, indem du den Vergleich wiederholst.","Gegenstand: Du kannst versuchen, einen Gegenstand mit einem Gewicht von bis zu 500 Kilogramm zu bewegen. Wird der Gegenstand weder getragen noch gehalten, bewegst du ihn automatisch bis zu neun Meter in eine beliebige Richtung, solange er in Reichweite des Zaubers bleibt.","Wird der Gegenstand getragen oder gehalten, führe einen vergleichenden Attributswurf mit deinem Attribut zum Zauberwirken gegen den Stärkewurf der Kreatur aus. Ist dein Ergebnis höher, ziehst du den Gegenstand von der Kreatur weg und kannst ihn bis zu neun Meter in eine beliebige Richtung bewegen, solange er in Reichweite des Zaubers bleibt.","Du kannst mit deinem telekinetischen Griff Gegenstände präzise steuern, beispielsweise ein einfaches Werkzeug benutzen, eine Tür oder einen Behälter öffnen, einen Gegenstand aus einem offenen Behälter holen oder ihn verstauen, oder den Inhalt einer Phiole ausgießen."]},
  {"id":"telepathic-bond","name":"Telepathische Bindung","en":"Telepathic Bond","level":5,"school":"divination","classes":["magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":true,"desc":["Du erschaffst eine telepathische Bindung zwischen bis zu acht bereitwilligen Kreaturen deiner Wahl in Reichweite. Dadurch werden alle Kreaturen für die Wirkungsdauer geistig miteinander verbunden. Kreaturen mit einem Intelligenzwert von höchstens 2 sind von diesem Zauber nicht betroffen.","Bis der Zauber endet, können die Ziele telepathisch miteinander kommunizieren, unabhängig davon, ob sie dieselbe Sprache sprechen oder nicht.","Die Kommunikation ist auf jede Entfernung möglich, reicht allerdings nicht bis auf andere Ebenen der Existenz."]},
  {"id":"cloudkill","name":"Todeswolke","en":"Cloudkill","level":5,"school":"conjuration","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"save":"con","damage":{"type":"poison","slots":{"5":"5d8"}},"area":{"shape":"sphere","size":6},"desc":["Du erschaffst eine Sphäre aus giftigem, gelb-grünen Nebel mit einem Radius von sechs Metern an einem Ort deiner Wahl in Reichweite. Der Nebel breitet sich um Ecken aus. Die Sphäre bleibt für die Wirkungsdauer bestehen, oder bis starker Wind den Nebel zerstreut und den Zauber beendet. Ihr Bereich ist komplett verschleiert.","Wenn eine Kreatur den Bereich des Zaubers in einem Zug erstmals betritt oder ihren Zug darin beginnt, muss sie einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 5W8 Giftschaden, anderenfalls die Hälfte. Kreaturen sind auch dann betroffen, wenn sie den Atem anhalten oder nicht atmen müssen.","Zu Beginn jedes deiner Züge bewegt sich der Nebel drei Meter von dir weg und wabert über den Boden. Die Dämpfe sind schwerer als Luft und sinken daher bis in die unterste Ebene des Bodens und strömen sogar durch Öffnungen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 6. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 5. um 1W8."]},
  {"id":"raise-dead","name":"Tote erwecken","en":"Raise Dead","level":5,"school":"necromancy","classes":["barde","kleriker","paladin"],"time":"1 Stunde","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst eine tote Kreatur und erweckst sie wieder zum Leben, sofern sie maximal zehn Tage lang tot war. Wenn die Seele des Ziels willig und frei ist, wieder in den Körper zurückzukehren, wird die Kreatur mit 1 Trefferpunkt zum Leben erweckt.","Dieser Zauber neutralisiert zudem sämtliche Gifte und heilt nichtmagische Krankheiten, unter denen das Ziel zum Zeitpunkt seines Todes gelitten hat. Dieser Zauber hebt jedoch keine magischen Krankheiten, Flüche oder ähnlichen Effekte auf. Werden diese nicht vor dem Wirken des Zaubers gebannt, wirken sie wieder, wenn die Kreatur zum Leben erweckt wird. Der Zauber kann keine untote Kreatur zum Leben erwecken.","Dieser Zauber schließt alle tödlichen Wunden, kann jedoch keine abgetrennten Gliedmaßen wiederherstellen. Fehlen der Kreatur lebensnotwendige Körperteile oder Organe, beispielsweise ihr Kopf, schlägt der Zauber automatisch fehl.","Von den Toten aufzuerstehen ist eine Tortur. Das Ziel erhält einen Malus von -4 auf alle Angriffs-, Attributs- und Rettungswürfe. Nach jeder langen Rast wird der Malus um 1 reduziert, bis er verschwindet."]},
  {"id":"dream","name":"Traum","en":"Dream","level":5,"school":"illusion","classes":["barde","hexenmeister","magier"],"time":"1 Minute","action":"long","range":"Besonders","rangeKind":"spec","rangeM":null,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":false,"save":"wis","damage":{"type":"psychic","slots":{"5":"3d6"}},"desc":["Dieser Zauber formt die Träume einer Kreatur. Wähle als Ziel eine Kreatur, die du kennst. Sie muss sich auf derselben Existenzebene befinden wie du. Kreaturen, die nicht schlafen, wie beispielsweise Elfen, sind von diesem Zauber nicht betroffen.","Der Zauber versetzt dich oder eine bereitwillige Kreatur, die du berührst, in Trance - als Boten. Während der Trance ist sich der Bote seiner Umgebung bewusst, kann jedoch keine Aktionen ausführen oder sich bewegen.","Wenn das Ziel schläft, erscheint der Bote in den Träumen des Ziels und kann mit ihm für die Wirkungsdauer des Zaubers sprechen, solange es schläft. Der Bote kann zudem die Umgebung des Traums gestalten und Landschaften, Gegenstände oder andere Bilder erschaffen. Der Bote kann die Trance jederzeit verlassen und den Zauber somit vorzeitig beenden. Das Ziel erinnert sich beim Aufwachen perfekt an den Traum. Ist das Ziel wach, wenn du den Zauber wirkst, weiß der Bote dies und kann die Trance (und den Zauber) entweder beenden oder warten, bis das Ziel einschläft und dann in dessen Träumen erscheinen.","Du kannst den Boten für das Ziel monströs und furchteinflößend erscheinen lassen. In diesem Fall kann der Bote eine Nachricht von höchstens zehn Wörtern übermitteln. Dann muss das Ziel einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, erschaffen die Echos der trügerischen Monstrosität einen Alptraum, der anhält, solange das Ziel schläft und verhindert, dass es die Effekte der Rast erhält. Außerdem erleidet das Ziel beim Aufwachen 3W6 psychischen Schaden.","Besitzt du eine Haarsträhne, einen Fingernagel oder dergleichen vom Körper des Ziels, ist es beim Rettungswurf im Nachteil."]},
  {"id":"greater-restoration","name":"Vollständige Genesung","en":"Greater Restoration","level":5,"school":"abjuration","classes":["barde","kleriker","druide","magieschmied"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst eine Kreatur und erfüllst sie mit positiver Energie, um einen schwächenden Effekt aufzuheben.","Du kannst die Erschöpfung des Ziels um eine Stufe senken oder einen der folgenden Effekte auf dem Ziel beenden:"]},
  {"id":"passwall","name":"Wände passieren","en":"Passwall","level":5,"school":"transmutation","classes":["magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Ein Durchgang erscheint an einem Punkt deiner Wahl in Reichweite, den du auf einer Oberfläche aus Holz, Gips oder Stein sehen kannst (etwa eine Mauer, eine Decke oder ein Fußboden). Er bleibt für die Wirkungsdauer bestehen. Du bestimmst die Ausmaße des Durchgangs: maximal 1,5 Meter breit, 2,5 Meter hoch und sechs Meter tief. Der Durchgang macht die umgebende Struktur nicht instabil.","Wenn der Durchgang verschwindet, werden sämtliche Kreaturen und Gegenstände, die sich noch darin befinden, sicher an eine freie Stelle ausgestoßen, die der Oberfläche am nächsten liegt, auf die der Zauber gewirkt wurde."]},
  {"id":"hallow","name":"Weihen","en":"Hallow","level":5,"school":"evocation","classes":["kleriker"],"time":"24 Stunden","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":false,"save":"cha","area":{"shape":"sphere","size":18},"desc":["Du berührst einen Punkt und erfüllst den Bereich um ihn herum mit heiliger (oder unheiliger) Macht. Der Bereich kann einen Radius von bis zu 18 Metern haben. Der Zauber schlägt fehlt, wenn zum Radius ein Bereich gehört, der bereits unter dem Effekt des Zaubers Weihen steht. Der betroffene Bereich unterliegt den folgenden Effekten:","Celestische Wesen, Elementare, Feenwesen, Unholde und Untote können den Bereich weder betreten noch Kreaturen innerhalb des Bereichs besessen machen, bezaubern oder verängstigen. Wenn eine Kreatur von diesen Kreaturen besessen, bezaubert oder verängstigt ist, endet dieser Zustand, sobald sie den Bereich betritt. Du kannst einen oder mehrere Arten von Kreaturen von diesem Effekt ausschließen.","Zudem kannst du einen zusätzlichen Effekt an den Bereich binden. Wähle einen Effekt aus der folgenden Liste oder einen, den dir dein SL anbietet. Einige dieser Effekte wirken auf Kreaturen in dem Bereich. Du kannst bestimmen, ob der Effekt auf alle Kreaturen wirkt, nur auf Kreaturen, die einer bestimmten Gottheit oder einem Anführer folgen, oder auf Kreaturen einer bestimmten Art wie Orks oder Trolle. Wenn eine Kreatur, die davon betroffen wäre, den Bereich des Zaubers in einem Zug erstmals betritt oder ihren Zug darin beginnt, kann sie einen Charismarettungswurf ausführen. Bei einem Erfolg ignoriert die Kreatur den zusätzlichen Effekt, bis sie den Bereich verlässt.","Anfälligkeit gegen Energie: Betroffene Kreaturen in dem Bereich sind anfällig für eine Schadensart deiner Wahl, mit Ausnahme von Hieb-, Stich- oder Wuchtschaden.","Dunkelheit: Dunkelheit erfüllt den Bereich. Natürliches und magisches Licht, das von Zaubern eines niedrigeren Grades erschaffen wurde als der Zauberplatz, den du zum Wirken von Weihen verwendet hast, kann den Bereich nicht erhellen.","Ewige Ruhe: Leichen innerhalb des Bereichs können nicht in Untote verwandelt werden.","Extradimensionale Interferenz: Betroffene Kreaturen können nicht mittels Teleportation oder auf extradimensionale oder interplanare Art reisen.","Furcht: Betroffene Kreaturen sind verängstigt, während sie sich in dem Bereich befinden.","Mut: Betroffene Kreaturen können nicht verängstigt werden, während sie sich in dem Bereich befinden.","Schutz vor Energie: Betroffene Kreaturen in dem Bereich sind gegen eine Schadensart deiner Wahl resistent, mit Ausnahme von Hieb-, Stich- oder Wuchtschaden.","Stille: Aus dem Bereich können keine Geräusche dringen, ebenso wenig wie in ihn hinein.","Tageslicht: Helles Licht erfüllt den Bereich. Magische Dunkelheit, die von Zaubern eines niedrigeren Grades erschaffen wurde als der Zauberplatz, den du zum Wirken von Weihen verwendet hast, kann das Licht nicht löschen.","Zungen: Betroffene Kreaturen können mit allen anderen Kreaturen in dem Bereich kommunizieren, selbst wenn sie keine gemeinsame Sprache sprechen."]},
  {"id":"reincarnate","name":"Wiedergeburt","en":"Reincarnate","level":5,"school":"transmutation","classes":["druide"],"time":"1 Stunde","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst eine tote humanoide Kreatur oder ihre Überreste. Falls die Kreatur maximal zehn Tage lang tot war, erschafft der Zauber einen neuen, erwachsenen Körper für sie und ruft dann die Seele in diesen Körper herbei. Ist die Seele des Ziels nicht frei oder bereitwillig zurückzukehren, schlägt der Zauber fehl.","Die Magie erschafft einen neuen Körper für die Kreatur, der wahrscheinlich einem anderen Volk angehört. Der SL würfelt mit einem W100 und bestimmt anhand der folgenden Tabelle, welche Gestalt die Kreatur annimmt, wenn sie zum Leben erweckt wird. Alternativ kann der SL eine Gestalt auswählen.","Die wiedergeborene Kreatur erinnert sich an ihr früheres Leben und ihre Erfahrungen. Sie behält die Fähigkeiten ihrer ursprünglichen Gestalt. Nur die Volksmerkmale ihres bisherigen Volks werden durch die des neuen ersetzt."]},
  {"id":"disintegrate","name":"Auflösung","en":"Disintegrate","level":6,"school":"transmutation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","area":{"shape":"cube","size":3},"desc":["Ein dünner grüner Strahl schießt von deinem ausgestreckten Finger auf ein Ziel in Reichweite, das du sehen kannst. Dabei kann es sich um eine Kreatur, einen Gegenstand oder ein Gebilde aus magischer Energie handeln, wie die Wand durch den Zauber Energiewand.","Eine Kreatur, die zum Ziel dieses Zaubers wird, muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet das Ziel 10W6+40 Energieschaden. Werden durch diesen Schaden die Trefferpunkte des Ziels auf 0 verringert, wird es aufgelöst.","Eine aufgelöste Kreatur und ihre gesamte Ausrüstung (mit Ausnahme von magischen Gegenständen) zerfällt zu feinem, grauen Staub. Sie kann nur durch die Zauber Wahre Auferstehung oder Wunsch wiedererweckt werden.","Ein maximal großer nichtmagischer Gegenstand oder ein Gebilde aus magischer Energie wird von diesem Zauber automatisch aufgelöst. Handelt es sich bei dem Ziel um einen mindestens riesigen Gegenstand oder ein Gebilde aus magischer Energie, löst dieser Zauber einen Würfel mit drei Metern Kantenlänge davon auf. Ein magischer Gegenstand ist von diesem Zauber nicht betroffen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 6. um 3W6."]},
  {"id":"eyebite","name":"Böser Blick","en":"Eyebite","level":6,"school":"necromancy","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","desc":["Für die Wirkungsdauer werden deine Augen zu einer tiefschwarzen Leere, die von schauerlicher Macht erfüllt ist. Eine Kreatur deiner Wahl, die du sehen kannst und die sich im Abstand von bis zu 18 Metern von dir befindet, muss einen Weisheitsrettungswurf bestehen, anderenfalls leidet sie für die Wirkungsdauer unter einem der folgenden Effekte deiner Wahl. Bis der Zauber endet, kannst du deine Aktion in jedem deiner Züge verwenden, um eine andere Kreatur als Ziel auszuwählen. Du kannst jedoch keine Kreatur erneut als Ziel auswählen, die bei ihrem Rettungswurf gegen Böser Blick Erfolg hatte.","Krank: Das Ziel ist bei Angriffs- und Attributswürfen im Nachteil. Am Ende jedes seiner Züge kann es einen weiteren Weisheitsrettungswurf ausführen. Ist der Rettungswurf erfolgreich, endet der Effekt.","Panik: Das Ziel ist von dir verängstigt.","Verängstigte Kreaturen müssen in jedem Zug die Spurt-Aktion ausführen und sich auf dem sichersten und kürzesten Weg von dir entfernen, sofern das technisch möglich ist. Wenn sich das Ziel mindestens 18 Meter von dir wegbewegt und dich nicht länger sehen kann, endet dieser Effekt.","Schlaf: Das Zielt wird bewusstlos. Es wacht auf, wenn es Schaden erleidet oder wenn eine andere Kreatur eine Aktion verwendet, um es wachzurütteln."]},
  {"id":"wall-of-thorns","name":"Dornenwand","en":"Wall of Thorns","level":6,"school":"conjuration","classes":["druide"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"save":"dex","damage":{"type":"piercing","slots":{"6":"7d8"}},"area":{"shape":"line","size":18,"width":1.5},"desc":["Du erschaffst eine Wand aus zähem, biegsamem und verworrenem Gestrüpp mit nadelscharfen Dornen. Die Wand erscheint auf einer festen Oberfläche in Reichweite und bleibt für die Wirkungsdauer bestehen. Die Wand kann bis zu 18 Meter lang, drei Meter hoch und 1,5 Meter dick sein. Alternativ kannst du eine ringförmige Wand mit einem Durchmesser von sechs Metern erschaffen, die bis zu sechs Meter hoch und 1,5 Meter dick ist Die Wand blockiert die Sichtlinie.","Wenn die Wand erscheint, muss jede Kreatur in ihrem Bereich einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 7W8 Stichschaden, anderenfalls die Hälfte.","Eine Kreatur kann die Dornenwand durchdringen, jedoch nur langsam und unter Schmerzen. Für jeden Meter, den sie sich durch die Wand bewegt, muss sie vier Meter ihrer Bewegungsrate verwenden. Zudem muss eine Kreatur, die die Wand in einem Zug erstmals betritt oder ihren Zug darin beendet, einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 7W8 Hiebschaden, anderenfalls die Hälfte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, steigen beide Schadensarten für jeden Grad über dem 6. um 1W8."]},
  {"id":"wall-of-ice","name":"Eiswand","en":"Wall of Ice","level":6,"school":"evocation","classes":["magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"save":"dex","damage":{"type":"cold","slots":{"6":"10d6"}},"area":{"shape":"sphere","size":3},"desc":["Du erschaffst eine Eiswand auf einer festen Oberfläche in Reichweite. Du kannst sie zu einer halbrunden Kuppel oder einer Sphäre mit einem Radius von bis zu drei Metern formen, oder du kannst eine flache Oberfläche aus zehn Platten erschaffen, die jeweils drei Quadratmeter groß sind. Jede Platte muss an eine andere angrenzen. In jeder Form ist die Wand 30 Zentimeter dick und bleibt für die Wirkungsdauer bestehen.","Erschaffst du die Wand so, dass sie den Bereich einer Kreatur durchdringt, wird die Kreatur auf eine Seite der Wand gestoßen und muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 10W6 Kälteschaden, anderenfalls die Hälfte.","Die Wand ist ein Objekt, das beschädigt und somit durchbrochen werden kann. Sie besitzt eine RK von 12, 30 Trefferpunkte pro Abschnitt von drei Metern und ist anfällig für Feuerschaden. Sinken die Trefferpunkte eines Abschnitts von drei Metern der Wand auf 0, wird dieser Abschnitt zerstört und hinterlässt in seinem Bereich eine eisige Luftschicht. Wenn eine Kreatur die eisige Luftschicht in einem Zug erstmals durchquert, muss sie einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 5W6 Kälteschaden, anderenfalls die Hälfte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, steigt der Schaden, den die Wand beim Erscheinen verursacht, für jeden Grad über dem 6. um 2W6, und der Schaden für das Durchqueren der eisigen Luftschicht um 1W6."]},
  {"id":"move-earth","name":"Erde bewegen","en":"Move Earth","level":6,"school":"transmutation","classes":["druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Konzentration, bis zu 2 Stunden","conc":true,"ritual":false,"area":{"shape":"cone","size":12},"desc":["Wähle einen viereckigen Bereich des Geländes in Reichweite mit einer Seitenlänge von maximal zwölf Metern. Für die Wirkungsdauer kannst du Erde, Lehn oder Sand in dem Bereich beliebig umformen. Du kannst den Bereich erheben, einen Graben erschaffen oder aufschütten, eine Mauer errichten oder niederreißen, oder eine Säule errichten. Das Ausmaß dieser Änderungen darf die Hälfte der größten Abmessung des Bereichs nicht übersteigen. Beeinflusst du also einen Bereich mit einer Seitenlänge von zwölf Metern, kannst du eine bis zu sechs Meter hohe Säule erschaffen, den Bereich um bis zu sechs Meter anheben oder senken, einen Graben mit bis zu sechs Metern Tiefe ausheben und so weiter. Diese Änderungen dauern zehn Minuten.","Am Ende der jeweils zehn Minuten, die du dich auf den Zauber konzentrierst, kannst du einen neuen Bereich auswählen, den du beeinflusst.","Da die Veränderung des Geländes langsam erfolgt, können Kreaturen in dem Bereich normalerweise nicht durch die Bodenbewegung gefangen oder verletzt werden.","Dieser Zauber kann weder Naturgestein noch Steinstrukturen beeinflussen. Felsen und Gebäude verschieben sich, um sich dem neuen Gelände anzupassen. Würde deine Veränderung des Geländes ein Bauwerk instabil machen, könnte es einstürzen.","Gleichermaßen hat dieser Zauber keinen direkten Einfluss auf Pflanzenwachstum. Die bewegte Erde nimmt Pflanzen mit sich."]},
  {"id":"conjure-fey","name":"Feenwesen beschwören","en":"Conjure Fey","level":6,"school":"conjuration","classes":["druide","hexenmeister"],"time":"1 Minute","action":"long","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde Du beschwörst ein Feenwesen mit Herausforderungsgrad 6 oder niedriger, oder einen Feengeist, der die Form eines Tiers mit Herausforderungsgrad 6 oder niedriger annimmt. Es erscheint in einem freien Bereich in Reichweite, den du sehen kannst. Das Feenwesen verschwindet, wenn der Zauber endet oder seine Trefferpunkte auf 0 sinken.","conc":true,"ritual":false,"desc":["Das Feenwesen ist dir und deinen Gefährten für die Wirkungsdauer freundlich gesinnt. Würfle die Initiative für das Wesen aus, das über seinen eigenen Zug verfügt. Es gehorcht deinen mündlichen Befehlen (erfordert keine Aktion), solange sie nicht gegen seine Gesinnung verstoßen. Wenn du dem Feenwesen keine Befehle erteilst, verteidigt es sich gegen feindlich gesinnte Kreaturen, führt aber anderenfalls keine Aktionen aus.","Wenn deine Konzentration unterbrochen wird, verschwindet das Feenwesen nicht. Stattdessen verlierst du die Kontrolle über das Feenwesen und es wird dir und deinen Gefährten gegenüber feindlich gesinnt und greift möglicherweise an. Ein unkontrolliertes Feenwesen kann nicht von dir fortgeschickt werden und verschwindet eine Stunde nach seiner Beschwörung.","Der SL hat die Werte des Feenwesens."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, erhöht sich der Herausforderungsgrad für jeden Grad über dem 6. um 1."]},
  {"id":"flesh-to-stone","name":"Fleisch zu Stein","en":"Flesh to Stone","level":6,"school":"transmutation","classes":["hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"con","desc":["Du versuchst, eine Kreatur in Reichweite, die du sehen kannst, in Stein zu verwandeln. Besteht der Körper des Ziels aus Fleisch, muss die Kreatur einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, ist sie festgesetzt und ihr Fleisch verhärtet sich. Bei einem erfolgreichen Rettungswurf ist die Kreatur nicht betroffen.","Eine von diesem Zauber festgesetzte Kreatur muss am Ende jedes ihrer Züge einen weiteren Konstitutionsrettungswurf ausführen. Bei drei erfolgreichen Rettungswürfen endet dieser Zauber. Scheitert der Wurf dreimal, wird sie zu Stein und leidet für die Wirkungsdauer unter dem Versteinert-Zustand. Die erfolgreichen und gescheiterten Würfe müssen nicht unmittelbar aufeinanderfolgen. Notiere dir einfach beide, bis das Ziel drei der gleichen hat.","Wird die Kreatur physisch zerbrochen, während sie versteinert ist, leidet sie unter ähnlichen Deformationen, wenn sie sich zurückverwandelt.","Konzentrierst du dich für die gesamte Wirkungsdauer auf diesen Zauber, wird die Kreatur in Stein verwandelt, bis der Effekt aufgehoben wird."]},
  {"id":"freezing-sphere","name":"Frostsphäre","en":"Freezing Sphere","level":6,"school":"evocation","classes":["magier"],"time":"1 Aktion","action":"action","range":"90 m","rangeKind":"dist","rangeM":90,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"cold","slots":{"6":"10d6"}},"area":{"shape":"sphere","size":18},"desc":["Eine Kugel aus klirrender Kälte schießt aus deinen Fingerspitzen an einen Punkt deiner Wahl in Reichweite, wo sie als Sphäre mit einem Radius von 18 Metern explodiert. Jede Kreatur in dem Bereich muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, so erleidet die Kreatur 10W6 Kälteschaden. Bei einem erfolgreichen Rettungswurf erleidet sie halb so viel Schaden.","Trifft die Kugel ein Gewässer oder eine Flüssigkeit, die größtenteils aus Wasser besteht (dazu gehören keine Wasserkreaturen), lässt sie die Flüssigkeit in einem würfelförmigen Bereich von neun Metern mal neun Metern mit 15 Zentimetern Tiefe gefrieren. Das Eis hält eine Minute lang an. Kreaturen, die auf der Oberfläche des gefrorenen Wassers schwimmen, werden im Eis gefangen. Eine gefangene Kreatur kann als Aktion einen Stärkewurf gegen deinen Zauberrettungswurf-SG ausführen, um sich zu befreien.","Du musst die Kugel nach dem Wirken des Zaubers nicht sofort abfeuern. In diesem Fall erscheint eine kleine, kühle Kugel von der Größe eines Schleudersteins in deiner Hand. Du - oder eine Kreatur, der du die Kugel gibst - kannst sie jederzeit bis zu zwölf Meter weit werfen oder sie mit einer Schleuder in deren Reichweite verschießen. Die Kugel zerbricht beim Aufprall und bewirkt denselben Effekt wie das normale Wirken des Zaubers. Du kannst die Kugel auch ablegen, ohne sie zu zerbrechen. Ist sie nach einer Minute nicht zerbrochen, explodiert sie."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 6. um 1W6."]},
  {"id":"heal","name":"Heilung","en":"Heal","level":6,"school":"evocation","classes":["kleriker","druide"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"heal":{"slots":{"6":"70","7":"80","8":"90","9":"100"}},"desc":["Wähle eine Kreatur in Reichweite, die du sehen kannst. Eine Welle positiver Energie durchströmt das Ziel und stellt 70 Trefferpunkte wieder her. Der Zauber beendet zudem die Zustände Blindheit und Taubheit, sowie alle Krankheiten, unter denen das Ziel leidet. Dieser Zauber wirkt nicht auf Untote oder Konstrukte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, steigt die Heilung für jeden Grad über dem 6. um 10."]},
  {"id":"heroes-feast","name":"Heldenmahl","en":"Heroes' Feast","level":6,"school":"conjuration","classes":["kleriker","druide"],"time":"10 Minuten","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"heal":{"dice":"2d10","mod":false},"desc":["Du erschaffst ein riesiges Festmahl aus herrlichem Essen und Trinken. Der Verzehr des Festmahls dauert eine Stunde. Nach dieser Zeit verschwindet es und die positiven Effekte treten erst nach Ablauf dieser Stunde in Kraft. Bis zu zwölf weitere Kreaturen können an dem Festmahl teilnehmen.","Eine Kreatur, die an dem Festmahl teilnimmt, erhält verschiedene Vorteile: Sie wird von allen Krankheiten und Giften geheilt, ist gegen Gift immun, kann nicht verängstigt werden und ist bei allen Weisheitsrettungswürfen im Vorteil. Ihr Trefferpunktemaximum steigt zudem um 2W10 und sie erhält dieselbe Anzahl an Trefferpunkten dazu. Diese Vorteile halten 24 Stunden lang an."]},
  {"id":"chain-lightning","name":"Kettenblitz","en":"Chain Lightning","level":6,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"lightning","slots":{"6":"10d8"}},"desc":["Du erschaffst einen Blitz, der auf ein Ziel deiner Wahl in Reichweite zuschießt, das du sehen kannst. Drei Blitze springen dann von diesem Ziel auf bis zu drei weitere über, die sich im Abstand von bis zu neun Metern vom ersten Ziel befinden. Beim Ziel kann es sich um eine Kreatur oder einen Gegenstand handeln. Es kann nur von einem der Blitze getroffen werden.","Das Ziel muss einen Geschicklichkeitsrettungswurf ausfuhren. Scheitert der Wurf, erleidet das Ziel 10W8 Blitzschaden, anderenfalls die Hälfte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, springt für jeden Grad über dem 6. ein zusätzlicher Blitz vom ersten Ziel auf ein weiteres Ziel über."]},
  {"id":"blade-barrier","name":"Klingenbarriere","en":"Blade Barrier","level":6,"school":"evocation","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"save":"dex","damage":{"type":"force","slots":{"6":"6d10"}},"area":{"shape":"line","size":30,"width":1.5},"desc":["Du erschaffst eine vertikale Wand wirbelnder, rasiermesserscharfer Klingen aus magischer Energie. Sie erscheint in Reichweite und bleibt für die Wirkungsdauer bestehen. Du kannst eine gerade Wand erschaffen, die bis zu 30 Meter lang ist, oder eine ringförmige Wand mit bis zu 18 Meter Durchmesser. In beiden Fällen ist die Wand sechs Meter hoch und 1,5 Meter dick. Die Wand bietet allen Kreaturen dahinter Dreivierteldeckung und stellt schwieriges Gelände dar.","Wenn eine Kreatur den Bereich der Wand in einem Zug erstmals betritt oder den Zug darin beginnt, muss sie einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 6W10 Hiebschaden. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur halb so viel Schaden."]},
  {"id":"globe-of-invulnerability","name":"Kugel der Unverwundbarkeit","en":"Globe of Invulnerability","level":6,"school":"abjuration","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Radius von 3 m)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"area":{"shape":"sphere","size":3},"desc":["Eine unbewegliche, leicht schimmernde Barriere entsteht in einem Radius von drei Metern um dich herum und bleibt für die Wirkungsdauer bestehen.","Jeder Zauber des maximal 5. Grades, der außerhalb der Barriere gewirkt wird, hat keinen Effekt auf Kreaturen oder Gegenstände im Innern, selbst wenn der Zauber mit einem Zauberplatz eines höheren Grades gewirkt wird. Ein derartiger Zauber kann Kreaturen und Objekte innerhalb der Barriere zum Ziel haben, hat jedoch keinen Effekt auf sie. Gleichermaßen ist der Bereich innerhalb der Barriere von Flächeneffekten solcher Zauber ausgeschlossen."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, blockiert die Barriere einen Grad höhere Zauber für jeden Zauberplatzgrad über dem 6. Grad."]},
  {"id":"harm","name":"Leid","en":"Harm","level":6,"school":"necromancy","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"necrotic","slots":{"6":"14d6"}},"desc":["Du entfesselst eine infektiöse Krankheit bei einer Kreatur in Reichweite, die du sehen kannst. Das Ziel muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet das Ziel 14W6 nekrotischen Schaden, anderenfalls die Hälfte. Der Schaden kann die Trefferpunkte des Ziels nicht unter 1 senken. Scheitert der Wurf, ist das Trefferpunktemaximum des Ziels eine Stunde lang um den Betrag des erlittenen nekrotischen Schadens verringert. Effekte, die Krankheiten heilen, stellen das Trefferpunktemaximum der Kreatur vor Ablauf dieser Zeit wieder her."]},
  {"id":"magic-jar","name":"Magisches Gefäß","en":"Magic Jar","level":6,"school":"necromancy","classes":["magier"],"time":"1 Minute","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":false,"save":"cha","desc":["Dein Körper verfällt in einen katatonischen Zustand, während deine Seele deinen Körper verlässt und in den Behälter eindringt, den du als Materialkomponente des Zaubers verwendest Während sich deine Seele im Behälter befindet, nimmst du deine Umgebung wahr, als würdest du dich im Bereich des Behälters aufhalten. Du kannst dich nicht bewegen oder reagieren.","Als einzige mögliche Aktion kannst du deine Seele bis zu 30 Meter außerhalb des Behälters projizieren und entweder in deinen lebenden Körper zurückkehren -und den Zauber beenden - oder versuchen, dich des Körpers eines Humanoiden zu bemächtigen.","Du kannst versuchen, von einem beliebigen Humanoiden im Abstand von bis zu 30 Metern von dir Besitz zu ergreifen, den du sehen kannst. Ausgenommen sind Kreaturen, die unter dem Zauber Schutz vor Gut und Böse oder Schutzkreis stehen. Das Ziel muss einen Charismarettungswurf ausführen. Scheitert der Wurf, besetzt deine Seele den Körper des Ziels und dessen Seele wird im Behälter gefangen. Bei einem Erfolg widersteht das Ziel dir und du kannst 24 Stunden lang keinen weiteren Versuch unternehmen.","Sobald du vom Körper einer Kreatur Besitz ergriffen hast, kontrollierst du ihn. Deine Spielwerte werden durch die Werte der Kreatur ersetzt, du behältst jedoch deine Gesinnung sowie deine Intelligenz-, Weisheits- und Charismawerte.","Du behältst zudem die Vorzüge deiner eigenen Klassenmerkmale. Verfügt das Ziel über","Klassenstufen, kannst du keine seiner Klassenmerkmale verwenden.","Währenddessen kann die Seele der Kreatur die Umgebung um den Behälter mit ihren eigenen Sinnen wahrnehmen, kann sich jedoch nicht bewegen und keine Aktionen ausführen.","Während du von einem Körper Besitz ergriffen hast, kannst du als Aktion vom Wirtskörper zum Behälter zurückkehren, sofern sich dieser im Abstand von bis zu 30 Metern von dir befindet. Dadurch wird die Seele der Kreatur in ihren Körper zurückbefördert. Stirbt der Wirtskörper, während du dich darin befindest, stirbt die Kreatur und du musst einen Charismarettungswurf gegen deinen eigenen Zauberrettungswurf-SG aus führen. Bei einem Erfolg kehrst du in den Behälter zurück, wenn er sich im Abstand von bis zu 30 Metern von dir befindet. Anderenfalls stirbst du.","Wird der Behälter zerstört oder endet der Zauber, kehrt deine Seele sofort in deinen Körper zurück. Befindet sich dein Körper mehr als 30 Meter von dir entfernt oder ist dein Körper tot, wenn du in ihn zurückkehren willst, stirbst du. Befindet sich die Seele einer anderen Kreatur im Behälter, wenn er zerstört wird, kehrt ihre Seele in ihren Körper zurück, sofern dieser am Leben ist und sich im Abstand von bis zu 30 Metern von ihr befindet. Ansonsten stirbt die Kreatur.","Wenn der Zauber endet, wird der Behälter zerstört"]},
  {"id":"mass-suggestion","name":"Massen-Einflüsterung","en":"Mass Suggestion","level":6,"school":"enchantment","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, M","duration":"24 Stunden","conc":false,"ritual":false,"save":"wis","desc":["Du schlägst eine Vorgehensweise vor (auf einen oder zwei Sätze beschränkt) und beeinflusst auf magische Weise bis zu zwölf Kreaturen deiner Wahl in Reichweite, die du sehen kannst und die dich hören und verstehen können. Kreaturen, die nicht bezaubert werden können, sind gegen diesen Effekt immun. Die Einflüsterung muss so formuliert sein, dass die vorgeschlagene Vorgehensweise angemessen erscheint. Aufforderungen, sich selbst zu erstechen, sich in einen Speer zu stürzen, sich anzuzünden oder auf andere Weise zu verletzen, heben die Wirkung des Zaubers auf.","Jedes Ziel muss einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, führt es die von dir beschriebene Vorgehensweise nach Kräften aus. Die vorgeschlagene Vorgehensweise kann während der gesamten Wirkungsdauer fortgesetzt werden. Wenn die vorgeschlagene Aktivität in kürzerer Zeit abgeschlossen werden kann, endet der Zauber, sobald das Ziel die Aktivität beendet hat.","Du kannst auch Bedingungen festlegen, die während der Wirkungsdauer eine besondere Handlung auslösen. Beispielsweise könntest du vorschlagen, dass eine Gruppe Soldaten dem ersten Bettler, den sie treffen, all ihr Geld geben. Wird die Bedingung vor Ablauf der Wirkungsdauer nicht erfüllt, wird die Handlung nicht ausgeführt.","Fügt einer deiner Begleiter oder du einer Kreatur Schaden zu, die von diesem Zauber betroffen ist, endet der Zauber für diese Kreatur."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades nutzt, beträgt die Wirkungsdauer zehn Tage. Bei einem Zauberplatz des 8. Grades beträgt die Wirkungsdauer 30 Tage. Bei einem Zauberplatz des 9. Grades beträgt die Wirkungsdauer ein Jahr und einen Tag."]},
  {"id":"contingency","name":"Notfall","en":"Contingency","level":6,"school":"evocation","classes":["magier"],"time":"10 Minuten","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"10 Tage","conc":false,"ritual":false,"desc":["Wähle einen Zauber des höchstens 5. Grades, den du auf dich selbst wirken kannst und dessen Zeitaufwand eine Aktion beträgt. Du wirkst diesen Zauber (auch Notfallzauber genannt) gemeinsam mit Notfall und verbrauchst Zauberplätze für beide. Der Notfallzauber tritt allerdings erst in Kraft, wenn ein bestimmter Umstand eintritt, den du beschreibst, wenn du die beiden Zauber wirkst. Beispiel: Wirkst du Notfall gemeinsam mit Wasser atmen, kannst du bestimmen, dass Wasser atmen in Kraft tritt, wenn du in Wasser oder einer ähnlichen Flüssigkeit untertauchst.","Der Notfallzauber tritt sofort in Kraft, wenn der Umstand das erste Mal auftritt, egal, ob du es willst oder nicht. Danach endet Notfall.","Der Notfallzauber wirkt nur auf dich, selbst wenn er normalerweise auch auf andere Ziele gewirkt werden könnte. Du kannst immer nur einen Notfallzauber gleichzeitig verwenden. Wirkst du diesen Zauber erneut, endet der Effekt eines anderen Notfallzaubers auf dich. Notfall endet auch, wenn du die Materialkomponenten nicht mehr bei dir hast."]},
  {"id":"transport-via-plants","name":"Pflanzentor","en":"Transport via Plants","level":6,"school":"conjuration","classes":["druide"],"time":"1 Aktion","action":"action","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G","duration":"1 Runde","conc":false,"ritual":false,"desc":["Dieser Zauber erschafft eine magische Verbindung zwischen einer mindestens großen, unbelebten Pflanze in Reichweite und einer anderen Pflanze in beliebiger Entfernung auf derselben Existenzebene. Du musst die Zielpflanze mindestens einmal gesehen oder berührt haben. Für die Wirkungsdauer kann jede Kreatur die verzauberte Pflanze betreten und steigt aus der Zielpflanze wieder heraus. Dafür benötigt sie 1,5 Meter ihrer Bewegungsrate."]},
  {"id":"word-of-recall","name":"Rückruf","en":"Word of Recall","level":6,"school":"conjuration","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"1,5 m","rangeKind":"dist","rangeM":1.5,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"area":{"shape":"sphere","size":1.5},"desc":["Dieser Zauber teleportiert dich und bis zu fünf bereitwillige Kreaturen, die sich im Abstand von bis zu 1,5 Metern von dir befinden, sofort zu einer zuvor festgelegten Zuflucht Du und alle Kreaturen, die mit dir teleportiert werden, erscheint an einer freien Stelle, die der von dir als Zuflucht bestimmten Ort am nächsten liegt (siehe unten). Wirkst du diesen Zauber, ohne zuvor eine Zuflucht festzulegen, hat er keinen Effekt","Du bestimmst eine Zuflucht, indem du diesen Zauber an einem Ort wirkst, der deiner Gottheit geweiht oder stark mit ihr verbunden ist - beispielweise in einem Tempel. Versuchst du, diesen Zauber auf diese Weise in einem Bereich zu wirken, der nicht deiner Gottheit gewidmet ist, hat der Zauber keinen Effekt"]},
  {"id":"instant-summons","name":"Sofortige Beschwörung","en":"Instant Summons","level":6,"school":"conjuration","classes":["magier"],"time":"1 Minute","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":true,"desc":["Du berührst einen Gegenstand mit einem Gewicht von maximal 4,5 Kilogramm und einer Länge von maximal 1,8 Metern. Der Zauber hinterlässt ein unsichtbares Mal auf der Oberfläche des Gegenstands und schreibt dessen Namen auf den Saphir, den du als Materialkomponente verwendest. Jedes Mal, wenn du diesen Zauber wirkst, musst du einen anderen Saphir verwenden.","Danach kannst du jederzeit deine Aktion verwenden, um den Namen des Gegenstands auszusprechen und den Saphir zu zerbrechen. Der Gegenstand erscheint sofort in deiner Hand, unabhängig von seiner physischen oder planaren Entfernung, und der Zauber endet.","Hält oder trägt eine andere Kreatur den Gegenstand, wird er beim Zerbrechen des Saphirs nicht zu dir transportiert Stattdessen erfährst du, welche Kreatur den Gegenstand besitzt und wo sie sich in diesem Augenblick ungefähr aufhält.","Wird der Zauber Magie bannen oder ein ähnlicher Effekt erfolgreich auf den Saphir gewirkt, endet dieser Zauber."]},
  {"id":"sunbeam","name":"Sonnenstrahl","en":"Sunbeam","level":6,"school":"evocation","classes":["druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Linie von 18 m)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"con","damage":{"type":"radiant","slots":{"6":"6d8"}},"area":{"shape":"line","size":18,"width":1.5},"desc":["Ein heller Lichtstrahl schießt in einer 1,5 Meter breiten und 18 Meter langen Linie aus deiner Hand. Jede Kreatur in der Linie muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 6W8 gleißenden Schaden und ist bis zu deinem nächsten Zug blind. Bei einem erfolgreichen Rettungswurf erleidet sie halb so viel Schaden und wird nicht blind. Untote und Schlicke sind bei diesem Rettungswurf im Nachteil.","Als Aktion kannst du in jedem deiner Züge eine neue Linie aus Licht erschaffen, bis der Zauber endet.","Für die Wirkungsdauer erstrahlt ein heller Funke in deiner Hand. Er spendet in einem Radius von neun Metern helles Licht und von weiteren neun Metern dämmriges Licht. Beim Licht handelt es sich um Sonnenlicht."]},
  {"id":"circle-of-death","name":"Todeskreis","en":"Circle of Death","level":6,"school":"necromancy","classes":["zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"necrotic","slots":{"6":"8d6","7":"10d6","8":"12d6","9":"14d6"}},"area":{"shape":"sphere","size":18},"desc":["Negative Energie breitet sich von einem Punkt in Reichweite in einer Sphäre mit einem Radius von 18 Metern aus. Jede Kreatur in dem Bereich muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet das Ziel 8W6 nekrotischen Schaden, anderenfalls die Hälfte."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 6. um 2W6."]},
  {"id":"create-undead","name":"Untote erschaffen","en":"Create Undead","level":6,"school":"necromancy","classes":["kleriker","hexenmeister","magier"],"time":"1 Minute","action":"long","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du kannst diesen Zauber nur nachts wirken. Wähle bis zu drei Leichen kleiner oder mittelgroßer Humanoiden in Reichweite. Jede Leiche wird zu einem Ghul unter deiner Kontrolle. (Der SL hat die Spielwerte für diese Kreaturen.)","Du kannst als Bonusaktion in jedem deiner Züge jede Kreatur, die du mit diesem Zauber belebt hast und die sich im Abstand von bis zu 36 Metern von dir befindet, mental befehligen. Wenn du mehrere Kreaturen kontrollierst, kannst du gleichzeitig eine oder alle befehligen, wobei jeder derselbe Befehl erteilt wird. Du entscheidest über die Aktion der Kreatur und ihre Bewegung in ihrem nächsten Zug. Alternativ kannst du einen allgemeinen Befehl erteilen, etwa das Bewachen einer bestimmten Kammer oder eines Korridors. Erteilst du keine Befehle, verteidigt sich die Kreatur lediglich gegen feindlich gesinnte Kreaturen. Sobald die Kreatur einen Befehl erhalten hat, führt sie ihn aus, bis die Aufgabe abgeschlossen ist.","Die Kreatur steht 24 Stunden lang unter deiner Kontrolle. Danach folgt sie keinem deiner Befehle mehr. Um weitere 24 Stunden die Kontrolle über die Kreatur zu behalten, musst du diesen Zauber vor dem Ablauf der ersten 24 Stunden erneut auf die Kreatur wirken. Setzt du den Zauber auf diese Weise ein, erlangst du die Kontrolle über bis zu drei Kreaturen, die du mit diesem Zauber belebt hast, anstatt eine neue zu beleben."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 7. Grades nutzt, kannst du vier Ghule beleben oder wieder unter deine Kontrolle bringen. Wirkst du diesen Zauber, indem du einen Zauberplatz des 8. Grades nutzt, kannst du fünf Ghule oder zwei Grule oder zwei Gruftschrecken beleben oder wieder unter deine Kontrolle bringen. Wirkst du diesen Zauber, indem du einen Zauberplatz des 9. Grades nutzt, kannst du sechs Ghule oder drei Grule oder drei Gruftschrecken oder zwei Mumien beleben oder wieder unter deine Kontrolle bringen."]},
  {"id":"irresistible-dance","name":"Unwiderstehlicher Tanz","en":"Irresistible Dance","level":6,"school":"enchantment","classes":["barde","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Wähle eine Kreatur in Reichweite, die du sehen kannst. Das Ziel beginnt einen komischen Tanz an Ort und Stelle: Für die Wirkungsdauer wiegt es sich, wippt mit den Füßen und springt umher. Kreaturen, die nicht bezaubert werden können, sind gegen diesen Zauber immun.","Eine tanzende Kreatur muss ihre gesamte Bewegungsrate für den Tanz verwenden, ohne ihren Bereich zu verlassen. Sie ist zudem bei Angriffs- und Rettungswürfen auf Geschicklichkeit im Nachteil. Während die Kreatur von diesem Zauber betroffen ist, sind andere Kreaturen bei Angriffswürfen gegen sie im Vorteil. Als Aktion kann eine tanzende Kreatur einen Weisheitsrettungswurf ausführen, um die Kontrolle wiederzuerlangen. Bei einem erfolgreichen Wurf endet der Zauber."]},
  {"id":"planar-ally","name":"Verbündeter aus den Ebenen","en":"Planar Ally","level":6,"school":"conjuration","classes":["kleriker"],"time":"10 Minuten","action":"long","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du bittest ein außerweltliches Wesen um Hilfe. Das Wesen muss dir sein: eine Gottheit, eine Elementarmacht, ein Dämonenprinz oder ein anderes Wesen kosmischer Macht Dieses Wesen schickt ein ihm treu ergebenes celestisches Wesen, einen Elementar oder einen Unhold, um dir zu helfen. Die Kreatur erscheint an einer freien Stelle in Reichweite. Kennst du den Namen einer bestimmten Kreatur, kannst du ihn aussprechen, wenn du diesen Zauber wirkst, um diese Kreatur zu erbitten.","Du könntest jedoch nach Wahl des SL trotzdem eine andere Kreatur erhalten.","Wenn die Kreatur erscheint, ist sie nicht gezwungen, sich auf eine bestimmte Weise zu verhalten. Du kannst sie bitten, einen Dienst gegen Bezahlung auszuführen, sie ist jedoch nicht dazu verpflichtet Die Aufgabe kann einfach oder komplex sein, von 'Fliege uns über den Abgrund!' oder 'Hilf uns im Kampf!' bis zu 'Spioniere unsere Feinde aus!' oder 'Beschützte uns, während wir in das Gewölbe vordringen!'. Du musst mit der Kreatur kommunizieren können, damit du um ihre Dienste feilschen kannst.","Die Bezahlung kann auf verschiedene Weise erfolgen. Ein celestisches Wesen verlangt möglicherweise eine beträchtliche Spende an Gold oder magischen Gegenständen, während ein Unhold ein lebendiges Opfer oder einen Schatz erwartet Einige Kreaturen bieten ihre Dienste im Gegenzug für eine Quest an, die du für sie durchführen musst.","Als Faustregel erfordert eine Aufgabe, die in Minuten gemessen wird, eine Bezahlung von 100 GM pro Minute. Eine Aufgabe, die in Stunden gemessen wird, kostet 1.000 GM pro Stunde. Eine Aufgabe, die in Tagen gemessen wird (maximal zehn Tage) erfordert 10.000 GM pro Tag. Der SL kann diese Bezahlung an die Umstände anpassen, unter denen du den Zauber wirkst. Steht die Aufgabe im Einklang mit dem Ethos der Kreatur, kann die Bezahlung halbiert werden oder sogar entfallen. Ungefährliche Aufgaben erfordern meist nur die Hälfte der genannten Bezahlung, während besonders gefährliche Aufgaben eine größere Spende benötigen. Kreaturen nehmen selten Aufgaben an, die selbstmörderisch erscheinen.","Nachdem die Kreatur den Auftrag abgeschlossen hat oder wenn die abgesprochene Dauer des Dienstes endet, kehrt die Kreatur auf ihre Heimatebene zurück, nachdem sie dir Bericht erstattet hat - sofern dies zur Aufgabe passt und möglich ist Kannst du dich mit der Kreatur nicht auf einen Preis für ihren Dienst einigen, kehrt sie sofort auf ihre Heimatebene zurück.","Eine Kreatur, die sich deiner Gruppe anschließt, zählt als Mitglied und erhält den vollen Anteil an Erfahrungspunkten."]},
  {"id":"programmed-illusion","name":"Vorbestimmtes Trugbild","en":"Programmed Illusion","level":6,"school":"illusion","classes":["barde","magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":false,"area":{"shape":"cube","size":9},"desc":["Du erschaffst eine Illusion eines Objekts, einer Kreatur oder eines anderen sichtbaren Phänomens in Reichweite, die unter einer bestimmten Bedingung aktiviert wird. Bis dahin ist die Illusion nicht wahrnehmbar. Sie darf nicht größer als ein Würfel mit neun Metern Kantenlänge sein. Beim Wirken des Zaubers bestimmst du, wie sich die Illusion verhält und welche Geräusche sie verursacht Diese vorbestimmte Darbietung kann bis zu fünf Minuten andauern.","Tritt die festgelegte Bedingung ein, entsteht die Illusion und verhält sich auf die von dir beschriebene Weise. Sobald die Illusion ihre Darbietung beendet hat, verschwindet sie und ist zehn Minuten lang inaktiv. Danach kann sie wieder aktiviert werden.","Die Auslösebedingung kann so allgemein oder detailliert sein, wie du möchtest, muss jedoch auf sichtbaren oder hörbaren Bedingungen basieren, die im Abstand von bis zu neun Metern des Bereichs auftreten. Beispielsweise könntest du eine Illusion deiner selbst erschaffen, die andere davor warnt, eine Tür mit einer Falle zu öffnen, oder die Illusion nur dann auslösen, wenn eine Kreatur ein bestimmtes Wort oder einen Satz ausspricht.","Physische Interaktionen mit dem Abbild enttarnen es als Illusion, da Dinge es einfach durchdringen können. Eine Kreatur, die ihre Aktion verwendet, um das Abbild zu untersuchen, kann einen Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG ausführen. Erkennt eine Kreatur die Illusion als solche, wird das Abbild für sie durchscheinend, und sämtliche Geräusche klingen für die Kreatur hohl."]},
  {"id":"guards-and-wards","name":"Wächter und Hüter","en":"Guards and Wards","level":6,"school":"abjuration","classes":["barde","magier"],"time":"10 Minuten","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":false,"area":{"shape":"cube","size":750},"desc":["Du erschaffst einen Schutz, der einen Bereich von bis zu 232 Quadratmetern auf dem Boden abdeckt (entweder ein Quadrat mit 15 Metern Kantenlänge oder hundert Quadrate mit 1,5 Metern Kantenlänge oder 25 Quadrate mit drei Metern Kantenlänge). Der geschützte Bereich kann bis zu sechs Meter hoch sein und eine beliebige Form haben. Du kannst mehrere Stockwerke einer Festung schützen, indem du den Bereich auf sie aufteilst, solange du jeden zusammenhängenden Bereich betreten kannst, während du den Zauber wirkst.","Wenn du diesen Zauber wirkst, kannst du Individuen festlegen, die von bestimmten oder allen Effekten deiner Wahl nicht betroffen sind. Du kannst auch ein Passwort festlegen, mit dem der Sprecher gegen diese Effekte immun ist.","Wächter und Hüter erschafft die folgenden Effekte innerhalb des geschützten Bereichs:","Korridore: Nebel füllt alle gesicherten Korridore, so dass sie komplett verschleiert sind. Außerdem besteht an jeder Kreuzung oder Abzweigung eine Chance von 50 Prozent, dass eine Kreatur außer dir selbst glaubt, in die entgegengesetzte Richtung zu gehen.","Treppen: Spinnennetze blockieren alle Treppen im geschützten Bereich von der Decke bis zum Boden, wie beim Zauber Netz. Diese Fäden wachsen innerhalb von zehn Minuten nach, wenn sie verbrannt oder zerrissen werden, solange Wächter und Hüter anhält.","Türen: Alle Türen im geschützten Bereich sind magisch verschlossen, als wären sie durch den Zauber Arkanes Schloss versiegelt. Außerdem kannst du bis zu zehn Türen mit einer Illusion verbergen, so dass sie als normale Wand erscheinen (dies entspricht einem illusionären Gegenstand des Zaubers Einfache Illusion).","Andere Zaubereffekte: Du kannst einen der folgenden magischen Effekte deiner Wahl im geschützten Bereich der Festung platzieren:","Der gesamte geschützte Bereich strahlt Magie aus. Wird Magie bannen erfolgreich auf einen bestimmten Effekt gewirkt, wird nur dieser eine Effekt entfernt.","Wenn du diesen Zauber ein Jahr lang jeden Tag an demselben Ort wirkst, kannst du eine dauerhaft geschützte Struktur erschaffen."]},
  {"id":"true-seeing","name":"Wahrer Blick","en":"True Seeing","level":6,"school":"divination","classes":["barde","kleriker","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Berührst du mit diesem Zauber eine bereitwillige Kreatur, sieht sie die Dinge so, wie sie wirklich sind. Für die Wirkungsdauer verfügt die Kreatur über Wahrer Blick, bemerkt von Magie verborgene Geheimtüren und kann bis zu einer Reichweite von 36 Metern in die Ätherebene blicken."]},
  {"id":"find-the-path","name":"Weg finden","en":"Find the Path","level":6,"school":"divination","classes":["barde","kleriker","druide"],"time":"1 Minute","action":"long","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Tag","conc":true,"ritual":false,"desc":["Dieser Zauber ermöglicht es dir, den kürzesten, direktesten physischen Weg zu einem bestimmten Ort auf derselben Existenzebene zu finden, mit dem du vertraut bist Wählst du einen Ort auf einer anderen Existenzebene, einen Ort, der sich bewegt (etwa eine bewegliche Festung) oder einen unspezifischen Ort (wie etwa 'der Hort eines grünen Drachen'), schlägt der Zauber fehl.","Während der Wirkungsdauer weißt du, wie weit der Zielort entfernt ist und in welcher Richtung er liegt, sofern du dich auf derselben Existenzebene befindest. Während du dorthin reist, ist dir an jeder Kreuzung automatisch bewusst, welcher Weg der kürzere und direktere zum Zielort ist (aber nicht unbedingt, welcher sicherer ist)."]},
  {"id":"wind-walk","name":"Windwandeln","en":"Wind Walk","level":6,"school":"transmutation","classes":["druide"],"time":"1 Minute","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":false,"desc":["Dieser Zauber verwandelt dich und bis zu zehn bereitwillige Kreaturen in Reichweite, die du sehen kannst, für die Wirkungsdauer in eine gasförmige Gestalt, die als Wolkenschwaden erscheint. In Wolkengestalt verfügt eine Kreatur über eine Flugbewegungsrate von 90 Metern und ist gegen Schaden von nichtmagischen Waffen resistent. Die einzigen Aktionen, die sie in dieser Gestalt ausführen kann, sind die Spurt-Aktion und die Rückverwandlung in ihre normale Gestalt. Die Rückverwandlung dauert eine Minute, während der die Kreatur kampfunfähig ist und sich nicht bewegen kann. Bis der Zauber endet, kann sich die Kreatur wieder in die Wolkengestalt verwandeln, was ebenfalls eine Minute dauert.","Befindet sich eine Kreatur in Wolkengestalt in der Luft, wenn der Zauber endet, sinkt sie eine Minute lang 18 Meter pro Runde hinab, bis sie sicher landet. Wenn sie nach einer Minute nicht landen kann, stürzt sie die verbleibende Entfernung."]},
  {"id":"forbiddance","name":"Zutritt verwehren","en":"Forbiddance","level":6,"school":"abjuration","classes":["kleriker"],"time":"10 Minuten","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Tag","conc":false,"ritual":true,"area":{"shape":"cube","size":12000},"desc":["Du erschaffst einen Schutz gegen magische Reisen, der einen Bereich von bis zu 3.700 Quadratmetern mit einer Höhe von bis zu neun Metern über dem Boden abdeckt. Für die Wirkungsdauer können sich Kreaturen nicht in den Bereich teleportieren oder Portale wie durch den Zauber Tor verwenden,","um in den Bereich einzudringen. Der Zauber schützt den Bereich gegen Ebenenreisen und verhindert damit, dass Kreaturen den Bereich aus der Astralebene, der Ätherebene, dem Feywild, dem Schattenfell oder mit dem Zauber Ebenenwechsel betreten.","Außerdem fügt der Zauber Kreaturentypen, die du beim Wirken bestimmst, Schaden zu. Wähle einen oder mehrere der folgenden Typen: celestische Wesen, Elementare, Feenwesen, Unholde und Untote. Wenn eine gewählte Kreatur den Bereich des Zaubers in einem Zug erstmals betritt oder ihren Zug darin beginnt, erleidet sie 5W10 gleißenden oder nekrotischen Schaden (deine Wahl beim Wirken des Zaubers).","Wenn du diesen Zauber wirkst, kannst du ein Passwort festlegen. Spricht eine Kreatur das Passwort, wenn sie den Bereich betritt, erleidet sie durch den Zauber keinen Schaden.","Der Bereich von Zutritt verwehren kann sich nicht mit dem Bereich eines anderen Zaubers derselben Art überschneiden. Wirkst du Zutritt verwehren 30 Tage lang am selben Ort, hält der Effekt an, bis er gebannt wird. Die Materialkomponenten werden beim letzten Wirken verbraucht."]},
  {"id":"mirage-arcane","name":"Arkane Spiegelung","en":"Mirage Arcane","level":7,"school":"illusion","classes":["barde","druide","magier"],"time":"10 Minuten","action":"long","range":"Sicht","rangeKind":"sight","rangeM":null,"comps":"V, G","duration":"10 Tage","conc":false,"ritual":false,"area":{"shape":"cube","size":1584},"desc":["Du lässt Gelände in einem Bereich von","1,6 Quadratkilometern wie eine andere Art von Gelände aussehen, riechen und sich sogar anfühlen. Die allgemeine Form des Geländes bleibt jedoch gleich. Weite Felder oder eine Straße können somit wie ein Sumpf, ein Hügel, eine Erdspalte oder anderes schwieriges oder unpassierbares Gelände erscheinen. Ein Tümpel kann wie eine grüne Wiese wirken, ein Abhang wie ein sanftes Gefälle oder ein mit Felsen übersäter Graben wie eine breite, flache Straße.","Gleichermaßen kannst du das Aussehen von Gebäuden ändern oder sie dort platzieren, wo es keine gibt. Der Zauber kann keine Kreaturen verändern, verbergen oder hinzufügen.","Die Illusion umfasst hörbare, visuelle, berührbare und olfaktorische Elemente, so dass sie sicheres Gelände in schwieriges verwandeln kann (und andersherum) oder anderweitig die Bewegung durch das Gebiet beeinflusst. Jedes Stück illusionäres Gelände (wie ein Fels oder ein Zweig), das aus dem Bereich des Zaubers entfernt wird, verschwindet sofort.","Kreaturen mit wahrem Blick können die Illusion durchschauen und sehen das wahre Gelände.","Alle anderen Elemente der Illusion bleiben jedoch bestehen. Selbst wenn sich die Kreatur also der Illusion bewusst ist, kann sie dennoch physisch mit ihr interagieren."]},
  {"id":"arcane-sword","name":"Arkanes Schwert","en":"Arcane Sword","level":7,"school":"evocation","classes":["barde","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"attack":"melee","damage":{"type":"force","slots":{"7":"3d10"}},"desc":["Du erschaffst eine schwertförmige Ebene aus Energie, die in Reichweite schwebt. Sie bleibt für die Wirkungsdauer bestehen.","Wenn das Schwert erscheint, kannst du einen Nahkampf-Zauberangriff gegen ein Ziel deiner Wahl im Abstand von bis zu 1,5 Metern vom Schwert ausführen. Bei einem Treffer erleidet das Ziel 3W10 Energieschaden. Bis der Zauber endet, kannst du in jedem deiner Züge eine Bonusaktion verwenden, um das Schwert bis zu sechs Meter zu einem Bereich zu bewegen, den du sehen kannst. Du kannst dann diesen Angriff gegen dasselbe oder ein anderes Ziel wiederholen."]},
  {"id":"etherealness","name":"Ätherische Gestalten","en":"Etherealness","level":7,"school":"transmutation","classes":["barde","kleriker","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Bis zu 8 Stunden","conc":false,"ritual":false,"desc":["Du betrittst die Grenzregionen der Ätherebene - dort, wo sie sich mit deiner derzeitigen Ebene überschneidet Du verbleibst während der Wirkungsdauer in der Äthergrenze, oder bis du den Zauber mit einer Aktion beendest. Währenddessen kannst du dich in jede Richtung bewegen. Wenn du dich nach oben oder unten bewegst, kostet jeder Meter einen zusätzlichen Meter an Bewegungsrate. Du kannst deine ursprüngliche Ebene sehen und hören. Sie ist jedoch monochrom und deine Sichtweite dort beträgt maximal 18 Meter.","Während du dich auf der Ätherebene befindest, kannst du nur Kreaturen beeinflussen oder von ihnen beeinflusst werden, die sich ebenfalls dort aufhalten. Kreaturen, die sich nicht auf der Ätherebene befinden, können dich nicht wahrnehmen oder mit dir interagieren, es sei denn, eine besondere Fähigkeit oder Magie erlaubt es ihnen.","Du ignorierst alle Gegenstände und Effekte, die sich nicht auf der Ätherebene befinden, und kannst dich somit durch Gegenstände bewegen, die du auf deiner ursprünglichen Ebene wahrnimmst","Wenn der Zauber endet, kehrst du sofort an der Stelle auf deine Ausgangsebene zurück, an der du dich gerade befindest. Befindest du dich am selben Ort wie ein solider Gegenstand oder eine Kreatur, wirst du augenblicklich zur nächsten freien Stelle bewegt und erleidest Energieschaden in Höhe der doppelten Anzahl an Metern, die du bewegt wurdest.","Dieser Zauber hat keinen Effekt, wenn du dich beim Wirken bereits auf der Ätherebene oder einer Ebene befindest, die nicht an sie angrenzt (beispielsweise auf den Äußeren Ebenen)."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 8. Grades oder höher nutzt, kannst du für jeden Grad über dem 7. bis zu drei bereitwillige Kreaturen (inklusive dir selbst) auswählen. Die Kreaturen müssen sich im Abstand von bis zu drei Metern von dir befinden, wenn du diesen Zauber wirkst."]},
  {"id":"resurrection","name":"Auferstehung","en":"Resurrection","level":7,"school":"necromancy","classes":["barde","kleriker"],"time":"1 Stunde","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst eine tote Kreatur. Ihr Tod darf maximal ein Jahrhundert zurückliegen und sie darf weder an Altersschwäche gestorben noch untot sein. Ist die Seele des Ziels frei und bereitwillig, wird es mit all seinen Treffer punkten wieder zum Leben erweckt.","Dieser Zauber neutralisiert sämtliche Gifte und heilt gewöhnliche Krankheiten, unter denen das Ziel zum Zeitpunkt seines Todes litt. Er hebt jedoch keine magischen Krankheiten, Flüche oder ähnlichen Effekte auf. Werden diese nicht vor dem Wirken des Zaubers gebannt, wirken sie wieder, wenn das Ziel zum Leben erweckt wird.","Dieser Zauber schließt alle tödlichen Wunden und stellt sämtliche abgetrennten Gliedmaßen wieder her.","Von den Toten aufzuerstehen ist eine Tortur.","Das Ziel erhält einen Malus von -4 auf alle Angriffs-, Attributs- und Rettungswürfe. Nach jeder langen Rast wird der Malus um 1 reduziert, bis er verschwindet.","Wirkst du diesen Zauber, um eine Kreatur zum Leben zu erwecken, die seit mindestens einem Jahr tot ist, belastet dich das stark. Du kannst erst nach einer langen Rast wieder Zauber wirken und bist bis dahin bei sämtlichen Angriffs-, Attributs- und Rettungswürfen im Nachteil."]},
  {"id":"conjure-celestial","name":"Celestisches Wesen beschwören","en":"Conjure Celestial","level":7,"school":"conjuration","classes":["kleriker"],"time":"1 Minute","action":"long","range":"27 m","rangeKind":"dist","rangeM":27,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Du beschwörst ein celestisches Wesen mit Herausforderungsgrad 4 oder niedriger, das in einem freien Bereich in Reichweite erscheint, den du sehen kannst. Das celestische Wesen verschwindet, wenn der Zauber endet oder seine Trefferpunkte auf 0 sinken.","Das celestische Wesen ist dir und deinen Gefährten für die Wirkungsdauer freundlich gesinnt. Würfle die Initiative für das celestische Wesen aus, das über seinen eigenen Zug verfügt. Es gehorcht deinen mündlichen Befehlen (erfordert keine Aktion), solange sie nicht gegen seine Gesinnung verstoßen. Wenn du dem celestischen Wesen keine Befehle erteilst, verteidigt es sich gegen feindlich gesinnte Kreaturen, führt aber anderenfalls keine Aktionen aus.","Der SL hat die Werte des celestischen Wesens."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 9. Grades nutzt, beschwörst du ein celestisches Wesen mit Herausforderungsgrad 5 oder niedriger."]},
  {"id":"plane-shift","name":"Ebenenwechsel","en":"Plane Shift","level":7,"school":"conjuration","classes":["kleriker","druide","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"attack":"melee","save":"cha","desc":["Dieser Zauber transportiert dich und bis zu acht bereitwillige Kreaturen, die sich in einem Kreis an den Händen halten, auf eine andere Existenzebene. Du kannst einen allgemeinen Zielort bestimmten, etwa die Messingstadt auf der Elementarebene des Feuers oder den Palast von Dispater auf der zweiten Ebene der Neun Höllen, und ihr erscheint dort oder in der Nähe des Ziels. Versuchst du beispielsweise, die Messingstadt zu erreichen, könntest du in ihrer Stahlstraße, vor dem Tor der Achse oder an einem Ort erscheinen, von dem aus du über das Feuermeer auf die Stadt blickst. Die Entscheidung liegt beim SL.","Kennst du die Siegelsequenz eines Kreises der Teleportation auf einer anderen Existenzebene, kann dich der Zauber zu diesem Kreis bringen. Ist der Kreis der Teleportation zu klein für alle transportieren Kreaturen, erscheinen sie an der nächsten freien Stelle neben dem Kreis.","Du kannst mit diesem Zauber eine unwillige Kreatur auf eine andere Existenzebene verbannen. Wähle eine Kreatur in Reichweite und führe einen Nahkampf-Zauberangriff aus. Bei einem Treffer muss das Ziel einen Charismarettungswurf ausführen. Scheitert der Wurf, wird es an einen zufälligen Ort auf der vor dir angegebenen Existenzebene transportiert. Eine auf diese Weise transportiere Kreatur muss ihren eigenen Weg zurück auf deine derzeitige Existenzebene finden."]},
  {"id":"forcecage","name":"Energiekäfig","en":"Forcecage","level":7,"school":"evocation","classes":["barde","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"30 m","rangeKind":"dist","rangeM":30,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"save":"cha","area":{"shape":"cube","size":6},"desc":["Ein unbewegliches, unsichtbares würfelförmiges Gefängnis aus magischer Energie bildet sich um einen Bereich deiner Wahl in Reichweite. Bei dem Gefängnis kann es sich um einen Käfig oder um eine solide Kiste handeln (deine Wahl).","Ein Gefängnis in Form eines Käfigs kann eine Seitenlänge von bis zu sechs Metern haben und besteht aus Stangen mit einem Durchmesser von einem Zentimeter mit jeweils einem Zentimeter Abstand.","Ein Gefängnis in Form einer Kiste kann eine Seitenlänge von bis zu drei Metern haben. Es handelt sich um eine solide Barriere, durch die keinerlei Materie dringen kann und die Zauber blockiert, die in den Bereich hinein oder hinaus gewirkt werden.","Wenn du den Zauber wirkst, wird jede Kreatur gefangen, die sich vollständig im Bereich des Käfigs befindet. Kreaturen, die sich nur zum Teil im Bereich befinden oder die zu groß sind, werden von der Mitte des Bereichs weggestoßen, bis sie sich vollständig außerhalb befinden.","Eine Kreatur im Energiekäfig kann diesen nur auf magische Art verlassen. Versucht eine Kreatur, den Käfig mit Teleportation oder Ebenenreisen zu verlassen, muss sie einen Charismarettungswurf ausführen. Bei einem Erfolg kann die Kreatur diese Magie nutzen, um den Käfig zu verlassen. Scheitert der Wurf, kann die Kreatur den Käfig nicht verlassen und verschwendet den Zauber oder den Effekt. Der Käfig erstreckt sich auch in die Ätherebene und blockiert damit Reisen über diese Ebene.","Dieser Zauber kann nicht durch Magie bannen aufgehoben werden."]},
  {"id":"fire-storm","name":"Feuersturm","en":"Fire Storm","level":7,"school":"evocation","classes":["kleriker","druide","zauberer"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"fire","slots":{"7":"7d10"}},"area":{"shape":"cube","size":30},"desc":["Ein Sturm aus lodernden Flammen erscheint an einem Ort deiner Wahl in Reichweite. Der Bereich des Sturms besteht aus bis zu zehn Würfeln mit drei Metern Kantenlänge, die du beliebig anordnen kannst. Jeder Würfel muss mit mindestens einer Seite an die Seite eines anderen Würfelns angrenzen. Jede Kreatur in diesem Bereich muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 7W10 Feuerschaden, anderenfalls die Hälfte.","Das Feuer verursacht Schaden bei Objekten in der Umgebung und entzündet brennbare Gegenstände, die nicht getragen oder gehalten werden. Du kannst festlegen, dass Pflanzen in der Umgebung nicht von diesem Zauber betroffen sind."]},
  {"id":"finger-of-death","name":"Finger des Todes","en":"Finger of Death","level":7,"school":"necromancy","classes":["zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","desc":["Du lässt negative Energie durch eine Kreatur in Reichweite pulsieren, die du sehen kannst, und fügst ihr extreme Schmerzen zu. Das Ziel muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet das Ziel 7W8+30 nekrotischen Schaden, anderenfalls die Hälfte.","Wird eine humanoide Kreatur durch diesen Zauber getötet, steht sie zu Beginn deines nächsten Zugs als Zombie wieder auf, der sich dauerhaft unter deiner Kontrolle befindet und deinen verbalen Befehlen nach Kräften folgt."]},
  {"id":"divine-word","name":"Göttliches Wort","en":"Divine Word","level":7,"school":"evocation","classes":["kleriker"],"time":"1 Bonusaktion","action":"bonus","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"save":"cha","desc":["Du sprichst ein göttliches Wort, das von der Macht erfüllt ist, die die Welt zu Beginn der Schöpfung geformt hat. Wähle eine beliebige Anzahl Kreaturen in Reichweite, die du sehen kannst. Jede Kreatur, die dich hören kann, muss einen Charismarettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur einen Effekt anhand ihrer aktuellen Trefferpunkte.","Unabhängig von ihren aktuellen Trefferpunkten werden celestische Wesen, Elementare, Feenwesen oder Unholde, die bei ihrem Rettungswurf scheitern, auf ihre Heimatebene verbannt (sofern sie sich nicht bereits dort befinden). Sie können 24 Stunden lang nur mit dem Zauber Wunsch auf deine derzeitige Ebene zurückkehren."]},
  {"id":"magnificent-mansion","name":"Herrliches Herrenhaus","en":"Magnificent Mansion","level":7,"school":"conjuration","classes":["barde","magier"],"time":"1 Minute","action":"long","range":"90 m","rangeKind":"dist","rangeM":90,"comps":"V, G, M","duration":"24 Stunden","conc":false,"ritual":false,"area":{"shape":"cube","size":1.5},"desc":["Du beschwörst ein extradimensionales Anwesen in Reichweite, die für die Wirkungsdauer bestehen bleibt Du entscheidest, wo sein einziger Eingang liegt. Dieser schimmert leicht und ist 1,5 Meter breit und drei Meter hoch. Du und Kreaturen, die du beim Wirken des Zaubers bestimmst, könnt das extradimensionale Anwesen betreten, solange das Portal geöffnet ist. Du kannst das Portal öffnen oder schließen, wenn du dich im Abstand von bis zu neun Metern davon befindest. Wenn das Portal geschlossen ist, ist es unsichtbar.","Hinter dem Portal befindet sich eine herrliche Eingangshalle mit zahlreichen Zimmern.","Die Atmosphäre ist sauber, frisch und warm.","Du kannst einen beliebigen Grundriss erstellen. Der Bereich darf jedoch aus maximal 50 Würfeln mit einer drei Metern Kantenlänge bestehen. Das Anwesen ist nach deinen Wünschen eingerichtet und dekoriert Es gibt ausreichend Nahrung, um ein Festmahl mit neun Gängen für bis zu 100 Personen zu servieren. 100 fast transparente Diener nehmen sich den Wünschen aller Gäste an. Du bestimmst das Aussehen dieser Diener und ihre Kleidung. Sie folgen ausnahmslos jedem deiner Befehle. Jeder Diener kann dieselben Aufgaben erfüllen wie normale menschliche Diener. Sie können jedoch nicht angreifen oder Aktionen ausführen, die einer anderen Kreatur direkt Schaden zufügen würde. Die Diener können Gegenstände holen und reinigen, Kleidung Zusammenlegen, Feuer entzünden, Essen servieren, Wein einschenken und dergleichen. Sie können sich im Anwesen frei bewegen, es jedoch nicht verlassen. Möbel und andere Gegenstände, die durch diesen Zauber erschaffen wurden, lösen sich in Rauch auf, wenn sie aus dem Anwesen entfernt werden. Wenn der Zauber endet, werden alle Kreaturen im Innern des extradimensionalen Bereichs in einen freien Bereich ausgestoßen, der dem Eingang am nächsten liegt."]},
  {"id":"prismatic-spray","name":"Regenbogenspiel","en":"Prismatic Spray","level":7,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Kegel von 18 m)","rangeKind":"self","rangeM":0,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","area":{"shape":"cone","size":18},"desc":["Acht bunte Lichtstrahlen schießen aus deiner Hand. Jeder Strahl leuchtet in einer anderen Farbe und besitzt eine andere Macht und einen anderen Zweck. Kreaturen innerhalb eines Kegels von 18 Metern müssen einen Geschicklichkeitsrettungswurf ausführen. Würfle für jedes Ziel mit einem W8, um die Farbe zu bestimmen, die es trifft."]},
  {"id":"regenerate","name":"Regeneration","en":"Regenerate","level":7,"school":"transmutation","classes":["barde","kleriker","druide"],"time":"1 Minute","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"1 Stunde","conc":false,"ritual":false,"heal":{"slots":{"7":"4d8 + 15"}},"desc":["Du berührst eine Kreatur und regst ihre natürliche Heilung an. Das Ziel gewinnt 4W8+15 Trefferpunkte zurück. Für die Wirkungsdauer erhält das Ziel zudem zu Beginn jedes seiner Züge 1 Trefferpunkt zurück (10 Trefferpunkte pro Minute),","Eventuelle abgetrennte Gliedmaßen des Ziels (Finger, Beine, Schweif und dergleichen) werden nach zwei Minuten wiederhergestellt. Hältst du eine abgetrennte Gliedmaße an den Stumpf, lässt der Zauber sie sofort wieder anwachsen."]},
  {"id":"reverse-gravity","name":"Schwerkraft umkehren","en":"Reverse Gravity","level":7,"school":"transmutation","classes":["druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"30 m","rangeKind":"dist","rangeM":30,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"dex","area":{"shape":"cylinder","size":15},"desc":["Dieser Zauber kehrt die Schwerkraft in einem 30 Meter hohen Zylinder mit einem Radius von 15 Metern um, der auf einen Punkt in Reichweite zentriert ist. Wenn du diesen Zauber wirkst, fallen alle Kreaturen und Gegenstände, die nicht mit dem Boden im Bereich verankert sind, nach oben bis zur Oberseite des Zylinders. Eine Kreatur kann einen Geschicklichkeitsrettungswurf ausführen, um sich an einem verankerten Gegenstand in Reichweite festzuhalten und somit den Fall verhindern.","Wenn ein solider Gegenstand (wie eine Decke) bei dem umgekehrten Sturz im Weg ist, treffen fallende Gegenstände und Kreaturen diesen wie bei einem normalen Sturz. Erreicht ein Gegenstand oder eine Kreatur die Oberseite des Zylinders, ohne etwas zu treffen, bleibt das Ziel dort und hängt für die Wirkungsdauer schwingend in der Luft.","Am Ende der Wirkungsdauer fallen betroffene Gegenstände und Kreaturen wieder herunter."]},
  {"id":"simulacrum","name":"Simulakrum","en":"Simulacrum","level":7,"school":"illusion","classes":["magier"],"time":"12 Stunden","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":false,"desc":["Du erschaffst ein illusionäres Duplikat eines Tiers oder einer humanoiden Kreatur. Sie muss sich für die gesamte Zeit, während du den Zauber wirkst, in Reichweite befinden. Beim Duplikat handelt sich um eine teilweise reale Kreatur, die aus Eis oder Schnee geformt wurde. Sie kann Aktionen ausführen und wie eine normale Kreatur beeinflusst werden. Es erscheint identisch zum Original, verfügt jedoch nur über die Hälfte des Trefferpunktemaximums der Kreatur und wird ohne Ausrüstung erschaffen. Ansonsten verwendet die Illusion alle Spielwerte der duplizierten Kreatur.","Das Simulakrum ist dir und allen von dir bestimmten Kreaturen freundlich gesinnt Es befolgt deine verbalen Befehle, bewegt sich und handelt nach deinen Wünschen und agiert im Kampf in deinem Zug. Das Simulakrum kann nicht dazulernen oder mächtiger werden. Es erlangt also niemals eine neue Stufe oder andere Fähigkeiten, noch kann es verbrauchte Zauberplätze zurückerhalten.","Wird das Simulakrum beschädigt, kannst du es in einem Alchemielabor reparieren, indem du seltene Kräuter und Mineralien im Wert von 100 GM pro wiederhergestelltem Trefferpunkt verwendest.","Das Simulakrum bleibt bestehen, bis seine Trefferpunkte auf 0 sinken. Dann wird es zu Schnee und schmilzt.","Wirkst du diesen Zauber erneut, werden alle aktiven Duplikate, die du mit diesem Zauber erschaffen hast, sofort zerstört."]},
  {"id":"delayed-blast-fireball","name":"Spätzündender Feuerball","en":"Delayed Blast Fireball","level":7,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"dex","area":{"shape":"sphere","size":6},"desc":["Ein gelber Lichtstrahl schießt aus deinem deutenden Finger, verdichtet sich an einem Punkt deiner Wahl in Reichweite zu einer leuchtenden Perle und verweilt dort für die Wirkungsdauer. Wenn der Zauber endet (entweder, weil deine Konzentration unterbrochen wird oder du ihn willentlich beendest), wird die Perle mit einem dumpfen Grollen zu einer lodernden Flammenexplosion, die sich um Ecken ausbreitet. Jede Kreatur in einer Sphäre mit einem Radius von sechs Metern um diesen Punkt muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur Feuerschaden in Höhe des gesamten angesammelten Schadens, anderenfalls die Hälfte.","Der Grundschaden des Zaubers beträgt 12W6. Wenn die Perle am Ende deines Zugs noch nicht detoniert ist, erhöht sich der Schaden um 1W6.","Berührt eine Kreatur die leuchtende Perle, bevor die Zeitspanne abgelaufen ist, muss die Kreatur einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, endet der Zauber sofort und die Perle explodiert. Bei einem erfolgreichen Rettungswurf kann die Kreatur die Perle bis zu zwölf Meter weit werfen. Trifft sie eine Kreatur oder einen soliden Gegenstand, endet der Zauber und die Perle explodiert.","Das Feuer verursacht Schaden bei Objekten in der Umgebung und entzündet brennbare Gegenstände, die nicht getragen oder gehalten werden."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 8. Grades oder höher nutzt, steigt der Schaden für jeden Grad über dem 7. um 1W6."]},
  {"id":"symbol","name":"Symbol","en":"Symbol","level":7,"school":"abjuration","classes":["barde","kleriker","magier"],"time":"1 Minute","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Bis der Zauber gebannt oder ausgelöst wird","conc":false,"ritual":false,"save":"cha","damage":{"type":"necrotic","slots":{"7":"10d10"}},"area":{"shape":"cube","size":3},"desc":["Wenn du diesen Zauber wirkst, zeichnest du eine schädliche Glyphe auf eine Oberfläche (wie einem Tisch, dem Fußboden oder einer Wand) oder in einen Gegenstand, der verschlossen werden kann, um die Glyphe zu verbergen (wie ein Buch, eine Schriftrolle oder eine Schatztruhe). Wählst du eine Oberfläche, kann die Glyphe einen Bereich mit einem Radius von maximal drei Metern abdecken. Wählst du einen Gegenstand, muss dieser an seinem Standort bleiben. Wird er mehr als drei Meter von dem Ort entfernt, an dem du den Zauber gewirkt hast, wird die Glyphe zerstört und der Zauber endet, ohne ausgelöst zu werden.","Die Glyphe ist nahezu unsichtbar. Es wird ein erfolgreicher Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG benötigt, um sie zu entdecken.","Wenn du den Zauber wirkst, entscheidest du, was die Glyphe auslöst. Glyphen auf Oberflächen werden meist dadurch ausgelöst, dass jemand sie berührt oder darauf steht, einen Gegenstand bewegt, der die Glyphe verdeckt, sich der Glyphe auf eine bestimmte Entfernung nähert oder mit dem Gegenstand interagiert, in den die Glyphe geschrieben wurde. Glyphen auf Gegenständen werden meist dadurch ausgelöst, dass jemand den Gegenstand öffnet, sich ihm auf eine bestimmte Entfernung nähert oder die Glyphe sieht oder liest.","Du kannst die Auslösebedingung des Zaubers weiter verfeinern, so dass der Zauber nur bei bestimmten Umständen oder körperlichen Eigenschaften einer Kreatur (wie Größe oder Gewicht) oder bestimmten Typen ausgelöst wird. Der Zauber könnte beispielsweise nur Vetteln oder Gestaltwandler betreffen. Du kannst auch Kreaturen festlegen, die die Glyphe nicht auslösen, beispielsweise wenn sie ein bestimmtes Passwort aussprechen.","Wähle beim Schreiben der Glyphe eine der folgenden Optionen als Effekt. Sobald sie ausgelöst wurde, leuchtet die Glyphe und erfüllt eine Sphäre mit einem Radius von 18 Metern zehn Minuten lang mit dämmrigem Licht. Danach endet der Zauber. Jede Kreatur, die sich beim Aktivieren der Glyphe in der Sphäre befindet, diese das erste Mal in einem Zug betritt oder ihren Zug dort beendet, wird Ziel des vorher festgelegten Effekts.","Betäubung: Jedes Ziel muss einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, wird es eine Minute lang betäubt.","Furcht: Jedes Ziel muss einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, ist es eine Minute lang verängstigt Während es verängstigt ist, lässt das Ziel fallen, was es gerade hält, und muss sich in jedem seiner Züge mindestens neun Meter von der Glyphe entfernen, sofern dies möglich ist.","Hoffnungslosigkeit: Jedes Ziel muss einen Charismarettungswurf ausführen. Scheitert der Wurf, wird das Ziel eine Minute lang von Verzweiflung überwältigt. Während dieser Zeit kann es weder angreifen noch Kreaturen als Ziel für schädigende Fähigkeiten, Zauber oder andere magische Effekte wählen.","Schlaf: Jedes Ziel muss einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, wird es zehn Minuten lang bewusstlos. Eine Kreatur erwacht, wenn sie Schaden erleidet oder jemand eine Aktion verwendet, um sie zu schütteln oder zu ohrfeigen.","Schmerz: Jedes Ziel muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, wird es eine Minute lang von schrecklichen Schmerzen geplagt und kampfunfähig.","Tod: Jedes Ziel muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet das Ziel 10W10 nekrotischen Schaden, anderenfalls die Hälfte.","Wahnsinn: Jedes Ziel muss einen Intelligenzrettungswurf ausführen. Scheitert der Wurf, verfällt das Ziel eine Minute lang dem Wahnsinn. Eine wahnsinnige Kreatur kann keine Aktionen ausführen, versteht nicht, was andere Kreaturen sagen, kann nicht lesen und sich nicht verständlich ausdrücken. Der SL kontrolliert ihre Bewegungen, die unberechenbar sind.","Zwietracht: Jedes Ziel muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, streitet sich das Ziel eine Minute lang mit anderen Kreaturen. Während dieser Zeit ist es nicht zu sinnvollen Gesprächen in der Lange und ist bei Angriffs- und Attributswürfen im Nachteil."]},
  {"id":"teleport","name":"Teleportieren","en":"Teleport","level":7,"school":"conjuration","classes":["barde","zauberer","magier"],"time":"1 Aktion","action":"action","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"damage":{"type":"force","slots":{"7":"3d10"}},"area":{"shape":"cube","size":3},"desc":["Dieser Zauber transportiert dich und bis zu acht bereitwillige Kreaturen deiner Wahl in Reichweite, die du sehen kannst, sofort zu einem von dir ausgewählten Ort. Du kannst auch einen einzelnen Gegenstand in Reichweite, den du sehen kannst, teleportieren. In diesem Fall muss der Gegenstand in einen Würfel mit drei Metern Kantenlänge passen und kann nicht von einer unwilligen Kreatur gehalten oder getragen werden.","Der von dir ausgewählte Zielort muss dir bekannt sein und sich auf derselben Existenzebene wie du befinden. Deine Vertrautheit mit dem Zielort bestimmt, ob du dort erfolgreich eintriffst. Der SL würfelt anhand der folgenden Tabelle mit einem W100.","Vertrautheit: Mit 'dauerhafter Kreis' ist ein dauerhafter Kreis der Teleportation gemeint, dessen Siegelsequenz dir bekannt ist. 'Zugehöriger Gegenstand' bedeutet, dass du einen Gegenstand besitzt, der innerhalb der letzten sechs Monate vom gewünschten Zielort entfernt wurde, etwa ein Buch aus dem Archiv eines Magiers, Bettlaken aus einer königlichen Kammer oder ein Stück Marmor aus der geheimen Gruft eines Lichs.","'Sehr vertraut' beschreibt einen Ort, an dem du oft gewesen bist, den du genau studiert hast oder den du beim Wirken des Zaubers sehen kannst. 'Beiläufig gesehen' beschreibt einen Ort, den du mehr als einmal gesehen hast, mit dem du jedoch nicht sehr vertraut bist. 'Einmal gesehen' beschreibt einen Ort, den du einmal gesehen hast, wahrscheinlich durch Magie. 'Beschreibung' bezieht sich auf einen Ort, dessen Position und Aussehen dir durch eine Beschreibung bekannt sind, etwa durch eine Karte.","'Falscher Zielort' bedeutet, dass ein Ort nicht existiert. Vielleicht hast du versucht, das Heiligtum eines Feindes magisch auszuspähen, konntest jedoch nur eine Illusion sehen. Oder du versuchst, dich an einen vertrauten Ort zu teleportieren, der nicht mehr existiert.","Am Zielort: Du und deine Gruppe (oder der Zielgegenstand) erscheint dort, wo du willst.","Abseits des Zielorts: Du und deine Gruppe (oder der Zielgegenstand) erscheint in einer zufälligen Entfernung und in einer zufälligen Richtung abseits des Zielorts. Die Entfernung vom Ziel beträgt 1W10 x 1W10 Prozent der Entfernung, die teleportiert werden sollte. Beispiel: Du versuchst, 190 Kilometer weit zu reisen und landest abseits des Zielorts. Du würfelst eine 5 und eine 3 mit den beiden W10. Daher befindest du dich 15 Prozent abseits des Ziels, also 28 Kilometer. Der SL bestimmt zufällig die Richtung, in der du vom Zielort entfernt landest, indem er einen W8 würfelt und 1 als Norden, 2 als Nordosten, 3 als Osten und so weiter bestimmt Teleportierst du dich zu einer Küstenstadt und landest 28 Kilometer weit im Meer, könntest du in Schwierigkeiten sein.","Ähnliches Gebiet: Du und deine Gruppe (oder der Zielgegenstand) erscheint in einem anderen Gebiet, das dem Zielort visuell oder thematisch ähnlich ist. Wolltest du dich beispielsweise in dein heimisches Labor teleportieren, landest du vielleicht im Labor eines anderen Magiers oder in einem Alchemieladen, der über viele ähnliche Geräte wie dein Labor verfügt. Grundsätzlich erscheinst du am nächstgelegenen ähnlichen Ort. Da der Zauber jedoch keine Reichweitenbegrenzung besitzt, kannst du theoretisch überall auf der Ebene landen.","Unglück: Die unvorhersehbare Magie des Zaubers führt zu einer holprigen Reise. Jede teleportierte Kreatur (oder der Zielgegenstand) erleidet 3W10 Energieschaden. Zudem würfelt der SL anhand der Tabelle, um zu bestimmen, wo du landest. Es kann zu mehreren Unglücken kommen, die jedes Mal Schaden verursachen."]},
  {"id":"project-image","name":"Trugbild projizieren","en":"Project Image","level":7,"school":"illusion","classes":["barde","magier"],"time":"1 Aktion","action":"action","range":"800 km","rangeKind":"dist","rangeM":800000,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Tag","conc":true,"ritual":false,"desc":["Du erschaffst ein illusionäres Abbild von dir selbst, das für die Wirkungsdauer bestehen bleibt. Das Abbild kann an einem beliebigen Ort in Reichweite erscheinen, den du schon einmal gesehen hast, unabhängig von dazwischenliegenden Hindernissen. Die Illusion sieht aus und klingt wie du, ist aber immateriell. Erleidet die Illusion Schaden, verschwindet sie und der Zauber endet","Als Aktion kannst du diese Illusion bis zu deiner doppelten Bewegungsrate bewegen und sie gestikulieren, sprechen und auf eine beliebige Art handeln lassen. Sie ahmt dein Verhalten perfekt nach.","Du kannst durch ihre Augen sehen und durch ihre Ohren hören, als befändest du dich am selben Ort. In jedem deiner Züge kannst du als Bonusaktion von den Sinnen der Illusion zu deinen eigenen wechseln, und wieder zurück. Während du seine Sinne benutzt, bist du in deiner eigenen Umgebung blind und taub.","Physische Interaktionen mit dem Abbild enttarnen es als Illusion, da Dinge es einfach durchdringen können. Eine Kreatur, die ihre Aktion verwendet, um das Abbild zu untersuchen, kann einen Intelligenzwurf (Nachforschungen) gegen deinen Zauberrettungswurf-SG ausführen. Erkennt eine Kreatur die Illusion als solche, wird das Abbild für sie durchscheinend, und sämtliche Geräusche klingen für die Kreatur hohl."]},
  {"id":"sequester","name":"Verbergen","en":"Sequester","level":7,"school":"transmutation","classes":["magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":false,"desc":["Mit diesem Zauber kannst du eine bereitwillige Kreatur oder einen Gegenstand verbergen. Das Ziel kann für die Wirkungsdauer nicht entdeckt werden. Wenn du den Zauber wirkst und das Ziel berührst, wird es unsichtbar und kann weder von Erkenntniszaubern aufgespürt noch durch Ausspähungssensoren von Erkenntniszaubern wahrgenommen werden.","Handelt es sich bei dem Ziel um eine Kreatur, fällt es in einen scheintoten Zustand. Für das Ziel stoppt die Zeit und es altert nicht.","Du kannst eine Bedingung festlegen, durch die der Zauber vorzeitig endet. Dabei hast du freie Wahl, solange die Bedingung im Abstand von bis zu 1,6 Kilometern um das Ziel auftritt oder sichtbar ist. Beispiele dafür wären 'nach 1.000 Jahren' oder 'wenn die Tarraske erwacht'. Dieser Zauber endet auch, wenn das Ziel Schaden erleidet."]},
  {"id":"antimagic-field","name":"Antimagisches Feld","en":"Antimagic Field","level":8,"school":"abjuration","classes":["kleriker","magier"],"time":"1 Aktion","action":"action","range":"Selbst (Sphäre mit 3 m Radius)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"area":{"shape":"sphere","size":3},"desc":["Eine unsichtbare Sphäre aus Antimagie mit einem Radius von 3 Metern umgibt dich. Dieser Bereich ist von der magischen Energie abgeschnitten, die das Multiversum erfüllt. Innerhalb der Sphäre können keine Zauber gewirkt werden, beschworene Kreaturen verschwinden und magische Gegenstände werden zu gewöhnlichen. Bis der Zauber endet, bewegt sich die Sphäre mit dir im Zentrum fort.","Zauber und andere magische Effekte (außer solche durch Artefakte oder Gottheiten) werden von der Sphäre unterdrückt, die für sie undurchdringlich ist Ein Zauberplatz, der zum Wirken eines unterdrückten Zaubers verwendet wird, gilt als verbraucht. Solange ein Effekt unterdrückt wird, wirkt er nicht, doch die Zeit, in der er unterdrückt wird, wird von seiner Dauer abgezogen.","Gezielte Effekte: Zauber und andere magische Effekte wie Magisches Geschoss und Person bezaubern, die auf eine Kreatur oder einen Gegenstand in der Sphäre abzielen, haben keinen Effekt.","Magische Flächeneffekte: Der Flächeneffekt eines anderen Zaubers oder magischen Effekts wie eines Feuerballs kann nicht in die Sphäre eindringen. Wenn die Sphäre einen magischen Flächeneffekt überschneidet, wird der Bereich in der Sphäre unterdrückt. Beispiel: Die Flammen einer Feuerwand werden innerhalb der Sphäre unterdrückt, sodass bei ausreichender Überschneidung eine Lücke in der Wand entsteht.","Zauber: Alle aktiven Zauber oder anderen magischen Effekte, die eine Kreatur oder einen Gegenstand in der Sphäre beeinflussen, werden unterdrückt, solange sich die Kreatur oder der Gegenstand darin befinden.","Magische Gegenstände: Die Eigenschaften und Kräfte magischer Gegenstände werden in der Sphäre unterdrückt. Beispiel: Ein Langschwert+1 ist in der Sphäre ein nichtmagisches Langschwert.","Die Eigenschaften und Kräfte magischer Waffen werden unterdrückt, wenn sie gegen ein Ziel in der Sphäre gerichtet oder von einem Angreifer in der Sphäre geführt werden. Verlässt eine magische Waffe oder ein magisches Geschoss die Sphäre vollständig (beispielsweise, wenn du mit einem magischen Pfeil oder einem magischen Speer ein Ziel außerhalb der Sphäre anvisierst), wird die Magie des Gegenstands nicht mehr unterdrückt, sobald er die Sphäre verlässt.","Magisches Reisen: Teleportation und Ebenenreisen funktionieren in der Sphäre nicht. Dabei spielt es keine Rolle, ob die Sphäre der Zielort oder der Startpunkt der magischen Reise darstellt. Ein Portal zu einem anderen Ort, einer anderen Welt oder einer anderen Existenzebene, sowie Öffnungen in den extradimensionalen Raum, wie beispielsweise durch den Zauber Seiltrick, schließen sich vorübergehend in der Sphäre.","Kreaturen und Objekte: Kreaturen oder Gegenstände, die mit Magie beschworen oder erschaffen wurden, existieren in der Sphäre vorübergehend nicht mehr. Kreaturen erscheinen sofort wieder, sobald der Bereich, in dem sie sich zuletzt befanden, nicht mehr innerhalb der Sphäre liegt","Magie bannen: Zauber und magische Effekte wie Magie bannen haben keine Auswirkungen auf die Sphäre. Ebenso heben sich Sphären nicht gegenseitig auf, die von verschiedenen Antimagisches Feld erschaffen wurden."]},
  {"id":"antipathy-sympathy","name":"Antipathie/Sympathie","en":"Antipathy/Sympathy","level":8,"school":"enchantment","classes":["druide","magier"],"time":"1 Stunde","action":"long","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"10 Tage","conc":false,"ritual":false,"area":{"shape":"cube","size":60},"desc":["Dieser Zauber zieht Kreaturen deiner Wahl an oder wehrt sie ab. Wähle als Ziel einen Gegenstand oder eine Kreatur in Reichweite, der oder die höchstens riesig sein darf, oder einen Bereich, der nicht größer als ein Würfel mit 60 Metern Kantenlänge ist. Bestimme dann eine Art von intelligenter Kreatur, wie rote Drachen, Goblins oder Vampire. Du erfüllst das Ziel mit einer Aura, die die gewählten Kreaturen für die Wirkungsdauer entweder anzieht oder abwehrt Wähle Antipathie oder Sympathie für den Effekt der Aura.","Antipathie: Die Verzauberung bewirkt, dass Kreaturen der von dir bestimmten Art den starken Drang verspüren, den Bereich zu verlassen und das Ziel zu meiden. Wenn eine derartige Kreatur das Ziel sehen kann oder sich ihm auf 18 Meter nähert, muss die Kreatur einen Weisheitsrettungswurf bestehen, oder sie wird verängstigt. Die Kreatur bleibt verängstigt, während sie das Ziel sehen kann oder sich im Abstand von bis zu 18 Metern von ihm befindet. Solange sie verängstigt ist, muss die Kreatur ihre Bewegungsrate verwenden, um sich zum nächsten sicheren Ort zu begeben, an dem sie das Ziel nicht sehen kann. Wenn die Kreatur mehr als 18 Meter vom Ziel entfernt ist und es nicht sehen kann, ist sie nicht mehr verängstigt. Sie erhält den Zustand jedoch erneut, wenn sie das Ziel wieder sehen kann oder sich ihm auf 18 Meter nähert.","Sympathie: Die Verzauberung bewirkt, dass Kreaturen der von dir bestimmten Art den starken Drang verspüren, sich dem Ziel zu nähern, während sie sich 18 Meter davon entfernt befinden oder es sehen können. Wenn eine derartige Kreatur das Ziel sehen kann oder sich ihm auf 18 Meter nähert, muss die Kreatur einen Weisheitsrettungswurf bestehen, oder ihre Bewegungsrate in jedem ihrer Züge verwenden, um den Bereich zu betreten oder sich in Reichweite des Ziels zu begeben. Wenn die Kreatur dies getan hat, kann sie sich nicht willentlich vom Ziel entfernen.","Wenn das Ziel eine beeinflusste Kreatur verletzt oder ihr anderweitig schadet, kann diese einen Weisheitsrettungswurf ausführen, um den Effekt wie unten beschrieben zu beenden.","Den Effekt beenden: Beendet eine betroffene Kreatur ihren Zug mehr als 18 Meter vom Ziel entfernt oder kann es nicht sehen, führt die Kreatur einen Weisheitsrettungswurf aus. Bei einem erfolgreichen Rettungswurf ist die Kreatur nicht länger vom Effekt des Ziels betroffen und erkennt, dass das Gefühl der Anziehung oder Abneigung magischer Natur ist. Außerdem darf eine Kreatur, während sie von dem Zauber betroffen ist, alle 24 Stunden einen weiteren Weisheitsrettungswurf ausführen.","Bei einem erfolgreichen Rettungswurf ist die Kreatur eine Minute lang gegen diesen Effekt immun. Danach kann er wieder in Kraft treten."]},
  {"id":"earthquake","name":"Erdbeben","en":"Earthquake","level":8,"school":"evocation","classes":["kleriker","druide","zauberer"],"time":"1 Aktion","action":"action","range":"150 m","rangeKind":"dist","rangeM":150,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"damage":{"type":"bludgeoning","slots":{"8":"5d6"}},"area":{"shape":"sphere","size":30},"desc":["Du erschaffst eine seismische Störung an einem Punkt auf dem Boden in Reichweite, den du sehen kannst. Für die Wirkungsdauer reißt ein gewaltiges Beben die Erde in einem Radius von 30 Metern um diesen Punkt auf und erschüttert Kreaturen und Strukturen auf dem Boden in diesem Bereich.","Der Bereich wird zu schwierigem Gelände. Jede Kreatur auf dem Boden, die Konzentration aufrechterhält, muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, wird die Konzentration der Kreatur unterbrochen.","Wenn du diesen Zauber wirkst, sowie am Ende jedes Zugs, in dem du dich darauf konzentrierst, muss jede Kreatur auf dem Boden in dem Bereich einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, wird die Kreatur umgestoßen.","Dieser Zauber kann nach Wahl des SL zusätzliche Auswirkungen abhängig vom Gelände haben.","Erdspalten: Erdspalten öffnen sich zu Beginn deines nächsten Zugs im Bereich des Zaubers. Insgesamt öffnen sich 1W6 Erdspalten an Orten, die der SL bestimmt. Jede ist 1W10 mal drei Meter tief, drei Meter breit und verläuft von einer Seite des Wirkungsbereichs zum anderen. Eine Kreatur, die dort steht, wo sich eine Erdspalte öffnet, muss einen Geschicklichkeitsrettungswurfbestehen, oder sie fällt hinein. Ist der Rettungswurf erfolgreich, bewegt sich die Kreatur mit dem Rand der Erdspalte, während sich diese öffnet.","Öffnet sich eine Erdspalte unter einem Gebäude, stürzt dieses automatisch ein (siehe unten).","Gebäude: Wenn du den Zauber wirkst, sowie zu Beginn jedes deiner Züge, bis der Zauber endet, fügt das Beben allen Gebäuden, die den Boden im Wirkungsbereich berühren, 50 Wuchtschaden zu. Wird ein Gebäude auf 0 Trefferpunkte reduziert, stürzt es ein und fügt möglicherweise Kreaturen in der Nähe Schaden zu. Eine Kreatur innerhalb der halben Entfernung der Höhe des Gebäudes muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 5W6 Wuchtschaden, wird umgestoßen und ist in den Trümmern gefangen. Als Aktion muss sie einen SG-20-Stärkewurf (Athletik) bestehen, um sich zu befreien. Der SL kann den SG je nach Art der Trümmer erhöhen oder verringern. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur halb so viel Schaden und wird nicht umgestoßen oder begraben."]},
  {"id":"incendiary-cloud","name":"Flammende Wolke","en":"Incendiary Cloud","level":8,"school":"conjuration","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"dex","damage":{"type":"fire","slots":{"8":"10d8"}},"area":{"shape":"sphere","size":6},"desc":["Eine wirbelnde Rauchwolke, die von weißer Glut durchzogen ist, erscheint in einer Sphäre mit einem Radius von sechs Metern, die auf einem Punkt in Reichweite zentriert ist. Die Wolke breitet sich um Ecken aus und ist komplett verschleiert. Sie bleibt für die Wirkungsdauer bestehen oder bis ein mäßiger oder stärkerer Wind (mindestens 16 Kilometer pro Stunde) den Nebel auflöst.","Wenn die Wolke erscheint, muss jede Kreatur in diesem Bereich einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 10W8 Feuerschaden, anderenfalls die Hälfte. Wenn eine Kreatur den Bereich des Zaubers in einem Zug erstmals betritt oder ihren Zug darin beendet, muss sie diesen Rettungswurf ebenfalls ausführen.","Zu Beginn jedes deiner Züge bewegt sich die Wolke drei Meter in eine Richtung deiner Wahl direkt von dir weg."]},
  {"id":"mind-blank","name":"Gedankenleere","en":"Mind Blank","level":8,"school":"abjuration","classes":["barde","magier"],"time":"1 Aktion","action":"action","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G","duration":"24 Stunden","conc":false,"ritual":false,"desc":["Bis der Zauber endet, ist eine bereitwillige Kreatur, die du berührst, gegen psychischen Schaden, Effekte, die ihre Gefühle oder Gedanken lesen würden, Erkenntniszauber und den Bezaubert-Zustand immun. Dieser Zauber verhindert sogar den Zauber Wunsch sowie ähnliche Zauber oder Effekte, die den Verstand des Ziels beeinflussen oder die Informationen über das Ziel offenbaren."]},
  {"id":"demiplane","name":"Halbebene","en":"Demiplane","level":8,"school":"conjuration","classes":["hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"G","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Du erschaffst eine schattenhafte Tür auf einer soliden Oberfläche in Reichweite, die du sehen kannst. Die Tür ist groß genug, dass mittelgroße Kreaturen problemlos hindurchpassen. Wird sie geöffnet, führt die Tür zu einer Halbebene, die als leerer Raum mit neun Metern Kantenlänge erscheint und aus Holz oder Stein besteht. Wenn der Zauber endet, verschwindet die Tür und Kreaturen oder Gegenstände in der Halbebene bleiben dort gefangen, da die Tür auf der anderen Seite ebenfalls verschwindet.","Jedes Mal, wenn du diesen Zauber wirkst, kannst du eine neue Halbebene erschaffen oder die schattenhafte Tür mit einer Halbebene verbinden, die du beim vorherigen Wirken des Zaubers erschaffen hast. Ist dir außerdem die Natur und der Inhalt einer Halbebene bekannt, die durch diesen Zauber von einer anderen Kreatur erschaffen wurde, kannst du die schattenhafte Tür stattdessen auch mit dieser Halbebene verbinden."]},
  {"id":"holy-aura","name":"Heilige Aura","en":"Holy Aura","level":8,"school":"abjuration","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"area":{"shape":"sphere","size":9},"desc":["Göttliches Licht breitet sich von dir aus und wird in einem Radius von neun Metern um dich herum zu einem sanften Strahlen. Kreaturen deiner Wahl, die sich im Radius befinden, wenn du den Zauber wirkst, strahlen in einem Radius von 1,5 Metern dämmriges Licht aus und sind bei allen Rettungswürfen im Vorteil. Bis der Zauber endet, sind andere Kreaturen zudem bei Angriffswürfen gegen sie im Nachteil. Trifft ein Unhold oder ein Untoter eine betroffene Kreatur mit einem Nahkampfangriff, blitzt die Aura hell auf. Der Angreifer muss einen Konstitutionsrettungswurf bestehen, oder er ist blind, bis der Zauber endet."]},
  {"id":"maze","name":"Irrgarten","en":"Maze","level":8,"school":"conjuration","classes":["magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Konzentration, bis zu 10 Minuten","conc":true,"ritual":false,"desc":["Du verbannst eine Kreatur in Reichweite, die du sehen kannst, auf eine labyrinthartige Halbebene. Das Ziel bleibt bis zur Wirkungsdauer dort - oder bis es dem Irrgarten entkommt.","Das Ziel kann seine Aktion verwenden, um eine Flucht zu versuchen. Dazu muss es einen SG-20-Intelligenzwurf ausführen. Bei einem Erfolg entkommt es und der Zauber endet. Ein Minotaurus oder Goristro-Dämon hat automatisch Erfolg.","Wenn der Zauber endet, erscheint das Ziel wieder an der Stelle, von der es wegteleportiert wurde, oder an der nächstgelegenen freien Stelle, falls dieser Ort besetzt ist."]},
  {"id":"clone","name":"Klon","en":"Clone","level":8,"school":"necromancy","classes":["magier"],"time":"1 Stunde","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Dieser Zauber erschafft ein bewegungsloses Duplikat einer lebenden Kreatur als Schutz vor ihrem Tod. Der Klon wächst in 12 0 Tagen in einem versiegelten Gefäß zu voller Größe und Reife heran. Du kannst auch einen Klon als jüngere Version derselben Kreatur erschaffen. Er bleibt bewegungslos und überlebt unendlich lange, solange das Gefäß nicht geöffnet wird.","Stirbt die ursprüngliche Kreatur, nachdem der Klon herangereift ist, wird ihre Seele auf den Klon übertragen, sofern die Seele frei und willig ist, zurückzukehren. Der Klon ist körperlich mit dem Original identisch und besitzt dieselbe Persönlichkeit sowie dieselben Erinnerungen und Fähigkeiten, aber keine Ausrüstung des Originals. Wenn die körperlichen Überreste der ursprünglichen Kreatur noch existieren, werden sie reglos und können danach nicht mehr zum Leben erweckt werden, da sich die Seele der Kreatur an einem anderen Ort befindet."]},
  {"id":"dominate-monster","name":"Monster beherrschen","en":"Dominate Monster","level":8,"school":"enchantment","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"save":"wis","desc":["Du versuchst, eine Kreatur in Reichweite zu betören, die du sehen kannst Sie muss einen Weisheitsrettungswurf bestehen oder sie wird für die Wirkungsdauer von dir bezaubert Wenn du oder deine Verbündeten gegen die Kreatur kämpfen, ist sie beim Rettungswurf im Vorteil.","Während die Kreatur bezaubert ist und ihr euch auf derselben Existenzebene aufhaltet, verfügst du über eine telepathische Verbindung mit ihr. Diese kannst du verwenden, um der Kreatur Befehle zu erteilen, solange du bei Bewusstsein bist (erfordert keine Aktion), Die Kreatur befolgt diese nach Kräften. Du kannst eine einfache, allgemeine Aktion angeben, wie 'Greife diese Kreatur an', 'Lauf dorthin' oder 'Hole diesen Gegenstand'. Wenn die Kreatur den Befehl erfüllt hat und keine weiteren Anweisungen von dir erhält, verteidigt sie sich und versucht nach Kräften, am Leben zu bleiben.","Du kannst eine Aktion verwenden, um vollständige und präzise Kontrolle über das Ziel zu erlangen. Bis zum Ende deines nächsten Zugs führt die Kreatur nur Aktionen deiner Wahl aus und tut nichts, was du ihr nicht erlaubst. Währenddessen kannst du die Kreatur auch reagieren lassen, allerdings musst du dafür deine eigene Reaktion verwenden.","Jedes Mal, wenn das Ziel Schaden erleidet, führt es einen neuen Weisheitsrettungswurf gegen den Zauber aus. Ist der Rettungswurf erfolgreich, endet der Zauber."],"higher":["Wirkst du diesen Zauber, indem du einen Zauberplatz des 9. Grades nutzt, ändert sich die Wirkungsdauer zu: Konzentration, bis zu 8 Stunden."]},
  {"id":"glibness","name":"Redegewandtheit","en":"Glibness","level":8,"school":"transmutation","classes":["barde","hexenmeister"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V","duration":"1 Stunde","conc":false,"ritual":false,"desc":["Bis der Zauber endet, kannst du das Würfelergebnis deiner Charismawürfe durch eine 15 ersetzen. Magie, die feststellt, ob du die Wahrheit sagst, zeigt immer an, dass du die Wahrheit sagst - egal, was du in Wirklichkeit von dir gibst."]},
  {"id":"feeblemind","name":"Schwachsinn","en":"Feeblemind","level":8,"school":"enchantment","classes":["barde","druide","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"int","damage":{"type":"psychic","slots":{"8":"4d6"}},"desc":["Du attackierst den Verstand einer Kreatur in Reichweite, die du sehen kannst, und versuchst, ihren Intellekt und ihre Persönlichkeit zu brechen. Das Ziel erleidet 4W6 psychischen Schaden und muss einen Intelligenzrettungswurf ausführen.","Scheitert der Wurf, fallen der Intelligenz- und der Charismawert der Kreatur auf 1. Die Kreatur kann keine Zauber wirken, keine magischen Gegenstände aktivieren, versteht keine Sprache und kann nicht verständlich kommunizieren. Sie kann jedoch ihre Freunde erkennen, ihnen folgen und sie sogar beschützen.","Nach jeweils 30 Tagen kann die Kreatur den Rettungswurf gegen den Zauber wiederholen. Ist der Rettungswurf erfolgreich, endet der Zauber.","Der Zauber kann zudem durch Heilung, Vollständige Genesung oder Wunsch aufgehoben werden."]},
  {"id":"sunburst","name":"Sonnenfeuer","en":"Sunburst","level":8,"school":"evocation","classes":["druide","zauberer","magier"],"time":"1 Aktion","action":"action","range":"45 m","rangeKind":"dist","rangeM":45,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"save":"con","damage":{"type":"radiant","slots":{"8":"12d6"}},"area":{"shape":"cylinder","size":18},"desc":["Gleißendes Sonnenlicht erfüllt einen Radius von 18 Metern, der um einen Punkt deiner Wahl in Reichweite zentriert ist. Jede Kreatur in diesem Licht muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 12W6 gleißenden Schaden und ist eine Minute lang blind. Bei einem erfolgreichen Rettungswurf erleidet sie halb so viel Schaden und wird nicht blind. Untote und Schlicke sind bei diesem Rettungswurf im Nachteil.","Eine von diesem Zauber geblendete Kreatur führt am Ende jedes ihrer Züge einen weiteren Konstitutionsrettungswurf aus. Bei einem erfolgreichen Rettungswurf ist sie nicht mehr blind.","Dieser Zauber bannt jede Dunkelheit in der Umgebung, die von einem Zauber erschaffen wurde."]},
  {"id":"animal-shapes","name":"Tierform","en":"Animal Shapes","level":8,"school":"transmutation","classes":["druide"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G","duration":"Konzentration, bis zu 24 Stunden","conc":true,"ritual":false,"desc":["Deine Magie verwandelt andere in Tiere. Wähle eine beliebige Anzahl bereitwilliger Kreaturen in Reichweite, die du sehen kannst. Du verwandelst jedes Ziel in die Gestalt eines maximal großen Tieres mit maximal Herausforderungsgrad 4. In darauffolgenden Zügen kannst du mit deiner Aktion betroffene Kreaturen in neue Gestalten verwandeln.","Die Verwandlung hält für jedes Ziel bis zum Ende der Wirkungsdauer an, oder bis seine Trefferpunkte auf 0 fallen oder es stirbt. Du kannst für jedes Ziel eine andere Gestalt wählen. Die Werte eines Ziels werden durch die Werte des gewählten Tiers ersetzt Das Ziel behält jedoch seine Gesinnung, sowie seine Intelligenz-, Weisheit- und Charismawerte. Das Ziel erhält die Trefferpunkte seiner neuen Gestalt. Nimmt es wieder seine ursprüngliche Gestalt an, besitzt es die gleichen Trefferpunkte wie vor der Verwandlung. Findet die Rückverwandlung statt, weil die Trefferpunkte des Ziels auf 0 sinken, wird überschüssiger Schaden auf seine ursprüngliche Gestalt übertragen. Sofern dieser überschüssige Schaden die ursprüngliche Gestalt der Kreatur nicht auf 0 Trefferpunkte reduziert, wird sie nicht bewusstlos. Die Kreatur kann nur Aktionen durchfuhren, die in ihrer neuen Gestalt möglich sind. Sie kann weder sprechen noch Zauber wirken.","Die Ausrüstung des Ziels verschmilzt mit seiner neuen Gestalt. Das Ziel kann seine Ausrüstung nicht aktivieren oder nutzen."]},
  {"id":"control-weather","name":"Wetterkontrolle","en":"Control Weather","level":8,"school":"transmutation","classes":["kleriker","druide","magier"],"time":"10 Minuten","action":"long","range":"Selbst (Radius von 8 km)","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 8 Stunden","conc":true,"ritual":false,"desc":["Für die Wirkungsdauer kontrollierst du das Wetter im Umkreis von acht Kilometern. Du musst dich im Freien befinden, um diesen Zauber zu wirken. Wenn du keine freie Sicht mehr zum Himmel hast, endet der Zauber vorzeitig.","Wenn du den Zauber wirkst, änderst du die aktuellen Wetterbedingungen, die vom SL je nach Klima und Jahreszeit bestimmt werden. Du kannst Niederschlag, Temperatur und Wind beeinflussen. Es dauert 1W4 mal zehn Minuten, bis die neuen Bedingungen in Kraft treten. Danach kannst du die Bedingungen erneut ändern. Wenn der Zauber endet, normalisiert sich das Wetter allmählich.","Finde zum Ändern des Wetters eine aktuelle Wetterbedingung in der folgenden Tabelle und ändere sie eine Stufe nach oben oder unten. Wenn du den Wind änderst, kannst du auch seine Richtung festlegen."]},
  {"id":"power-word-stun","name":"Wort der Macht: Betäubung","en":"Power Word Stun","level":8,"school":"enchantment","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du sprichst ein Wort der Macht, das den Verstand einer Kreatur in Reichweite, die du sehen kannst, überwältigt. Wenn die gewählte Kreatur maximal 150 Trefferpunkte hat, wird sie betäubt. Anderenfalls hat der Zauber keine Wirkung.","Am Ende jedes seiner Züge muss das Ziel einen Konstitutionsrettungswurf ausführen. Bei einem erfolgreichen Rettungswurf endet dieser Betäubungseffekt."]},
  {"id":"astral-projection","name":"Astrale Projektion","en":"Astral Projection","level":9,"school":"necromancy","classes":["kleriker","hexenmeister","magier"],"time":"1 Stunde","action":"long","range":"3 m","rangeKind":"dist","rangeM":3,"comps":"V, G, M","duration":"Besonders","conc":false,"ritual":false,"desc":["Durch diesen Zauber projiziert du und bis zu acht bereitwillige Kreaturen in Reichweite den jeweiligen Astralkörper auf die Astralebene. Der Zauber schlägt fehl und das Wirken ist vergeudet, wenn du dich bereits auf dieser Ebene befindest. Dabei lässt du deinen physischen Körper bewusstlos und in einem scheintoten Zustand zurück. Er benötigt weder Nahrung noch Luft und altert nicht.","Dein Astralkörper ähnelt deiner sterblichen Form in fast jeder Hinsicht und hat auch deren Spiel werte und deine Habseligkeiten. Der Hauptunterschied ist eine Silberschnur, die zwischen deinen Schulterblättern entspringt und nach 30 Zentimetern unsichtbar wird. Diese Schnur ist deine Verbindung zu deinem materiellen Körper. Solange die Schnur intakt bleibt, findest du den Weg nach Hause. Wird die Schnur durchtrennt - was nur geschieht, wenn ein Effekt dies explizit erwähnt - werden deine Seele und dein Körper getrennt, was dich sofort tötet.","Deine Astralform kann sich frei durch die Astralebene bewegen und dort durch Portale gehen, die zu einer beliebigen anderen Ebene führen. Wenn du eine neue Ebene betrittst oder zu der Ebene zurückkehrst, auf der du dich beim Wirken des Zaubers befunden hast, werden dein Körper und deine Habseligkeiten an der Silberschnur entlang transportiert, so dass du dich beim Betreten der neuen Ebene wieder in deinem Körper befindest. Eine Astralform stellt eine eigenständige Inkarnation dar. Jeglicher Schaden und andere Effekte auf deine Astralform haben keinen Effekt auf deinen physischen Körper und bleiben auch nicht bestehen, wenn du in ihn zurückkehrst.","Der Zauber endet für dich und deine Gefährten, wenn du ihn als Aktion aufhebst. Wenn der Zauber endet, kehrt die betroffene Kreatur in ihren Körper zurück und wacht auf.","Der Zauber kann auch für dich oder einen deiner Gefährten frühzeitig enden. Ein erfolgreiches Magie bannen gegen einen Astralkörper oder physischen Körper beendet den Zauber für diese Kreatur. Wenn die Trefferpunkte des Körpers oder der Astralform einer Kreatur auf 0 fallen, endet der Zauber für diese Kreatur. Wenn der Zauber endet und die Silberschnur intakt ist, zieht sie die Astralform der Kreatur zurück in ihren Körper und beendet den scheintoten Zustand.","Wenn du vorzeitig zu deinem Körper zurückkehrst, bleiben deine Gefährten in ihrer Astralform und müssen ihren eigenen Weg zurück zu ihren Körpern finden. Normalerweise geschieht das, indem ihre Trefferpunkte auf 0 sinken."]},
  {"id":"imprisonment","name":"Einkerkerung","en":"Imprisonment","level":9,"school":"abjuration","classes":["hexenmeister","magier"],"time":"1 Minute","action":"long","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Bis der Zauber gebannt wird","conc":false,"ritual":false,"save":"wis","desc":["Du erschaffst magische Fesseln, um eine Kreatur in Reichweite festzuhalten, die du sehen kannst. Das Ziel muss einen Weisheitsrettungswurf bestehen oder es wird von dem Zauber gebunden. Ist der Rettungswurf erfolgreich, ist es gegen den Zauber immun, wenn du ihn erneut wirkst. Während sie von diesem Zauber betroffen ist, muss die Kreatur nicht atmen, essen oder trinken und altert nicht. Erkenntniszauber können das Ziel weder orten noch wahrnehmen.","Wenn du diesen Zauber wirkst, wähle eine der folgenden Arten der Einkerkerung:","Abgesichertes Gefängnis: Der Zauber transportiert das Ziel zu einer winzigen Halbebene, die gegen Teleportation und Ebenenreisen geschützt ist. Bei der Halbebene kann es sich um ein Labyrinth, einen Käfig, einen Turm oder eine ähnliche geschlossene Struktur oder einen Bereich deiner Wahl handeln.","Die besondere Komponente für diese Version des Zaubers ist eine kleine Abbildung des Gefängnisses aus Jade.","Anketten: Schwere Ketten, die fest im Boden verankert sind, halten das Ziel fest. Das Ziel ist bis zum Ende des Zaubers festgesetzt und kann sich bis dahin weder bewegen noch auf irgendeine Art bewegt werden.","Die besondere Komponente für diese Version des Zaubers ist eine dünne Kette aus Edelmetall.","Begräbnis: Das Ziel wird tief unter der Erde in einer Sphäre aus magischer Energie begraben, die gerade groß genug für das Ziel ist. Nichts kann die Sphäre durchdringen und keine Kreatur kann durch Teleportation oder Ebenenreisen in die Sphäre hinein- oder herausreisen.","Die besondere Komponente für diese Version des Zaubers ist eine kleine Mithralkugel.","Schlummer: Das Ziel schläft ein und kann nicht aufgeweckt werden. Die besondere Komponente für diese Version des Zaubers besteht aus seltenen, einschläfernden Kräutern.","Winziges Gefängnis: Das Ziel schrumpft auf eine Größe von 2,5 Zentimetern und wird in einem Edelstein oder einem ähnlichen Gegenstand eingesperrt. Licht kann den Edelstein normal durchdringen und ermöglicht es dem Ziel somit, nach draußen und anderen Kreaturen ins Innere zu sehen. Ansonsten kann ihn jedoch nichts durchdringen, nicht einmal Teleportation oder Ebenenreisen. Der Edelstein kann nicht geschliffen oder zerbrochen werden, solange der Zauber anhält","Die besondere Komponente für diese Version des Zaubers ist ein großer, transparenter Edelstein wie ein Diamant, Korund oder Rubin.","Den Zauber beenden: Während du eine beliebige Version des Zaubers wirkst, kannst du eine Bedingung festlegen, die den Zauber beendet und das Ziel befreit. Die Bedingung kann so spezifisch oder komplex sein, wie du möchtest. Der SL muss jedoch zustimmen, dass sie vernünftig und ihr Eintreten möglich ist. Die Bedingung kann vom Namen, der Identität oder der Gottheit einer Kreatur abhängen, muss aber auf beobachtbaren Handlungen oder Eigenschaften basieren und nicht auf immateriellen Konzepten wie Stufen, Klassen oder Trefferpunkten.","Der Zauber Magie bannen kann den Zauber nur beenden, wenn er als Zauber des 9. Grades gewirkt wird und entweder das Gefängnis oder die besondere Komponente als Ziel hat.","Du kannst eine besondere Komponente nur verwenden, um ein Gefängnis pro Komponente zu erschaffen. Wirkst du den Zauber erneut mit derselben Komponente, wird das Ziel des ersten Zaubers sofort aus der Einkerkerung befreit."]},
  {"id":"shapechange","name":"Gestaltwandel","en":"Shapechange","level":9,"school":"transmutation","classes":["druide","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"desc":["Für die Wirkungsdauer nimmst du die Gestalt einer anderen Kreatur an. Dabei kann es sich um eine beliebige Kreatur handeln, deren Herausforderungsgrad maximal deiner Stufe entspricht. Es darf sich weder um ein Konstrukt noch um einen Untoten handeln. Zudem musst du diese Art von Kreatur mindestens einmal gesehen haben. Du verwandelst dich ein durchschnittliches Exemplar dieser Kreatur, ohne Klassenstufen oder das Merkmal 'Zauberwirken'.","Deine Spielwerte werden durch die Werte der gewählten Kreatur ersetzt, du behältst jedoch deine Gesinnung, sowie deine Intelligenz-, Weisheits- und Charismawerte. Du bist weiterhin in deinen Fertigkeiten und Rettungswürfen geübt und darüber hinaus in denen der Kreatur. Sollte es zu Überschneidungen kommen und die Kreatur einen höheren Übungsbonus aufweisen, benutzt du diesen statt deinem. Du kannst keine legendären Aktionen und Hortaktionen der neuen Gestalt ausführen.","Du übernimmst die Trefferpunkte und Trefferwürfel der neuen Gestalt. Nimmst du wieder deine normale Gestalt an, hast du so viele Trefferpunkte wie vor der Verwandlung. Solltest du dich zurückverwandeln, weil du auf 0 Trefferpunkte sinkst, wird der überschüssige Schaden auf deine normale Gestalt übertragen. Solange der überschüssige Schaden dich in deiner normalen Gestalt nicht auf 0 Trefferpunkte sinken lässt, wirst du nicht bewusstlos.","Du behältst alle Vorzüge deiner Klasse, deines Volkes oder anderer Quellen und kannst sie anwenden, falls deine neue Gestalt körperlich dazu in der Lage ist. Spezialsinne wie Dunkelsicht kannst du aber nur nutzen, wenn deine neue Gestalt ebenfalls darüber verfügt. Du kannst nur sprechen, wenn die Kreatur normalerweise ebenfalls sprechen kann.","Bei der Verwandlung entscheidest du, ob deine Ausrüstung zu Boden fällt, mit deiner neuen Gestalt verschmilzt oder von ihr getragen wird. Getragene Ausrüstung kann normal verwendet werden. Der SL entscheidet abhängig von der Größe und Gestalt der Kreatur, ob sie eine bestimmte Ausrüstung tragen kann. Deine Ausrüstung verändert weder Größe noch Form, um sich an die neue Gestalt anzupassen. Ausrüstung, die in der neuen Gestalt nicht getragen werden kann, muss entweder zu Boden fallen oder damit verschmelzen. Verschmolzene Ausrüstung hat in dieser Form keinen Effekt.","Während der Wirkungsdauer kannst du als Aktion eine neue Gestalt annehmen, wobei dieselben Einschränkungen und Regeln der ursprünglichen Gestalt gelten, mit einer Ausnahme: Wenn die neue Gestalt mehr Trefferpunkte als deine aktuelle Gestalt besitzt, bleiben deine Trefferpunkte bei ihrem aktuellen Wert."]},
  {"id":"mass-heal","name":"Massen-Heilung","en":"Mass Heal","level":9,"school":"evocation","classes":["kleriker"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"heal":{"slots":{"9":"700"}},"desc":["Eine Flut aus heilender Energie strömt von dir zu verletzten Kreaturen um dich herum. Du stellst bis zu 700 Trefferpunkte wieder her, die du auf eine beliebige Anzahl an Kreaturen in Reichweite aufteilen kannst, die du sehen kannst. Kreaturen, die von diesem Zauber geheilt werden, werden auch von sämtlichen Krankheiten befreit, sowie von Effekten, die sie blind oder taub machen. Dieser Zauber wirkt nicht auf Untote oder Konstrukte."]},
  {"id":"meteor-swarm","name":"Meteoritenschwarm","en":"Meteor Swarm","level":9,"school":"evocation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"1,6 km","rangeKind":"dist","rangeM":1600,"comps":"V, G","duration":"Unmittelbar","conc":false,"ritual":false,"save":"dex","damage":{"type":"fire","slots":{"9":"20d6"}},"area":{"shape":"sphere","size":12},"desc":["Lodernde Feuerkugeln stürzen an vier verschiedenen Punkten in Reichweite zu Boden, die du sehen kannst Jede Kreatur in einer Sphäre mit einem Radius von zwölf Metern um jeden gewählten Punkt muss einen Geschicklichkeitsrettungswurf ausführen. Die Sphäre breitet sich um Ecken aus. Scheitert der Wurf, erleidet die Kreatur 20W6 Feuerschaden und 20W6 Wuchtschaden, anderenfalls die Hälfte. Kreaturen im Wirkungsbereich von mehr als einem feurigen Ausbruch sind nur einmal betroffen.","Der Zauber verursacht Schaden bei Gegenständen in der Umgebung und entzündet brennbare Gegenstände, die nicht getragen oder gehalten werden."]},
  {"id":"prismatic-wall","name":"Regenbogenwand","en":"Prismatic Wall","level":9,"school":"abjuration","classes":["magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G","duration":"10 Minuten","conc":false,"ritual":false,"area":{"shape":"line","size":27,"width":1.5},"desc":["Schimmerndes, buntes Licht bildet eine vertikale, undurchsichtige Wand, die auf einen Punkt in Reichweite zentriert ist, den du sehen kannst.","Die Wand ist bis zu 27 Meter lang, neun Meter hoch und 2,5 Zentimeter dick. Alternativ kannst du die Wand in eine Sphäre mit bis zu neun Metern Durchmesser formen, die auf einem Punkt deiner Wahl in Reichweite zentriert ist. Die Wand bleibt für die Wirkungsdauer bestehen. Platzierst du die Wand so, dass sie durch den von einer Kreatur besetzten Bereich verläuft, schlägt der Zauber fehl und deine Aktion und der Zauberplatz sind vergeudet","Die Wand verströmt helles Licht bis zu einer Reichweite von 30 Metern und dämmriges Licht für weitere 30 Meter. Du und Kreaturen, die du beim Wirken des Zaubers bestimmst, könnt die Wand durchqueren und sich in ihrer Nähe aufhalten, ohne Schaden zu erleiden. Wenn eine andere Kreatur, die die Wand sehen kann, sich ihr auf sechs Meter nähert oder ihren Zug dort beginnt, muss die Kreatur einen Konstitutionsrettungswurf bestehen, oder sie wird eine Minute lang blind.","Die Wand besteht aus sieben Schichten, jede in einer anderen Farbe. Versucht eine Kreatur, durch die Wand zu greifen oder zu gehen, geschieht dies Schicht für Schicht für alle sieben Schichten der Wand. Für jede Schicht muss die Kreatur einen Geschicklichkeitsrettungswurf ausführen und wird von den unten beschriebenen Eigenschaften dieser Schicht betroffen.","Die Wand kann auch Schicht für Schicht von Rot nach Violett zerstört werden, wobei die Art für jede Schicht anders ist Sobald eine Schicht zerstört wurde, bleibt sie es für die Wirkungsdauer des Zaubers. Eine Rute des Abbruchs zerstört eine Regenbogenwand, ein Antimagisches Feld hat jedoch keinen Effekt."]},
  {"id":"storm-of-vengeance","name":"Sturm der Vergeltung","en":"Storm of Vengeance","level":9,"school":"conjuration","classes":["druide"],"time":"1 Aktion","action":"action","range":"Sicht","rangeKind":"sight","rangeM":null,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"con","damage":{"type":"acid","slots":{"9":"1d6"}},"area":{"shape":"sphere","size":108},"desc":["Eine brodelnde Sturmwolke bildet sich zentriert auf einen Punkt, den du sehen kannst, und breitet sich auf einen Radius von 110 Metern aus. Blitze zucken in dem Bereich herab, Donner grollt und starke Winde heulen. Jede Kreatur, die sich beim Erscheinen der Wolke maximal 1,5 Kilometer darunter befindet, muss einen Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 2 W6 Schallschaden und ist fünf Minuten lang taub.","In jeder Runde, in der du dich auf diesen Zauber konzentrierst, erzeugt der Sturm in deinem Zug einen zusätzlichen Effekt.","Runde 2: Säureregen regnet aus der Wolke. Jede Kreatur und jeder Gegenstand unter der Wolke erleidet 1W6 Säureschaden.","Runde 3: Du rufst sechs Blitze aus der Wolke hervor, die sechs Kreaturen oder Gegenstände deiner Wahl unter der Wolke treffen. Jedes Ziel kann nur von maximal einem Blitz getroffen werden. Eine getroffene Kreatur muss einen Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 10W6 Blitzschaden, anderenfalls die Hälfte.","Runde 4: Hagelkörner regnen aus der Wolke herab. Jede Kreatur unter der Wolke erleidet 2 W6 Wuchtschaden.","Runde 5-10: Windstöße und Eisregen fegen durch den Bereich unter der Wolke. Der Bereich wird zu schwierigem Gelände und ist komplett verschleiert. Jede Kreatur im Bereich erleidet 1W6 Kälteschaden. Fernkampfwaffenangriffe sind in diesem Bereich unmöglich. Wind und Regen stellen eine starke Ablenkung dar, wenn sich eine Kreatur auf einen Zauber konzentrieren will. Außerdem zerstreuen starke Winde (die zwischen 32 bis 80 Kilometer pro Stunde erreichen) automatisch Nebel, Dunst und ähnliche Effekte in dem Bereich, egal ob sie magischer Natur sind oder nicht."]},
  {"id":"gate","name":"Tor","en":"Gate","level":9,"school":"conjuration","classes":["kleriker","zauberer","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"desc":["Du beschwörst ein Portal, das eine freie Stelle in Reichweite, die du sehen kannst, mit einem bestimmten Ort auf einer anderen Existenzebene verbindet. Bei dem Portal handelt es sich um eine kreisrunde Öffnung mit einem Durchmesser von 1,5 bis sechs Metern. Du kannst das Portal in jede beliebige Richtung ausrichten. Es bleibt für die Wirkungsdauer bestehen.","Das Portal hat auf beiden Ebenen eine Vorder-und eine Rückseite. Reisen durch das Portal sind nur durch die Vorderseite möglich. Alles, was das Portal passiert, wird sofort auf die andere Ebene transportiert und erscheint an einer freien Stelle, die dem Portal am nächsten liegt.","Gottheiten und andere Herrscher über die Ebenen können verhindern, dass sich Portale dieses Zaubers in ihrer Gegenwart oder in ihren Domänen öffnen.","Wenn du diesen Zauber wirkst, kannst du den Namen einer bestimmten Kreatur aussprechen (ein Pseudonym, Titel oder Spitzname funktioniert nicht). Befindet sich die Kreatur auf einer anderen Ebene als du, öffnet sich das Portal in unmittelbarer Nähe der genannten Kreatur und zieht sie durch das Portal an die nächstgelegene freie Stelle auf deiner Seite des Portals. Du erlangst keine besondere Macht über die Kreatur und sie handelt nach Ermessen des SL. Sie kann verschwinden, dich angreifen oder dir helfen."]},
  {"id":"weird","name":"Unheimliches Schicksal","en":"Weird","level":9,"school":"illusion","classes":["magier"],"time":"1 Aktion","action":"action","range":"36 m","rangeKind":"dist","rangeM":36,"comps":"V, G","duration":"Konzentration, bis zu 1 Minute","conc":true,"ritual":false,"save":"wis","damage":{"type":"psychic","slots":{"9":"4d10"}},"area":{"shape":"sphere","size":9},"desc":["Du schöpfst aus den tiefsten Ängsten einer Gruppe von Kreaturen und erschaffst illusionäre Monster in ihren Köpfen, die nur für sie sichtbar sind. Jede Kreatur in einer Sphäre mit einem Radius von neun Metern, die um einen Punkt deiner Wahl in Reichweite zentriert ist, muss einen Weisheitsrettungswurf ausführen. Scheitert der Wurf, ist die Kreatur für die Wirkungsdauer verängstigt Die Illusion manifestiert die schlimmsten Albträume einer Kreatur als unerbittliche Bedrohung. Am Ende jedes ihrer Züge muss die verängstigte Kreatur einen Weisheitsrettungswurf bestehen, oder sie erleidet 4W10 psychischen Schaden.","Bei einem Erfolg endet der Zauber für diese Kreatur."]},
  {"id":"foresight","name":"Voraussicht","en":"Foresight","level":9,"school":"divination","classes":["barde","druide","hexenmeister","magier"],"time":"1 Minute","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"8 Stunden","conc":false,"ritual":false,"desc":["Du berührst eine bereitwillige Kreatur und verleihst ihr die eingeschränkte Fähigkeit, in die unmittelbare Zukunft zu blicken. Für die Wirkungsdauer kann das Ziel nicht überrascht werden und ist bei Angriffs-, Attributs- und Rettungswürfen im Vorteil. Zudem sind andere Kreaturen für die Wirkungsdauer bei Angriffswürfen gegen das Ziel im Nachteil.","Der Zauber endet sofort, wenn du ihn vor Ablauf der Wirkungsdauer erneut wirkst."]},
  {"id":"true-resurrection","name":"Wahre Auferstehung","en":"True Resurrection","level":9,"school":"necromancy","classes":["kleriker","druide"],"time":"1 Stunde","action":"long","range":"Berührung","rangeKind":"touch","rangeM":1.5,"comps":"V, G, M","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du berührst eine tote Kreatur. Ihr Tod darf maximal 200 Jahre zurückliegen und sie darf nicht an Altersschwäche gestorben sein. Ist die Seele der Kreatur frei und bereitwillig, wird sie mit all ihren Trefferpunkten wieder zum Leben erweckt.","Dieser Zauber schließt alle Wunden, neutralisiert jedes Gift, heilt alle Krankheiten und bannt sämtliche Flüche, unter denen die Kreatur zum Zeitpunkt ihres Todes gelitten hat. Der Zauber ersetzt beschädigte oder fehlende Organe und Gliedmaßen.","Der Zauber kann sogar einen neuen Körper erschaffen, wenn der ursprüngliche Körper nicht mehr existiert. In diesem Fall musst du den Namen der Kreatur aussprechen. Sie erscheint dann an einer freien Stelle deiner Wahl im Abstand von bis zu drei Metern von dir."]},
  {"id":"true-polymorph","name":"Wahre Verwandlung","en":"True Polymorph","level":9,"school":"transmutation","classes":["barde","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"9 m","rangeKind":"dist","rangeM":9,"comps":"V, G, M","duration":"Konzentration, bis zu 1 Stunde","conc":true,"ritual":false,"save":"cha","desc":["Wähle eine Kreatur oder einen nichtmagischen Gegenstand in Reichweite, die oder den du sehen kannst. Du verwandelst die Kreatur in eine andere Kreatur, die Kreatur in einen Gegenstand oder den Gegenstand in eine Kreatur. Der Gegenstand darf von keiner anderen Kreatur getragen oder gehalten werden. Die Verwandlungszauber hält bis zum Ende der Wirkungsdauer an, oder bis die Trefferpunkte des Ziels auf 0 fallen oder es stirbt. Konzentrierst du dich für die gesamte Wirkungsdauer auf den Zauber, hält die Verwandlung an, bis sie gebannt wird.","Dieser Zauber wirkt nicht auf Gestaltwandler oder auf Kreaturen mit 0 Trefferpunkten. Eine unwillige Kreatur kann einen Charismarettungswurf ausführen. Bei einem Erfolg wird sie nicht von diesem Zauber betroffen.","Kreatur in Kreatur: Verwandelst du eine Kreatur in eine andere Kreatur, kannst du eine beliebige Gestalt wählen, solange deren Herausforderungsgrad gleich oder niedriger ist als der des Ziels (wenn das Ziel keinen Herausforderungsgrad hat, verwende seine Stufe). Die Spielwerte des Ziels, inklusive mentaler Attributswerte, werden durch die Werte der neuen Gestalt ersetzt. Es behält seine Gesinnung und Persönlichkeit.","Das Ziel erhält die Trefferpunkte seiner neuen Gestalt. Nimmt es wieder seine ursprüngliche Gestalt an, besitzt es die gleichen Trefferpunkte wie vor der Verwandlung. Findet die Rückverwandlung statt, weil die Trefferpunkte des Ziels auf 0 sinken, wird überschüssiger Schaden auf seine ursprüngliche Gestalt übertragen. Sofern dieser überschüssige Schaden die ursprüngliche Gestalt der Kreatur nicht auf 0 Trefferpunkte reduziert, wird sie nicht bewusstlos.","Die Kreatur kann nur Aktionen durchführen, die in ihrer neuen Gestalt möglich sind. Sie kann nicht sprechen, Zauber wirken oder andere Aktionen ausführen, die Hände oder Sprache erfordern, es sei denn, ihre neue Gestalt ist dazu in der Lage.","Die Ausrüstung des Ziels verschmilzt mit seiner neuen Gestalt Es kann die Ausrüstung nicht aktivieren, verwenden, führen oder anderweitig nutzen.","Gegenstand in Kreatur: Du kannst einen Gegenstand in eine beliebige Kreatur verwandeln, solange die Kreatur nicht größer als der Gegenstand ist und der Herausforderungsgrad der Kreatur maximal 9 beträgt. Die Kreatur ist dir und deinen Verbündeten gegenüber freundlich gesinnt. Sie handelt in jedem deiner Züge. Du entscheidest, welche Aktion sie ausführt und wie sie sich bewegt. Der SL hat die Spielwerte der Kreatur und führt ihre Aktionen und Bewegungen aus.","Wird der Zauber dauerhaft, kontrollierst du die Kreatur nicht mehr. Sie kann dir freundlich gesinnt bleiben, je nachdem, wie du sie behandelt hast.","Kreatur in Gegenstand: Verwandelst du eine Kreatur in einen Gegenstand, verwandelt sie sich mit allem, was sie trägt und in der Hand hält. Die Spielwerte der Kreatur werden zu denen des Gegenstands. Wenn der Zauber endet und das Ziel wieder seine normale Form annimmt, besitzt es keine Erinnerungen an die Zeit, die es als Gegenstand verbracht hat."]},
  {"id":"power-word-kill","name":"Wort der Macht: Tod","en":"Power Word Kill","level":9,"school":"enchantment","classes":["barde","zauberer","hexenmeister","magier"],"time":"1 Aktion","action":"action","range":"18 m","rangeKind":"dist","rangeM":18,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du sprichst ein Wort der Macht, das eine Kreatur in Reichweite, die du sehen kannst, sofort tötet. Wenn die gewählte Kreatur maximal 100 Trefferpunkte hat, stirbt sie. Anderenfalls hat der Zauber keine Wirkung."]},
  {"id":"wish","name":"Wunsch","en":"Wish","level":9,"school":"conjuration","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"damage":{"type":"necrotic","slots":{"9":"1d10"}},"desc":["Wunsch ist der mächtigste Zauber, den eine sterbliche Kreatur wirken kann. Indem du deinen Willen laut aussprichst, kannst du das Fundament der Realität im Einklang mit deinen Wünschen verändern.","Als grundlegende Verwendung dieses Zaubers kannst du einen beliebigen anderen Zauber des maximal 8. Grades kopieren. Du musst weder dessen Voraussetzungen erfüllen noch teure Materialkomponenten bezahlen. Der Zauber tritt einfach in Kraft.","Alternativ kannst du einen der folgenden Effekte erzeugen:","Du kannst auch etwas erreichen, das über die oben genannten Beispiele hinausgeht. Beschreibe dem SL deinen Wunsch so genau wie möglich. Der SL hat einigen Spielraum bei der Entscheidung, was in einem solchen Fall geschieht. Je größer der Wunsch ist, desto wahrscheinlicher ist es, dass etwas schief geht. Der Zauber könnte einfach fehlschlagen, der gewünschte Effekt nur zum Teil erfüllt werden oder du selbst eine unvorhersehbare Nebenwirkung erleiden, die von deiner Formulierung des Wunsches abhängt. Wenn du dir beispielsweise wünschst, dass ein Bösewicht tot wäre, könntest du in eine Zukunft katapultiert werden, in der der Schurke nicht mehr am Leben ist - wodurch du praktisch aus dem Spiel entfernt wirst. Wünscht du dir einen legendären magischen Gegenstand oder ein Artefakt, könntest du zum aktuellen Besitzer des Gegenstands teleportiert werden.","Mit diesem Zauber einen anderen Effekt zu erzielen, als einen Zauber zu kopieren, belastet dich stark. Jedes Mal, wenn du nach dieser Belastung einen Zauber wirkst, erleidest du 1W10 nekrotischen Schaden pro Grad des Zaubers. Dieser Effekt verschwindet nach einer langen Rast. Dieser Schaden kann nicht verringert oder verhindert werden. Zudem fällt deine Stärke 2W4 Tage lang auf 3, wenn sie nicht bereits 3 oder weniger beträgt. Für jeden dieser Tage, an dem du dich nur ausruhst oder leichten Tätigkeiten nachgehst, verringerst du die übrige Erholungszeit um 2 Tage. Zuletzt besteht eine Chance von 33 Prozent, dass du Wunsch aufgrund dieser Belastung niemals erneut wirken kannst."]},
  {"id":"time-stop","name":"Zeitstopp","en":"Time Stop","level":9,"school":"transmutation","classes":["zauberer","magier"],"time":"1 Aktion","action":"action","range":"Selbst","rangeKind":"self","rangeM":0,"comps":"V","duration":"Unmittelbar","conc":false,"ritual":false,"desc":["Du stoppst kurzzeitig den Fluss der Zeit für alle außer dir selbst. Für andere Kreaturen vergeht keine Zeit, während du 1W4+1 Züge hintereinander bekommst, in denen du wie gewohnt Aktionen ausführen und dich bewegen kannst.","Dieser Zauber endet, wenn eine deiner Aktionen oder ein von dir erschaffener Effekt während dieser Zeitspanne eine Kreatur außer dir selbst oder einen Gegenstand beeinflusst, den jemand anderes außer dir trägt. Zudem endet der Zauber, wenn du dich mehr als 300 Meter von dem Ort entfernst, an dem du ihn gewirkt hast."]},
];
